# Rate limiting storage
rate_limits: dict[str, list[float]] = defaultdict(list)
_rate_limits_last_prune = 0.0

# App-wide IP blocking — {ip: expires_at_iso_or_None}, loaded at startup from
# blocked_ips and kept in sync in-process so the middleware check on every
# request never touches the database.
_blocked_ips: dict[str, Optional[str]] = {}
# The addresses in _blocked_ips that were put there by an automatic (login or probe) ban. Only
# these are skipped at request time when the address has since become exempt; a manual block
# is always enforced.
_auto_blocked_ips: set[str] = set()


def _is_ip_blocked(ip: str) -> bool:
    """Check the in-process blocked-IP cache. Lazily evicts expired entries.

    The cache is keyed by canonical address (ipguard.canonical_ip); the lookup
    folds the caller's address the same way, but only when something is blocked.
    """
    if not _blocked_ips:
        return False
    if ip not in _blocked_ips:
        ip = ipguard.canonical_ip(ip) or ip
        if ip not in _blocked_ips:
            return False
    expires_at = _blocked_ips[ip]
    if expires_at is None:
        return True
    try:
        if datetime.now(timezone.utc) < datetime.fromisoformat(expires_at.replace(" ", "T")).replace(tzinfo=timezone.utc):
            return True
    except ValueError:
        return True
    # Expired — evict from cache (DB row is left for the admin's own record; harmless)
    del _blocked_ips[ip]
    return False


# Paths only vulnerability scanners ask for — the portal serves none of them.
_PROBE_PATH_RE = re.compile(
    r"(^|/)\.(env|git|aws|ssh|svn|hg|htpasswd|htaccess|DS_Store)(\b|/|$)"
    r"|\.git-credentials"
    r"|\.(php\d?|aspx?|jsp|cgi)$"
    r"|(^|/)(wp-admin|wp-login|wp-content|wp-includes|phpmyadmin|cgi-bin|vendor/phpunit)(/|$)",
    re.IGNORECASE,
)
# Prefixes that relay to other applications, where such paths can be legitimate.
# User uploads are exempt too: their URLs are user-influenced (chat images).
_PROBE_EXEMPT_PREFIXES = ("/proxy/", "/search/", "/api/", "/static/uploads/")
_PROBE_TABLE_MAX = 20000                            # hard cap per table
_probe_strikes: dict[str, tuple[int, float]] = {}   # ip -> (count, first_seen)
_probe_blocks: dict[str, float] = {}                # ip -> monotonic expiry
_probe_last_prune = 0.0


def _is_local_address(ip: str) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return True
    if addr.version == 6 and addr.ipv4_mapped:
        addr = addr.ipv4_mapped
    return addr.is_loopback or addr.is_private or addr.is_link_local


def _is_scanner_probe(request: web.Request, status: int) -> bool:
    """True for a failed request to a scanner-only path that no browser made.

    Current browsers attach Sec-Fetch-Site to every request they make over
    HTTPS and page script cannot remove it, so requiring its absence means a
    web page, an email or a chat message full of <img> tags cannot make a
    visitor's browser earn strikes (and a block) on that visitor's behalf.
    Safari before 16.4 sends no such header, so image loads (the way a page
    triggers requests without user action) are skipped by Accept as well.
    That exception is best-effort, which is why the feature is opt-in.
    """
    return (
        status in (401, 404, 405)
        and "Sec-Fetch-Site" not in request.headers
        and not request.headers.get("Accept", "").lower().startswith("image/")
        and not request.path.startswith(_PROBE_EXEMPT_PREFIXES)
        and _PROBE_PATH_RE.search(request.path) is not None
    )


def _is_probe_blocked(ip: str) -> bool:
    expires = _probe_blocks.get(ip)
    if expires is None:
        return False
    if monotonic() < expires:
        return True
    del _probe_blocks[ip]
    return False


def _record_probe(ip: str, path: str, user_agent: Optional[str] = None) -> None:
    """Count a scanner-style request; block the client once it repeats."""
    global _probe_last_prune
    # Never block the proxies themselves, local callers, this server's own
    # addresses or anything on a never-ban list: media-server hooks, link
    # previews and tunnelled connections reach the portal from those, and users
    # can aim them at probe-like paths. Every automatic block asks the same
    # helper, _never_ban_reason.
    if Config.PROBE_BLOCK_STRIKES <= 0 or _never_ban_reason(ip) is not None:
        return
    now = monotonic()
    # Sweep expired entries at most once a minute, and cap both tables, so a
    # flood of distinct addresses costs O(1) per request and bounded memory.
    if now - _probe_last_prune > 60 and (len(_probe_strikes) > 5000 or len(_probe_blocks) > 5000):
        _probe_last_prune = now
        for k in [k for k, (_, first) in _probe_strikes.items() if now - first > 600]:
            del _probe_strikes[k]
        for k in [k for k, exp in _probe_blocks.items() if exp <= now]:
            del _probe_blocks[k]
    while len(_probe_strikes) >= _PROBE_TABLE_MAX:
        del _probe_strikes[next(iter(_probe_strikes))]
    while len(_probe_blocks) >= _PROBE_TABLE_MAX:
        del _probe_blocks[next(iter(_probe_blocks))]
    count, first = _probe_strikes.get(ip, (0, now))
    if now - first > 600:
        count, first = 0, now
    count += 1
    if count >= Config.PROBE_BLOCK_STRIKES:
        _probe_strikes.pop(ip, None)
        _probe_blocks[ip] = now + Config.PROBE_BLOCK_SECONDS
        logger.info(
            f"Blocking {ip} for {Config.PROBE_BLOCK_SECONDS}s after repeated scanner probes (last: {path[:80]})"
        )
        security_event_nowait(
            "probe_block", ip=ip, user_agent=user_agent, result="blocked",
            details={"path": path[:80], "seconds": Config.PROBE_BLOCK_SECONDS})
        # Also store it (temporary, longer on a repeat): it then survives a restart.
        _spawn(_persist_probe_ban(ip, path))
    else:
        _probe_strikes[ip] = (count, first)


_CHAT_UPLOAD_URL_RE = re.compile(r"/static/uploads/chat/[A-Za-z0-9._-]+")


def _valid_chat_upload_url(url) -> bool:
    """A chat image/attachment URL must name one file in the chat upload dir."""
    return (
        isinstance(url, str)
        and ".." not in url
        and _CHAT_UPLOAD_URL_RE.fullmatch(url) is not None
    )


def safe_error_message(e: Exception) -> str:
    """Return a safe error message without exposing internal details."""
    error_msg = str(e)
    # Don't expose file paths or internal details
    if '/' in error_msg or '\\' in error_msg:
        return "An internal error occurred"
    # Truncate very long messages
    if len(error_msg) > 200:
        return error_msg[:200] + "..."
    # Allow UNIQUE constraint errors to pass through (helpful for duplicate names)
    if "UNIQUE constraint" in error_msg:
        return "A record with this name or identifier already exists"
    return error_msg


async def read_multipart_part(part, limit: int) -> tuple[bytes, bool]:
    """Read one multipart ``file`` part up to ``limit`` bytes.

    aiohttp's ``BodyPartReader.read()`` takes no size argument in the
    version pinned here — it reads the whole part unconditionally, which
    is exactly what a per-file size cap needs to avoid. Stream it in
    chunks instead and stop as soon as ``limit`` is exceeded.

    Returns ``(data, oversized)`` — ``data`` is truncated at ``limit`` and
    ``oversized`` is True if there was more where that came from.
    """
    buf = bytearray()
    oversized = False
    async for chunk in part:
        buf.extend(chunk)
        if len(buf) > limit:
            oversized = True
            del buf[limit:]
            break
    return bytes(buf), oversized

# Active WebSocket connections for monitoring
active_connections: weakref.WeakSet = weakref.WeakSet()

# Track online users globally (user_id -> active connection count)
_online_users: dict[int, int] = {}

# Open authenticated WebSockets per user: user_id -> {ws: token_id}. A socket is
# authenticated once at upgrade, so revoking a user's sessions must also close
# the sockets that were opened with them.
_user_websockets: dict[int, dict] = {}

# Open WebSockets one user may hold at once (prevents resource exhaustion). The
# generic handler counts its own sockets; the chat handler counts the registry above.
_MAX_WS_PER_USER = 20


def _register_user_ws(user_id: int, ws, token_id: str) -> None:
    _user_websockets.setdefault(user_id, {})[ws] = token_id


async def _credential_still_valid(token) -> bool:
    """True if the credential a socket was opened with is still good: the account
    exists and the session token (or API key) is neither revoked nor expired.

    A socket is registered for revocation (_register_user_ws) and checked here
    afterwards. A revocation that landed before the registration did not see the
    socket, one that lands after it closes the socket itself, and this read
    follows the registration, so it sees any revocation of the first kind.
    """
    try:
        if await db.get_user_by_id(token.user_id) is None:
            return False
        jti = str(token.token_id or "")
        if jti.startswith("streamkey-"):
            return True    # a stream key is not a session; its sockets are only closed with the account
        if jti.startswith("apikey-"):
            key_id = int(jti[len("apikey-"):])
            for key in await db.get_user_api_keys(token.user_id):
                if key["id"] != key_id:
                    continue
                if key.get("revoked"):
                    return False
                exp = key.get("expires_at")
                if exp:
                    try:
                        if datetime.fromisoformat(exp.replace("Z", "+00:00")) < datetime.now(timezone.utc):
                            return False
                    except ValueError:
                        pass
                return True
            return False
        return await db.is_token_valid(jti)
    except Exception:
        logger.warning("could not re-check a WebSocket credential; closing the socket", exc_info=True)
        return False


def _unregister_user_ws(user_id: int, ws) -> None:
    conns = _user_websockets.get(user_id)
    if conns is not None:
        conns.pop(ws, None)
        if not conns:
            _user_websockets.pop(user_id, None)


class _ProxyHttpCall:
    """One in-flight proxied HTTP response (the /proxy path, not its WebSockets).

    Registered for the life of the request so that revoking the member's
    credentials can end it: abort() drops the client connection and the
    upstream response, and `aborted` tells the handler why it stopped.
    """
    __slots__ = ("request", "resp", "aborted", "__weakref__")

    def __init__(self, request):
        self.request = request
        self.resp = None
        self.aborted = False

    def abort(self) -> None:
        self.aborted = True
        transport = self.request.transport
        if transport is not None:
            transport.abort()
        if self.resp is not None:
            self.resp.close()


# Open proxied HTTP responses per user: user_id -> {call: token_id}.
_user_proxy_calls: dict[int, dict] = {}


def _register_user_proxy_call(user_id: int, call: _ProxyHttpCall, token_id: str) -> None:
    _user_proxy_calls.setdefault(user_id, {})[call] = token_id


def _unregister_user_proxy_call(user_id: int, call: _ProxyHttpCall) -> None:
    calls = _user_proxy_calls.get(user_id)
    if calls is not None:
        calls.pop(call, None)
        if not calls:
            _user_proxy_calls.pop(user_id, None)


# What depends on a share or a grant, so that ending it ends them: (kind, resource_id,
# grantee user_id) -> the sockets, proxied HTTP calls and SSH connections opened through
# it. kind is "conn" (a connection share, resource_id = user_connections.id) or "svc"
# (a service grant; nothing is registered under it today because no socket is opened
# through a service grant, the kind exists so a future one is closed by the same sweep).
# Weak references: an entry disappears with the object, nothing has to unregister it.
_grant_dependents: dict = {}

# WebSocket close code for "your access to this connection ended" (expired or revoked),
# distinct from 4001 (session revoked: clients go to /login) and 4003/4004.
GRANT_ENDED_CLOSE_CODE = 4010


def _register_grant_dependent(kind: str, resource_id: int, user_id: int, obj) -> None:
    _grant_dependents.setdefault((kind, int(resource_id), int(user_id)), weakref.WeakSet()).add(obj)


# How long a revoke, a sweep or a user delete waits for the grantee's WebSockets to finish
# their close handshake. A socket whose peer is gone can take ~10 s to give up; the close
# keeps running in the background, the caller is not held for it.
GRANT_CLOSE_WAIT_SECONDS = 2.0
_grant_close_background: set = set()


def _drop_finished_close(task) -> None:
    _grant_close_background.discard(task)
    if not task.cancelled():
        task.exception()        # retrieved so a failed close is not reported as never retrieved


async def _close_grant_targets(targets: list) -> int:
    """Close sockets, proxied calls and SSH connections that depended on a share or grant.
    The synchronous ones go first; the WebSockets are closed concurrently and waited for at
    most GRANT_CLOSE_WAIT_SECONDS in total."""
    sockets = []
    for obj in targets:
        try:
            if isinstance(obj, _ProxyHttpCall):
                obj.abort()
            elif isinstance(obj, (web.WebSocketResponse, MetricsWebSocket)):
                sockets.append(obj)
            else:
                obj.close()     # an SSH connection (asyncssh's close() is synchronous)
        except Exception:
            logger.debug("closing something that depended on a share or grant failed", exc_info=True)
    if sockets:
        tasks = [asyncio.ensure_future(ws.close(code=GRANT_ENDED_CLOSE_CODE, message=b"access ended"))
                 for ws in sockets]
        _, pending = await asyncio.wait(tasks, timeout=GRANT_CLOSE_WAIT_SECONDS)
        for task in tasks:
            if task in pending:
                _grant_close_background.add(task)
            task.add_done_callback(_drop_finished_close)
    return len(targets)


async def close_grant_dependents(kind: str, resource_id: int, user_id: int = None) -> int:
    """End what the grantee holds open through one share or grant (user_id None: through
    every grantee of that resource, for a deleted connection). Other sockets of the user,
    the chat for one, are not touched. Returns how many were closed."""
    keys = [k for k in list(_grant_dependents)
            if k[0] == kind and k[1] == int(resource_id) and (user_id is None or k[2] == int(user_id))]
    targets = []
    for key in keys:
        targets.extend(list(_grant_dependents.pop(key, ())))
    return await _close_grant_targets(targets)


async def close_grant_dependents_for(connection_ids=(), grantee_id: int = None) -> int:
    """End what is open through any share of the given connections (a deleted owner's) and
    whatever the given user holds open as a grantee of any share or grant (a deleted
    account's), in one pass."""
    ids = {int(i) for i in connection_ids}
    keys = [k for k in list(_grant_dependents)
            if (k[0] == "conn" and k[1] in ids) or (grantee_id is not None and k[2] == int(grantee_id))]
    targets = []
    for key in keys:
        targets.extend(list(_grant_dependents.pop(key, ())))
    return await _close_grant_targets(targets)


def _forget_grant_dependent(kind: str, resource_id: int, user_id: int, obj) -> None:
    """Drop one object from its share's dependents (no-op when it was never registered, as for
    an owner's own connection). Used when the object stops being what must be ended: a
    WebSocket upgrade's proxied-call record is replaced by the socket itself."""
    key = (kind, int(resource_id), int(user_id))
    deps = _grant_dependents.get(key)
    if deps is not None:
        deps.discard(obj)
        if not deps:
            _grant_dependents.pop(key, None)


async def _track_shared_access(connection: dict, user_id: int, obj) -> bool:
    """Record that `obj` (a socket, proxied call or SSH connection) was opened through a
    share, then check the share is still live. False means it ended in between (a revoke
    that landed before the registration did not see `obj`): the caller must close it.
    Owner access (no share) is not tracked and always True."""
    if not connection.get("shared"):
        return True
    _register_grant_dependent("conn", connection["id"], user_id, obj)
    return await db.get_accessible_connection(connection["uuid"], user_id) is not None


def _keeps_credential(token_id, except_token_id, keep_prefixes) -> bool:
    return bool((except_token_id and token_id == except_token_id)
                or (keep_prefixes and str(token_id).startswith(keep_prefixes)))


async def close_user_websockets(user_id: int, except_token_id: str = None,
                                keep_prefixes: tuple = (),
                                only_token_id: str = None) -> int:
    """Close a user's open WebSockets, and abort their in-flight proxied HTTP
    responses, after their credentials were revoked.

    except_token_id keeps what was opened with that token (the caller's own
    session). keep_prefixes keeps what was opened with a kind of credential
    that was not revoked (token ids "apikey-N" and "streamkey-N").
    only_token_id ends just what was opened with that one token and keeps
    every other session of the user (a single logout). Returns the number of
    WebSockets closed.
    """
    def _spared(tid) -> bool:
        if only_token_id is not None and tid != only_token_id:
            return True
        return _keeps_credential(tid, except_token_id, keep_prefixes)

    # Cached playback decisions made for this user are dropped whatever was
    # revoked (the next playback request asks again; the cost of dropping the
    # sessions that were kept is one lookup).
    _playback_cache_forget(user_id=user_id)
    _viewers.remove_user_everywhere(user_id)       # not counted as a viewer from now on

    # Proxied HTTP responses (long downloads, event streams) have no total
    # time limit, so they are cut here too.
    for call, tid in list(_user_proxy_calls.get(user_id, {}).items()):
        if not _spared(tid):
            try:
                call.abort()
            except Exception:
                logger.debug("aborting a proxied response failed", exc_info=True)
    targets = [
        ws for ws, tid in list(_user_websockets.get(user_id, {}).items())
        if not _spared(tid)
    ]
    # A revoked session ends its voice call at once, with no reconnect grace,
    # also when the socket is already gone and the call is only being held.
    # Removing the entries before the sockets close keeps the room from seeing a
    # "reconnecting" state (a socket that closes with a live entry holds it for the
    # grace); it is done again after the close, because a socket that was still
    # open could have joined a call in between and that entry would otherwise be held.
    await _voice_revoke_user(user_id, _spared)
    if targets:
        await asyncio.gather(
            *(ws.close(code=4001, message=b"session revoked") for ws in targets),
            return_exceptions=True
        )
        await _voice_revoke_user(user_id, _spared)
    return len(targets)

