async def http_authenticated_upload(request: web.Request) -> web.Response:
    """Serve uploaded files (chat images, thumbnails) only to authenticated users."""
    token = await authenticate_request(request)
    if not token:
        return web.Response(status=401, text="Unauthorized")

    rel_path = request.match_info.get("path", "")
    # Prevent directory traversal
    if not rel_path or ".." in rel_path or rel_path.startswith("/"):
        return web.Response(status=400, text="Bad request")

    filepath = STATIC_DIR / "uploads" / rel_path
    if not filepath.is_file():
        return web.Response(status=404, text="Not found")

    # Determine content type
    content_type, _ = mimetypes.guess_type(str(filepath))
    if not content_type:
        content_type = "application/octet-stream"

    # Security: only allow safe types to render inline.
    # HTML, SVG, JS, CSS, XML etc. could execute scripts in portal's origin (stored XSS).
    SAFE_INLINE_TYPES = {
        "image/jpeg", "image/png", "image/gif", "image/webp",
        "video/mp4", "video/webm",
        "audio/mpeg", "audio/ogg",
        "application/pdf",
    }
    headers = {
        "X-Content-Type-Options": "nosniff",
    }
    if content_type not in SAFE_INLINE_TYPES:
        # Force download — never render as active content
        content_type = "application/octet-stream"
        fname = filepath.name
        headers["Content-Disposition"] = f'attachment; filename="{fname}"'

    headers["Content-Type"] = content_type
    return web.FileResponse(filepath, headers=headers)


async def http_create_token(request: web.Request) -> web.Response:
    """Create a new access token."""
    client_ip = get_client_ip(request)

    if not check_rate_limit(client_ip):
        return web.json_response({"error": "Rate limit exceeded"}, status=429)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    username = data.get("username")
    password = data.get("password")
    scopes = data.get("scopes", ["*"])
    token_name = data.get("name")
    expires_hours = data.get("expires_hours")

    if not username or not password:
        return web.json_response(
            {"error": "username and password required"},
            status=400
        )

    # "web_session" is the name of browser login sessions; the backup download
    # route trusts it, so a token made through the API may not carry it.
    if isinstance(token_name, str) and token_name.strip().casefold() == "web_session":
        return web.json_response({"error": "That token name is reserved"}, status=400)

    # Authenticate user
    user, fail_reason = await authenticate_user_reason(username, password)
    if not user:
        logger.warning(f"Failed login attempt for {_tried_label(username, fail_reason)} from {client_ip}")
        security_event_nowait("login_failed", request=request, ip=client_ip,
                              username=_tried_name(username, fail_reason),
                              result=fail_reason, details={"via": "token"})
        await _count_login_failure(client_ip, await _failure_user_id(username, fail_reason))
        return web.json_response({"error": "Invalid credentials"}, status=401)

    # Second factor: same verification as the web login. Revealed only after
    # the password checked out, so a wrong password cannot probe for 2FA.
    if user.get("totp_enabled"):
        totp_code = data.get("totp_code")
        if not totp_code or (isinstance(totp_code, str) and not totp_code.strip()):
            security_event_nowait("2fa_required", request=request, ip=client_ip, user=user,
                                  details={"via": "token"})
            return web.json_response(
                {"error": "Two-factor code required", "totp_required": True},
                status=401
            )
        result, retry_after = await verify_second_factor(user, totp_code, client_ip, request=request)
        if result == "throttled":
            return web.json_response(
                {"error": "Too many incorrect codes. Try again later."},
                status=429,
                headers={"Retry-After": str(retry_after)}
            )
        if result == "invalid":
            logger.warning(f"Failed 2FA for user '{username}' from {client_ip} (token endpoint)")
            return web.json_response(
                {"error": "Invalid 2FA code", "totp_required": True},
                status=401
            )
        if result == "backup":
            logger.info(f"Backup code used for user '{username}' from {client_ip} (token endpoint)")

    # Enforce scope restrictions based on user role
    is_admin = user.get("is_admin") or user.get("role") in ("admin", "superadmin")
    allowed_scopes = ["*"] if is_admin else ["services:read", "access:*"]
    if is_admin:
        # Admins can request any scopes
        pass
    else:
        # Non-admin users: restrict to their allowed scopes
        scopes = [s for s in scopes if s in allowed_scopes]
        if not scopes:
            scopes = allowed_scopes

    # Create token
    jwt_token, token_id = await create_access_token(
        user_id=user["id"],
        scopes=scopes,
        name=token_name,
        expires_in_hours=expires_hours,
        ip=client_ip,
        user_agent=request.headers.get("User-Agent")
    )

    logger.info(f"Token created for user '{username}' from {client_ip}")
    await db.log_activity(user["id"], get_display_name(user), "login", "Signed in", client_ip)
    await _note_login_success(user, client_ip)
    await security_event("login_success", request=request, ip=client_ip, user=user,
                         details={"via": "token", "token_id": token_id[:8]})

    return web.json_response({
        "token": jwt_token,
        "token_id": token_id,
        "user_id": user["id"],
        "scopes": scopes
    })


async def http_revoke_token(request: web.Request) -> web.Response:
    """Revoke a token."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    token_id = data.get("token_id")
    if not token_id:
        return web.json_response({"error": "token_id required"}, status=400)

    if not isinstance(token_id, str):
        return web.json_response({"error": "token_id required"}, status=400)

    # Only admins may revoke tokens that belong to other users; everyone else
    # can only touch their own and gets 404 for anything else. The credential
    # used must itself carry admin power, so a narrowly scoped admin key or
    # stream key cannot sign other users out.
    caller_role = await get_user_role_from_token(token)
    is_admin_caller = (get_role_level(caller_role) >= get_role_level("admin")
                       and token.has_scope("admin"))
    target = await db.get_token(token_id)
    # Admins follow the same hierarchy as password resets: they cannot act on
    # accounts at or above their own level (superadmins may act on anyone).
    if is_admin_caller and target and target["user_id"] != token.user_id:
        target_user = await db.get_user_by_id(target["user_id"])
        target_role = (target_user or {}).get("role") or (
            "admin" if (target_user or {}).get("is_admin") else "user")
        if not can_manage_role(caller_role, target_role):
            return web.json_response({"error": "Token not found"}, status=404)
    if await revoke_token(token_id, None if is_admin_caller else token.user_id):
        logger.info(f"Token {token_id[:8]}... revoked by user {token.user_id}")
        if target:
            # What was opened with that session ends with it: its sockets, its
            # voice call and its in-flight proxied downloads. The owner's
            # other sessions stay (also when an admin revokes a member's).
            await close_user_websockets(target["user_id"], only_token_id=token_id)
        if target and target["user_id"] != token.user_id:
            actor = await db.get_user_by_id(token.user_id)
            await audit_log("token_revoke", token.user_id,
                            actor["username"] if actor else "unknown",
                            target_id=target["user_id"], target_type="user",
                            details={"token_id": token_id[:8]})
        await security_event(
            "session_revoked", request=request, user_id=token.user_id,
            username=await _username_of(token.user_id),
            details={"token_id": token_id[:8],
                     "target_user_id": target["user_id"] if target else None,
                     "own": bool(target and target["user_id"] == token.user_id)})
        return web.json_response({"status": "revoked"})
    else:
        return web.json_response({"error": "Token not found"}, status=404)


async def http_list_tokens(request: web.Request) -> web.Response:
    """List tokens for the authenticated user."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    tokens = await db.get_user_tokens(token.user_id)
    return web.json_response({
        "tokens": [
            {
                "id": t["id"],
                "token_id": t["token_id"][:8] + "...",
                "name": t["name"],
                "scopes": t["scopes"],
                "revoked": bool(t["revoked"]),
                "created_at": t["created_at"],
                "last_used_at": t["last_used_at"],
                "expires_at": t["expires_at"]
            }
            for t in tokens
        ]
    })


def _iso_utc(value) -> Optional[str]:
    """A stored timestamp (SQLite "YYYY-MM-DD HH:MM:SS" or ISO with an offset,
    both UTC) as ISO-8601 with a Z, so the browser reads it as UTC."""
    if not value:
        return None
    try:
        when = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return when.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _session_view(row: dict, current_token_id: str) -> dict:
    """One session row as shown to its owner: never the token id itself, only
    the opaque public id derived from it."""
    device = parse_user_agent(row.get("user_agent"))
    return {
        "id": public_session_id(row["token_id"]),
        "kind": "browser" if row.get("name") == "web_session" else "token",
        "name": None if row.get("name") == "web_session" else row.get("name"),
        "device": device["label"],
        "browser": device["browser"],
        "os": device["os"],
        "created_at": _iso_utc(row.get("created_at")),
        "last_used_at": _iso_utc(row.get("last_used_at")),
        "expires_at": _iso_utc(row.get("expires_at")),
        "ip": row.get("ip"),
        "last_ip": row.get("last_ip"),
        "current": bool(current_token_id) and row["token_id"] == current_token_id,
    }


async def http_list_my_sessions(request: web.Request) -> web.Response:
    """List the caller's own sessions (browser logins and tokens made through
    the API). API keys are not sessions; they are listed under /api/api-keys."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    # The sessions routes act on the user's whole account: only a browser
    # session or a full-scope credential may use them.
    if not has_full_user_scope(token):
        return full_scope_required_response()
    rows = await db.get_user_live_tokens(token.user_id)
    return web.json_response({
        "sessions": [_session_view(r, token.token_id) for r in rows]
    })


async def http_revoke_my_session(request: web.Request) -> web.Response:
    """Sign out one of the caller's own sessions, by its public id."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    # The sessions routes act on the user's whole account: only a browser
    # session or a full-scope credential may use them.
    if not has_full_user_scope(token):
        return full_scope_required_response()
    public_id = request.match_info.get("id", "")
    target = next((r for r in await db.get_user_live_tokens(token.user_id)
                   if matches_public_id(r["token_id"], public_id)), None)
    if target is None:
        return web.json_response({"error": "Session not found"}, status=404)
    if target["token_id"] == token.token_id:
        return web.json_response(
            {"error": "This is the session you are using. Use Log out to end it."},
            status=400)
    if not await db.revoke_token(target["token_id"], token.user_id):
        return web.json_response({"error": "Session not found"}, status=404)
    # What was opened with that session ends with it; the other sessions stay.
    await close_user_websockets(token.user_id, only_token_id=target["token_id"])
    logger.info(f"Session {public_id} of user {token.user_id} signed out by the user")
    await security_event(
        "session_revoked", request=request, user_id=token.user_id,
        username=await _username_of(token.user_id), result="own",
        details={"token_id": target["token_id"][:8], "target_user_id": token.user_id,
                 "own": True})
    return web.json_response({"status": "revoked"})


async def http_revoke_my_other_sessions(request: web.Request) -> web.Response:
    """Sign out every session of the caller except the one making the request.
    API keys and stream keys are not sessions and are left alone."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    # The sessions routes act on the user's whole account: only a browser
    # session or a full-scope credential may use them.
    if not has_full_user_scope(token):
        return full_scope_required_response()
    revoked = await db.revoke_user_tokens(token.user_id, except_token_id=token.token_id)
    closed = await close_user_websockets(token.user_id, except_token_id=token.token_id,
                                         keep_prefixes=("apikey-", "streamkey-"))
    logger.info(f"User {token.user_id} signed out {revoked} other session(s)")
    await security_event(
        "session_revoked", request=request, user_id=token.user_id,
        username=await _username_of(token.user_id), result="others",
        details={"sessions_revoked": revoked, "websockets_closed": closed,
                 "target_user_id": token.user_id, "own": True})
    return web.json_response({"status": "ok", "revoked": revoked, "websockets_closed": closed})


async def http_admin_revoke_user_sessions(request: web.Request) -> web.Response:
    """Admin "sign out everywhere" for one user. Governed by the same hierarchy
    as password resets (can_manage_role). On the caller's own account it keeps
    the session being used, so an admin cannot lock themselves out. Sessions and
    tokens only: API keys and stream keys are not revoked."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    # The role comes from the database, not from the scopes the session was
    # created with: someone promoted to admin keeps a member's scopes until
    # they sign in again. The credential must still be a full-scope one, so a
    # stream key or a scoped key cannot sign anyone out.
    actor_role = await get_user_role_from_token(token)
    if get_role_level(actor_role) < get_role_level("admin"):
        return web.json_response(
            {"error": "Only admins and superadmins can sign users out"}, status=403)
    if not has_full_user_scope(token):
        return full_scope_required_response()
    user_id = request.match_info.get("id")
    if not user_id or not user_id.isdigit():
        return web.json_response({"error": "Invalid user ID"}, status=400)
    user_id = int(user_id)
    target_user = await db.get_user_by_id(user_id)
    if not target_user:
        return web.json_response({"error": "User not found"}, status=404)
    own = user_id == token.user_id
    if not own:
        target_role = target_user.get("role") or ("admin" if target_user.get("is_admin") else "user")
        if not can_manage_role(actor_role, target_role):
            return web.json_response(
                {"error": f"You cannot sign out users with role '{target_role}'"}, status=403)
    keep_token_id = token.token_id if own else None
    revoked = await db.revoke_user_tokens(user_id, except_token_id=keep_token_id)
    # "Everywhere" includes push devices, the current session's too
    await db.delete_user_push_subscriptions(user_id)
    closed = await close_user_websockets(user_id, except_token_id=keep_token_id,
                                         keep_prefixes=("apikey-", "streamkey-"))
    actor = await db.get_user_by_id(token.user_id)
    await audit_log("sessions_revoke", token.user_id,
                    actor["username"] if actor else "unknown",
                    target_id=user_id, target_type="user",
                    target_name=target_user["username"],
                    details={"sessions_revoked": revoked, "websockets_closed": closed,
                             "kept_current_session": own})
    logger.info(f"Sessions of user {user_id} signed out by {actor_role} {token.user_id}")
    await security_event(
        "session_revoked", request=request, user_id=token.user_id,
        username=actor["username"] if actor else None, result="admin_all",
        details={"target_user_id": user_id, "target_username": target_user["username"],
                 "sessions_revoked": revoked, "websockets_closed": closed,
                 "kept_current_session": own, "own": own})
    return web.json_response({"status": "ok", "revoked": revoked,
                              "kept_current_session": own})


def _attach_resource_usage(status: dict) -> None:
    """Mutate a service/game-server status dict in place, adding a
    ``resource`` field ({cpu_percent, mem_mb, procs}) when it's running and
    has a PID — used by the Services/Managed Services/Game Servers cards.
    No-op (leaves ``resource`` unset) when stopped or PID-less, so the
    frontend can hide the readout rather than show a stale/zero one."""
    if status.get("status") == "running" and status.get("pid"):
        usage = system_monitor.get_tree_resource_usage(status["pid"])
        if usage:
            status["resource"] = usage


async def http_list_services(request: web.Request) -> web.Response:
    """List available services.

    Query params:
        type: Filter by service_type ('proxy' or 'managed')
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Check for type filter
    service_type = request.query.get("type")
    if service_type and service_type in ("proxy", "managed"):
        services = await db.get_enabled_services_by_type(service_type)
    else:
        services = await db.get_all_services()

    # A disabled managed service just means "don't auto-start on Portal boot"
    # (normal for a systemd-wrapped game server that runs on its own). It's
    # still visible to an admin and to any user granted control/logs on it, so
    # merge those in — get_all_services / get_enabled_services_by_type filter
    # on enabled=1.
    if service_type in (None, "", "managed"):
        is_admin = token.has_scope("admin") or token.has_scope("*")
        granted_ids = set() if is_admin else set(
            (await db.get_user_granted_service_ids(token.user_id)).keys()
        )
        if is_admin or granted_ids:
            seen = {s["id"] for s in services}
            for s in await db.get_services_by_type("managed"):
                if s["id"] not in seen and (is_admin or s["id"] in granted_ids):
                    services.append(s)

    async def serialize_service(s):
        """Serialize service for API response."""
        result = {
            "id": s["id"],
            "name": s["name"],
            "path": s["path"],
            "plugin": s.get("plugin", "tcp_tunnel"),
            "host": s.get("host", ""),
            "port": s.get("port", 0),
            "required_scopes": s["required_scopes"],
            "enabled": bool(s["enabled"]),
            "service_type": s.get("service_type", "proxy"),
            "icon": s.get("icon", "server"),
            "systemd_unit": s.get("systemd_unit"),
        }
        # Include process management fields for managed services
        if s.get("service_type") == "managed":
            # Prefer the live status (get_service_status reconciles a systemd-
            # backed service against the outside world on every call, so a
            # unit that restarted between health-monitor ticks doesn't leave
            # a stale PID here) over the plain DB row, which only refreshes
            # on a status-text transition — the resource-usage chip on a
            # restarted-but-still-"running" game server was going missing
            # because a dead PID resolves to nothing, not an old one.
            live = await _service_manager.get_service_status(s["id"]) if _service_manager else None
            src = live or s
            result.update({
                "display_name": s.get("display_name") or s["name"],
                "description": s.get("description", ""),
                "status": src.get("status", "stopped"),
                "pid": src.get("pid"),
                "health_status": src.get("health_status", "unknown"),
            })
            _attach_resource_usage(result)
        elif s.get("systemd_unit"):
            unit_status = await asyncio.to_thread(system_monitor.get_service_status, s["systemd_unit"])
            result["status"] = "running" if unit_status and unit_status["sub_state"] == "running" else "stopped"
        return result

    return web.json_response({
        "services": [await serialize_service(s) for s in services]
    })


async def http_create_service(request: web.Request) -> web.Response:
    """Create a new service (admin only).

    Supports both proxy services (routing to external backends) and
    managed services (Portal-run processes).
    """
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Check admin scope
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    name = data.get("name")
    path = data.get("path")
    plugin = data.get("plugin", "tcp_tunnel")
    host = data.get("host", "localhost")
    port = data.get("port", 0)
    config = data.get("config", {})
    required_scopes = data.get("required_scopes", "*")

    # Unified services fields
    service_type = data.get("service_type", "proxy")
    display_name = data.get("display_name")
    description = data.get("description")
    binary_path = data.get("binary_path")
    working_dir = data.get("working_dir")
    ports = data.get("ports", [])
    icon = data.get("icon", "server")
    systemd_unit = (data.get("systemd_unit") or "").strip() or None

    # Handle scopes as string or list
    if isinstance(required_scopes, str):
        required_scopes = [s.strip() for s in required_scopes.split(",") if s.strip()]

    if not name or not path:
        return web.json_response(
            {"error": "name and path required"},
            status=400
        )

    # Validate service_type
    if service_type not in ("proxy", "managed"):
        return web.json_response(
            {"error": "service_type must be 'proxy' or 'managed'"},
            status=400
        )

    if systemd_unit and not system_monitor._validate_service_name(systemd_unit):
        return web.json_response({"error": "Invalid systemd unit name"}, status=400)

    # For managed services, use 127.0.0.1 as default host
    if service_type == "managed" and host == "localhost":
        host = "127.0.0.1"

    if isinstance(config, dict):
        if "host_key_ignore" in config and not isinstance(config["host_key_ignore"], bool):
            return web.json_response({"error": "Invalid host key setting"}, status=400)
        # An admin may pre-fill a valid fingerprint; anything else is dropped.
        config = hostkeys.guard_replacement({}, config, target_changed=False, trusted_incoming=True)

    try:
        service_id = await db.create_service(
            name=name,
            path=path,
            plugin=plugin,
            host=host,
            port=port,
            config=config,
            required_scopes=required_scopes,
            icon=icon,
            service_type=service_type,
            display_name=display_name,
            description=description,
            binary_path=binary_path,
            working_dir=working_dir,
            ports=ports,
            systemd_unit=systemd_unit
        )
        logger.info(f"Service '{name}' ({service_type}) created by user {token.user_id}")

        response = {
            "id": service_id,
            "name": name,
            "path": path,
            "plugin": plugin,
            "host": host,
            "port": port,
            "required_scopes": required_scopes,
            "service_type": service_type,
            "icon": icon,
            "systemd_unit": systemd_unit,
        }
        if service_type == "managed":
            response.update({
                "display_name": display_name or name,
                "description": description,
                "status": "stopped",
            })
        return web.json_response(response, status=201)
    except Exception as e:
        logger.warning(f"Failed to create service: {e}")
        return web.json_response({"error": safe_error_message(e)}, status=400)


async def http_delete_service(request: web.Request) -> web.Response:
    """Delete a relay service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    if await db.delete_service(int(service_id)):
        logger.info(f"Service {service_id} deleted by user {token.user_id}")
        return web.json_response({"status": "deleted"})
    else:
        return web.json_response({"error": "Service not found"}, status=404)


async def http_update_service(request: web.Request) -> web.Response:
    """Update a service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service_id = int(service_id)

    # Check service exists
    service = await db.get_service_by_id(service_id)
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Build update fields
    updates = {}
    # Common fields
    for field in ["name", "path", "plugin", "host", "port", "icon"]:
        if field in data:
            updates[field] = data[field]
    if "enabled" in data:
        updates["enabled"] = 1 if data["enabled"] else 0
    if "required_scopes" in data:
        scopes = data["required_scopes"]
        if isinstance(scopes, str):
            scopes = [s.strip() for s in scopes.split(",") if s.strip()]
        updates["required_scopes"] = ",".join(scopes)
    # A changed effective SSH target (the host and port the ssh plugin dials:
    # the config's own host/port when set, else the columns) drops the SSH
    # host-key pin, whether or not a config is sent with the edit.
    target_changed = _service_target_changed(
        service, updates, data.get("config") if "config" in data else None)
    if "config" in data:
        new_config = data["config"]
        if isinstance(new_config, dict):
            # The SSH host-key pin is only set by the accept route or an admin
            # pre-filling a valid fingerprint.
            if "host_key_ignore" in new_config and not isinstance(new_config["host_key_ignore"], bool):
                return web.json_response({"error": "Invalid host key setting"}, status=400)
            new_config = hostkeys.guard_replacement(
                service.get("config"), new_config,
                target_changed=target_changed, trusted_incoming=True)
            updates["config"] = new_config   # a dict: stored encrypted
        else:
            updates["config"] = json.dumps(new_config)
    elif target_changed and isinstance(service.get("config"), dict) and (
            hostkeys.FINGERPRINT_KEY in service["config"] or hostkeys.REFUSED_KEY in service["config"]):
        updates["config"] = hostkeys.guard_replacement(
            service["config"], service["config"], target_changed=True)

    # Managed service fields
    for field in ["display_name", "description", "binary_path", "working_dir"]:
        if field in data:
            updates[field] = data[field]
    if "ports" in data:
        updates["ports"] = json.dumps(data["ports"])

    if "systemd_unit" in data:
        unit = (data["systemd_unit"] or "").strip() or None
        if unit and not system_monitor._validate_service_name(unit):
            return web.json_response({"error": "Invalid systemd unit name"}, status=400)
        updates["systemd_unit"] = unit

    if not updates:
        return web.json_response({"error": "No fields to update"}, status=400)

    try:
        # Use the unified update method
        await db.update_service_full(service_id, **updates)

        # Get updated service
        updated = await db.get_service_by_id(service_id)
        logger.info(f"Service {service_id} updated by user {token.user_id}: {list(updates.keys())}")

        response = {
            "id": updated["id"],
            "name": updated["name"],
            "path": updated["path"],
            "plugin": updated.get("plugin", "tcp_tunnel"),
            "host": updated.get("host", ""),
            "port": updated.get("port", 0),
            "enabled": bool(updated["enabled"]),
            "required_scopes": updated["required_scopes"],
            "service_type": updated.get("service_type", "proxy"),
            "icon": updated.get("icon", "server"),
            "systemd_unit": updated.get("systemd_unit"),
        }
        if updated.get("service_type") == "managed":
            response.update({
                "display_name": updated.get("display_name") or updated["name"],
                "description": updated.get("description", ""),
                "status": updated.get("status", "stopped"),
            })
        return web.json_response(response)
    except Exception as e:
        logger.warning(f"Failed to update service {service_id}: {e}")
        return web.json_response({"error": safe_error_message(e)}, status=400)


async def http_get_service(request: web.Request) -> web.Response:
    """Get a single service by ID."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service = await db.get_service_by_id(int(service_id))
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    # Check authorization for non-admin users
    if not token.has_scope("admin") and not token.has_scope("*"):
        if not check_service_authorization(service, token):
            return web.json_response({"error": "Access denied"}, status=403)

    response = {
        "id": service["id"],
        "name": service["name"],
        "path": service["path"],
        "plugin": service.get("plugin", "tcp_tunnel"),
        "host": service.get("host", ""),
        "port": service.get("port", 0),
        "enabled": bool(service["enabled"]),
        "required_scopes": service["required_scopes"],
        "config": redact_service_config(service.get("config", {})),
        "service_type": service.get("service_type", "proxy"),
        "icon": service.get("icon", "server"),
        "systemd_unit": service.get("systemd_unit"),
    }

    if service.get("systemd_unit"):
        unit_status = await asyncio.to_thread(system_monitor.get_service_status, service["systemd_unit"])
        response["systemd_status"] = unit_status["sub_state"] if unit_status else "unknown"
        response["status"] = "running" if unit_status and unit_status["sub_state"] == "running" else "stopped"

    # Include process management fields for managed services
    if service.get("service_type") == "managed":
        response.update({
            "display_name": service.get("display_name") or service["name"],
            "description": service.get("description", ""),
            "status": service.get("status", "stopped"),
            "pid": service.get("pid"),
            "binary_path": service.get("binary_path"),
            "working_dir": service.get("working_dir"),
            "ports": service.get("ports", []),
            "health_status": service.get("health_status", "unknown"),
            "last_health_check": service.get("last_health_check"),
            "restart_count": service.get("restart_count", 0),
            "last_started_at": service.get("last_started_at"),
            "last_stopped_at": service.get("last_stopped_at"),
            "error_message": service.get("error_message"),
        })

    return web.json_response(response)


async def http_get_service_types(request: web.Request) -> web.Response:
    """Get available managed service types."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    types = get_available_service_types()
    return web.json_response({"types": types})


async def _audit_service_control(token: "TokenPayload", service: dict, action: str) -> None:
    """Audit entry for a start, stop or restart of a service done through the portal. A stop asked
    for here is deliberately silent to the health alerts, so it must leave a record."""
    actor = await db.get_user_by_id(token.user_id)
    await audit_log(
        f"service.{action}", token.user_id, (actor or {}).get("username", "unknown"),
        target_id=service["id"], target_type="service", target_name=service.get("name"),
        details={"service_id": service["id"], "service_name": service.get("name"), "action": action,
                 "systemd_unit": service.get("systemd_unit") if service.get("service_type") != "managed" else None},
    )


async def _control_systemd_bound_service(
    service: dict, action: str, token: "TokenPayload"
) -> web.Response:
    """Start/stop/restart a proxy-type (or any) service bound to a systemd unit.

    This reuses system_monitor.control_service(), the same validated
    `sudo systemctl <action> <unit>.service` call already exposed under
    System Monitor — it's just wired into the Services panel here so a
    service row (e.g. a game server or file share behind the reverse
    proxy) doesn't need SSH access to be restarted.
    """
    unit = service["systemd_unit"]
    success, message = await asyncio.to_thread(system_monitor.control_service, unit, action)
    if not success:
        return web.json_response({"error": message}, status=400)

    logger.info(f"Service {service['id']} ({unit}.service) {action} by user {token.user_id}")
    admin_user = await db.get_user_by_id(token.user_id)
    await db.log_activity(
        token.user_id, get_display_name(admin_user) if admin_user else "admin",
        f"service_{action}", f"{action.capitalize()}ed service '{service.get('name', service['id'])}' ({unit})"
    )
    await _audit_service_control(token, service, action)
    unit_status = await asyncio.to_thread(system_monitor.get_service_status, unit)
    status = "running" if unit_status and unit_status["sub_state"] == "running" else "stopped"
    return web.json_response({
        "success": True,
        "service": {
            "id": service["id"],
            "name": service["name"],
            "status": status,
            "pid": unit_status.get("main_pid") if unit_status else None,
        }
    })


async def http_start_service(request: web.Request) -> web.Response:
    """Start a managed/systemd-bound service (admin or a user with a 'control' grant)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    service_id = request.match_info.get("id")
    if not service_id or not service_id.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)

    service_id = int(service_id)

    if not await _can_control_service(token, service_id, "control"):
        return forbidden_response(request)

    service = await db.get_service_by_id(service_id)
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)

    if service.get("service_type") != "managed":
        if not service.get("systemd_unit"):
            return web.json_response(
                {"error": "This service has no start/stop/restart control configured. "
                          "Bind it to a systemd unit to enable it."},
                status=400
            )
        return await _control_systemd_bound_service(service, "start", token)

    if not _service_manager:
        return web.json_response({"error": "Service manager not initialized"}, status=503)

    success, error = await _service_manager.start_service(service_id)
    if success:
        logger.info(f"Service {service_id} started by user {token.user_id}")
        await _audit_service_control(token, service, "start")
        updated = await db.get_service_by_id(service_id)
        admin_user = await db.get_user_by_id(token.user_id)
        await db.log_activity(token.user_id, get_display_name(admin_user) if admin_user else "admin", "service_start", f"Started service '{service.get('name', service_id)}'")
        return web.json_response({
            "success": True,
            "service": {
                "id": updated["id"],
                "name": updated["name"],
                "status": updated.get("status", "stopped"),
                "pid": updated.get("pid"),
            }
        })
    else:
        return web.json_response({"error": error}, status=400)


