async def http_shodan_lookup(request: web.Request) -> web.Response:
    """Look up an IP address in Shodan (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    ip = request.match_info.get("ip")
    if not ip:
        return web.json_response({"error": "IP address required"}, status=400)

    # Validate IP format
    import ipaddress as _ipaddress
    try:
        _ipaddress.ip_address(ip)
    except ValueError:
        return web.json_response({"error": "Invalid IP address format"}, status=400)

    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({"error": "Shodan API key not configured"}, status=503)

    result = await shodan_client.lookup_host(ip)
    if result:
        return web.json_response(result.to_dict())
    else:
        return web.json_response({"error": "No data found for IP", "ip": ip}, status=404)


async def http_shodan_search(request: web.Request) -> web.Response:
    """Search Shodan (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({"error": "Shodan API key not configured"}, status=503)

    query = request.query.get("query")
    if not query:
        return web.json_response({"error": "Query parameter required"}, status=400)

    try:
        limit = int(request.query.get("limit", "10"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid limit parameter"}, status=400)
    limit = min(max(limit, 1), 100)

    results = await shodan_client.search(query, limit)
    return web.json_response({"results": results})


async def http_shodan_api_info(request: web.Request) -> web.Response:
    """Get Shodan API info (credits remaining, etc.) - admin only."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    # Check both Config and the client (client may have been set at runtime)
    if not Config.SHODAN_API_KEY and not shodan_client.api_key:
        return web.json_response({
            "configured": False,
            "message": "Shodan API key not configured"
        })

    info = await shodan_client.get_api_info()
    if info:
        return web.json_response({
            "configured": True,
            "plan": info.get("plan", "unknown"),
            "query_credits": info.get("query_credits", 0),
            "scan_credits": info.get("scan_credits", 0)
        })
    else:
        return web.json_response({
            "configured": bool(Config.SHODAN_API_KEY or shodan_client.api_key),
            "error": "Failed to get API info"
        }, status=500)


async def http_shodan_set_api_key(request: web.Request) -> web.Response:
    """Set Shodan API key (admin only) - persists to database."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    api_key = data.get("api_key", "").strip()
    if not api_key:
        return web.json_response({"error": "API key required"}, status=400)

    # Set the API key in both the client and Config
    shodan_client.set_api_key(api_key)
    Config.SHODAN_API_KEY = api_key

    # Verify the key works before persisting
    info = await shodan_client.get_api_info()
    if info:
        # Persist to database (encrypted at rest) for survival across restarts
        await db.set_setting("shodan_api_key", encrypt_config(api_key))
        logger.info(f"Shodan API key updated and persisted by user {token.user_id}")
        return web.json_response({
            "status": "success",
            "plan": info.get("plan", "unknown"),
            "query_credits": info.get("query_credits", 0)
        })
    else:
        return web.json_response({"error": "Invalid API key"}, status=400)


# =============================================================================
# VOD Manager API
# =============================================================================


_vod_pin_lock = asyncio.Lock()


async def _vod_note_host_key(user_id: int, storage: dict, *, pin: Optional[str] = None,
                             refused: Optional[str] = None) -> bool:
    """Record a VOD storage host-key event in its config: pin a key (first use
    after an upgrade, only while no pin exists) or note the key that was refused.
    Returns True when something was written."""
    async with _vod_pin_lock:
        current = await db.get_vod_storage(user_id)
        if (not current or current["host"] != storage["host"]
                or (current["port"] or 22) != (storage["port"] or 22)):
            return False
        config = dict(current.get("config") or {})
        if pin:
            if hostkeys.normalize_fingerprint(config.get(hostkeys.FINGERPRINT_KEY)):
                return False        # someone pinned meanwhile; never overwrite here
            config[hostkeys.FINGERPRINT_KEY] = pin
            config.pop(hostkeys.REFUSED_KEY, None)
        elif refused:
            config[hostkeys.REFUSED_KEY] = {
                "fingerprint": refused, "at": datetime.now(timezone.utc).isoformat()}
        else:
            return False
        return await db.update_vod_storage_config(
            user_id, config, current["host"], current["port"])


async def _vod_activity(user_id: int, action: str, detail: str) -> None:
    user = await db.get_user_by_id(user_id)
    await db.log_activity(user_id, get_display_name(user) if user else "unknown", action, detail)


_VOD_HOST_KEY_ERROR = "Host key changed; review it in VOD storage settings"


async def _vod_dial(user_id: int, storage: dict, addrs: list):
    """Dial VOD storage on already policy-checked addresses and verify its host
    key. There is nobody to ask at upload time, so a first key is pinned
    automatically (and logged); a different key later is refused and logged.
    Returns (conn, sftp, None) or (None, None, error)."""
    config = storage.get("config") or {}
    connect_opts = {
        "host": addrs[0],   # replaced per attempt by connect_verified
        "port": storage["port"] or 22,
        "username": storage["username"],
    }

    if storage["auth_method"] == "key":
        key_content = config.get("private_key")
        if key_content:
            connect_opts["client_keys"] = [asyncssh.import_private_key(key_content)]
        else:
            return None, None, "No private key configured"
    elif storage["auth_method"] == "password":
        connect_opts["password"] = config.get("password", "")

    pinned, ignore = hostkeys.policy_for(config)
    try:
        conn, seen = await hostkeys.connect_verified(
            addrs, connect_opts, pinned=pinned, ignore=ignore, trust_unpinned=True, timeout=10)
    except hostkeys.HostKeyRefused as refused:
        logger.warning(
            f"VOD SFTP host key changed for user {user_id}: expected {refused.expected}, "
            f"server presented {refused.fingerprint}; upload/download refused")
        await _vod_note_host_key(user_id, storage, refused=refused.fingerprint)
        await _vod_activity(user_id, "vod_host_key_refused",
                            f"VOD storage host key changed (now {refused.fingerprint}); connection refused")
        return None, None, _VOD_HOST_KEY_ERROR
    except asyncio.TimeoutError:
        return None, None, "Connection timed out"
    except asyncssh.Error as e:
        logger.warning(f"VOD SFTP SSH error for user {user_id}: {e}")
        return None, None, "Connection failed"
    except OSError as e:
        logger.warning(f"VOD SFTP connection error for user {user_id}: {e}")
        return None, None, "Connection failed"

    if seen and not pinned and not ignore:
        if await _vod_note_host_key(user_id, storage, pin=seen):
            logger.info(f"VOD SFTP host key pinned on first use for user {user_id}: {seen}")
            await _vod_activity(user_id, "vod_host_key_pinned",
                                f"VOD storage host key pinned on first use ({seen})")
    try:
        sftp = await asyncio.wait_for(conn.start_sftp_client(), VOD_SFTP_START_TIMEOUT)
    except asyncio.TimeoutError:
        conn.close()
        logger.warning(f"VOD SFTP session start timed out for user {user_id}")
        return None, None, "Connection timed out"
    except (asyncssh.Error, OSError) as e:
        conn.close()
        logger.warning(f"VOD SFTP session error for user {user_id}: {e}")
        return None, None, "Connection failed"
    except BaseException:
        conn.close()                                # cancelled by a caller's deadline: do not leave it open
        raise
    return conn, sftp, None


async def _connect_vod_sftp(user_id: int):
    """Connect to user's VOD SFTP storage. Returns (conn, sftp, None) or (None, None, error)."""
    storage = await db.get_vod_storage(user_id)
    if not storage:
        return None, None, "No VOD storage configured"

    try:
        # Dial the checked addresses so a later DNS answer cannot differ.
        _addrs = await resolve_checked_host(storage["host"], storage["port"] or 22)
    except HostCheckError:
        logger.warning(f"VOD SFTP host refused by outbound host policy for user {user_id}")
        return None, None, "Host not allowed"
    return await _vod_dial(user_id, storage, _addrs)


async def http_get_vod_storage(request: web.Request) -> web.Response:
    """Get current user's VOD storage config (password/key redacted)."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"storage": None})

    # Redact sensitive fields - strip config entirely, expose only flags
    config = storage.get("config") or {}
    redacted = dict(storage)
    del redacted["config"]
    redacted["has_password"] = bool(config.get("password"))
    redacted["has_key"] = bool(config.get("private_key"))
    # Host key: what is pinned, whether the check is off, and the last key refused
    pinned, ignore = hostkeys.policy_for(config)
    refused = config.get(hostkeys.REFUSED_KEY)
    redacted["host_key_fingerprint"] = pinned
    redacted["host_key_ignore"] = ignore
    redacted["host_key_refused"] = (
        {"fingerprint": refused.get("fingerprint"), "at": refused.get("at")}
        if isinstance(refused, dict) and hostkeys.valid_fingerprint(refused.get("fingerprint")) else None)

    return web.json_response({"storage": redacted, "recording_guard": _vod_guard_public(token.user_id)})


async def http_save_vod_storage(request: web.Request) -> web.Response:
    """Create or update VOD storage config."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    host = data.get("host", "").strip()
    username = data.get("username", "").strip()
    remote_path = data.get("remote_path", "").strip()
    auth_method = data.get("auth_method", "password")

    if not host:
        return web.json_response({"error": "Host is required"}, status=400)
    if not username:
        return web.json_response({"error": "Username is required"}, status=400)
    if not remote_path:
        return web.json_response({"error": "Remote path is required"}, status=400)
    if auth_method not in ("password", "key"):
        return web.json_response({"error": "Invalid auth method"}, status=400)

    port = data.get("port", 22)
    try:
        port = int(port)
        if port < 1 or port > 65535:
            raise ValueError
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid port"}, status=400)

    # Refuse local/internal targets (a name that does not resolve yet may be
    # saved; connecting re-checks and fails closed)
    if not await _user_targets_allowed(host, None, port):
        return web.json_response({"error": "Host not allowed"}, status=403)

    # Build config JSON with sensitive data
    config = {}
    if auth_method == "password":
        password = data.get("password", "")
        # If password is "***", keep existing password
        if password == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                password = existing_config.get("password", "")
        config["password"] = password
    elif auth_method == "key":
        private_key = data.get("private_key", "")
        # If key is "***", keep existing key
        if private_key == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                private_key = existing_config.get("private_key", "")
        config["private_key"] = private_key

    # Host key: the pin survives an edit only while the target is unchanged
    # (a new host or port starts again); the opt-out is the owner's own setting.
    previous = await db.get_vod_storage(token.user_id)
    prev_config = (previous.get("config") or {}) if previous else {}
    if "host_key_ignore" in data and not isinstance(data["host_key_ignore"], bool):
        return web.json_response({"error": "Invalid host key setting"}, status=400)
    if previous and previous["host"] == host and (previous["port"] or 22) == port:
        kept = hostkeys.normalize_fingerprint(prev_config.get(hostkeys.FINGERPRINT_KEY))
        if kept:
            config[hostkeys.FINGERPRINT_KEY] = kept
        if isinstance(prev_config.get(hostkeys.REFUSED_KEY), dict):
            config[hostkeys.REFUSED_KEY] = prev_config[hostkeys.REFUSED_KEY]
    config[hostkeys.IGNORE_KEY] = data.get(
        "host_key_ignore", hostkeys.policy_for(prev_config)[1]) is True

    storage_id = await db.save_vod_storage(
        token.user_id,
        name=data.get("name", "My VOD Storage"),
        host=host,
        port=port,
        username=username,
        auth_method=auth_method,
        remote_path=remote_path,
        config=json.dumps(config),
    )

    _vod_play_purge(owner=token.user_id, ident_not=vod_play.storage_ident(
        {"host": host, "port": port, "username": username, "remote_path": remote_path}))
    return web.json_response({"id": storage_id, "message": "Storage config saved"})


async def http_delete_vod_storage(request: web.Request) -> web.Response:
    """Delete VOD storage config."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    deleted = await db.delete_vod_storage(token.user_id)
    _vod_play_purge(owner=token.user_id)
    if not deleted:
        return web.json_response({"error": "No storage config found"}, status=404)
    return web.json_response({"message": "Storage config deleted"})


async def _accepted_fingerprint(request: web.Request):
    """Read and validate the fingerprint an accept request names.
    Returns (fingerprint, None) or (None, error response)."""
    body, fp, err = await _read_accept_request(request)
    return fp, err


async def _read_accept_request(request: web.Request):
    """Read an accept request body. Returns (body, fingerprint, None) or
    (None, None, error response)."""
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return None, None, web.json_response({"error": "Invalid JSON"}, status=400)
    data = data if isinstance(data, dict) else {}
    fp = hostkeys.normalize_fingerprint(data.get("fingerprint"))
    if not fp:
        return None, None, web.json_response({"error": "A SHA256 host key fingerprint is required"}, status=400)
    return data, fp, None


def _stale_host_key(message: str) -> web.Response:
    return web.json_response({"error": message, "type": "host_key_stale"}, status=409)


def _user_connection_ssh_target(connection: dict) -> tuple:
    """(host, port) the SSH/SFTP code dials for a user connection."""
    return connection.get("host") or "", connection.get("port") or 22


def _service_ssh_target(service: dict) -> tuple:
    """(host, port) the ssh plugin dials for an admin-defined service (the
    config can override the service's own host and port, as in the plugin)."""
    config = service.get("config") if isinstance(service.get("config"), dict) else {}
    return (config.get("host", service.get("host")) or "",
            _coerce_port(config.get("port"), _coerce_port(service.get("port"), 22)))


def _service_target_changed(service: dict, updates: dict, new_config=None) -> bool:
    """True when an edit changes the host or port the ssh plugin dials: the
    columns in `updates` or the host/port inside the incoming `new_config`."""
    after = dict(service)
    for column in ("host", "port"):
        if column in updates:
            after[column] = updates[column]
    if isinstance(new_config, dict):
        after["config"] = new_config
    return _service_ssh_target(service) != _service_ssh_target(after)


def _coerce_port(value, default: int) -> int:
    """A TCP port as an int; `default` when the value is missing or not a valid port
    (a config saved through the form can hold the port as text or null)."""
    if isinstance(value, bool):
        return default
    try:
        port = int(str(value).strip()) if isinstance(value, (str, float)) else int(value)
    except (TypeError, ValueError):
        return default
    return port if 0 < port < 65536 else default


def _present_host_key(payload: dict, scope: str, ident, user_id: int, target: tuple) -> dict:
    """Add the target and a signed token to a host-key prompt for someone who
    may accept it, so the accept request can prove what was shown."""
    host, port = target
    payload["host"], payload["port"] = host, port
    payload["accept_token"] = hostkeys.HostKeyAcceptToken.issue(
        Config.JWT_SECRET, scope, ident, user_id, host, port, payload["fingerprint"])
    return payload


def _check_accepted_prompt(body: dict, fp: str, scope: str, ident, user_id: int, target: tuple):
    """Refuse (409) an accept for a prompt that no longer matches. Returns an
    error response, or None when the host, port and fingerprint the user saw are
    still the connection's and were presented by this portal to this user."""
    host, port = body.get("host"), body.get("port")
    if not isinstance(host, str) or isinstance(port, bool) or not isinstance(port, int):
        return web.json_response({"error": "host, port and fingerprint of the prompt are required"}, status=400)
    try:
        target_port = int(target[1])
    except (TypeError, ValueError):
        target_port = None
    if (host, port) != (target[0], target_port):
        return _stale_host_key("This connection now points at a different host or port; connect again to review its key")
    if not hostkeys.HostKeyAcceptToken.check(
            Config.JWT_SECRET, body.get("token"), scope, ident, user_id, host, port, fp):
        return _stale_host_key("The fingerprint does not match the one presented, or the prompt expired; connect again")
    return None


async def http_accept_vod_host_key(request: web.Request) -> web.Response:
    """POST /api/vods/storage/host-key/accept - pin (or replace) the VOD storage
    host key. The storage belongs to the signed-in user alone. The fingerprint
    must be the refused one the settings page showed; anything else is a 409."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal
    fp, err = await _accepted_fingerprint(request)
    if err:
        return err
    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)
    async with _vod_pin_lock:
        storage = await db.get_vod_storage(token.user_id) or storage   # a transfer may have refused a key meanwhile
        config = dict(storage.get("config") or {})
        # Only the key the owner was shown (the last one a transfer refused).
        refused = config.get(hostkeys.REFUSED_KEY)
        shown = hostkeys.normalize_fingerprint(refused.get("fingerprint")) if isinstance(refused, dict) else None
        if not shown or shown != fp:
            return _stale_host_key("That is not the key the storage last presented; reload the VOD storage settings")
        config[hostkeys.FINGERPRINT_KEY] = fp
        config.pop(hostkeys.REFUSED_KEY, None)
        if not await db.update_vod_storage_config(token.user_id, config, storage["host"], storage["port"]):
            return web.json_response({"error": "Storage changed; try again"}, status=409)
    logger.info(f"VOD storage host key accepted by user {token.user_id}: {fp}")
    await _vod_activity(token.user_id, "vod_host_key_accepted", f"VOD storage host key accepted ({fp})")
    await security_event("host_key_accepted", request=request, user_id=token.user_id,
                         username=await _username_of(token.user_id),
                         details={"kind": "vod_storage", "fingerprint": fp})
    return web.json_response({"status": "accepted", "fingerprint": fp})


async def http_test_vod_storage(request: web.Request) -> web.Response:
    """Test SFTP connection with provided or saved credentials."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    host = data.get("host", "").strip()
    username = data.get("username", "").strip()
    remote_path = data.get("remote_path", "").strip()
    auth_method = data.get("auth_method", "password")
    try:
        port = int(data.get("port", 22))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid port"}, status=400)

    if not host or not username:
        return web.json_response({"error": "Host and username are required"}, status=400)

    try:
        _addrs = await resolve_checked_host(host, port)
    except HostBlockedError:
        return web.json_response({"success": False, "error": "Host not allowed"})
    except HostResolveError:
        return web.json_response({"success": False, "error": "Connection failed"})

    connect_opts = {
        # Dial the checked address so a later DNS answer cannot differ.
        "host": _addrs[0],   # replaced per attempt by connect_verified below
        "port": port,
        "username": username,
    }

    # Host key: the saved pin applies while the target is unchanged; otherwise
    # this is a first look at the host (nothing is pinned by a test).
    saved = await db.get_vod_storage(token.user_id)
    pinned = None
    if saved and saved["host"] == host and (saved["port"] or 22) == port:
        pinned = hostkeys.policy_for(saved.get("config"))[0]
    ignore = data.get("host_key_ignore") is True

    # Resolve credentials (may need to fetch existing if "***")
    if auth_method == "key":
        private_key = data.get("private_key", "")
        if private_key == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                private_key = existing_config.get("private_key", "")
        if private_key:
            try:
                connect_opts["client_keys"] = [asyncssh.import_private_key(private_key)]
            except asyncssh.KeyImportError as e:
                logger.warning(f"VOD storage private key import error: {e}")
                return web.json_response({"success": False, "error": "Invalid private key format"})
    else:
        password = data.get("password", "")
        if password == "***":
            existing = await db.get_vod_storage(token.user_id)
            if existing:
                # get_vod_storage already returns the decrypted config as a dict
                existing_config = existing.get("config") or {}
                password = existing_config.get("password", "")
        connect_opts["password"] = password

    conn = None
    try:
        conn, seen = await hostkeys.connect_verified(
            _addrs, connect_opts, pinned=pinned, ignore=ignore, trust_unpinned=True, timeout=10)
        sftp = await conn.start_sftp_client()
        key_note = ""
        if seen and not pinned:
            key_note = f" Host key {seen} will be pinned on first upload."

        # Try to list the remote path
        if remote_path:
            files = await sftp.listdir(remote_path)
            mkv_count = sum(1 for f in files if f.lower().endswith(".mkv"))
            return web.json_response({
                "success": True,
                "message": f"Connected successfully. Found {mkv_count} MKV file(s) in {remote_path}.{key_note}"
            })
        else:
            return web.json_response({"success": True, "message": f"Connected successfully.{key_note}"})

    except hostkeys.HostKeyRefused as refused:
        return web.json_response({
            "success": False,
            "error": f"Host key changed: the server now presents {refused.fingerprint}, "
                     f"but {refused.expected} is pinned.",
        })
    except asyncio.TimeoutError:
        return web.json_response({"success": False, "error": "Connection timed out"})
    except asyncssh.Error as e:
        logger.warning(f"VOD storage test SSH error for user {token.user_id}: {e}")
        return web.json_response({"success": False, "error": "SSH connection failed"})
    except OSError as e:
        logger.warning(f"VOD storage test connection error for user {token.user_id}: {e}")
        return web.json_response({"success": False, "error": "Connection failed"})
    finally:
        if conn:
            conn.close()


async def http_list_vods(request: web.Request) -> web.Response:
    """List MKV files on user's remote SFTP storage (recursive).

    Returns files with paths relative to the VOD root, e.g.
    "StreamName/2026-02-08_12-00-00/chunk_000.mkv" or "old_recording.mkv".
    "recording_guard" (also on the 502 answers) is null, or says that the disk guard stopped or
    refused a recording of this user: {kind: "stopped"|"refused", code, message, stream_name, at}.
    """
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    guard = _vod_guard_public(token.user_id)  # shown on the error answers too: the storage may be the problem
    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error, "recording_guard": guard}, status=502)

    try:
        remote_root = storage["remote_path"].rstrip("/")
        files = []

        async def scan_dir(dir_path: str, rel_prefix: str):
            try:
                entries = await sftp.listdir(dir_path)
            except (asyncssh.SFTPError, OSError):
                return
            for name in entries:
                if name.startswith("."):
                    continue
                full_path = f"{dir_path}/{name}"
                rel_path = f"{rel_prefix}/{name}" if rel_prefix else name
                try:
                    attrs = await sftp.stat(full_path)
                except (asyncssh.SFTPError, OSError):
                    continue
                if attrs.permissions is not None and (attrs.permissions & 0o40000):
                    # Directory — recurse
                    await scan_dir(full_path, rel_path)
                elif name.lower().endswith(".mkv"):
                    files.append({
                        "name": rel_path,
                        "size": attrs.size or 0,
                        "modified": attrs.mtime or 0,
                    })

        await scan_dir(remote_root, "")

        # Sort
        sort_by = request.query.get("sort", "modified")
        reverse = request.query.get("order", "desc") == "desc"
        if sort_by == "name":
            files.sort(key=lambda f: f["name"].lower(), reverse=reverse)
        elif sort_by == "size":
            files.sort(key=lambda f: f["size"], reverse=reverse)
        else:
            files.sort(key=lambda f: f["modified"], reverse=reverse)

        return web.json_response({"files": files, "path": remote_root, "recording_guard": guard,
                                  "playback": await _vod_play_public()})
    except asyncssh.SFTPError as e:
        logger.error(f"VOD list SFTP error for user {token.user_id}: {e}")
        return web.json_response({"error": "SFTP operation failed", "recording_guard": guard}, status=502)
    except OSError as e:
        logger.error(f"VOD list connection error for user {token.user_id}: {e}")
        return web.json_response({"error": "Connection failed", "recording_guard": guard}, status=502)
    finally:
        conn.close()


async def http_download_vod(request: web.Request) -> web.Response:
    """Stream-download a VOD file from remote SFTP storage.

    Supports subdirectory paths like "StreamName/session/chunk_000.mkv".
    """
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    filename = request.match_info.get("filename", "")

    # Security: prevent path traversal
    if not filename or ".." in filename or filename.startswith("/"):
        return web.json_response({"error": "Invalid filename"}, status=400)
    if not filename.lower().endswith(".mkv"):
        return web.json_response({"error": "Only MKV files can be downloaded"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    response_started = False
    try:
        remote_path = f"{storage['remote_path'].rstrip('/')}/{filename}"
        attrs = await sftp.stat(remote_path)

        response = web.StreamResponse()
        response.content_type = "video/x-matroska"
        response.content_length = attrs.size
        safe_name = filename.split("/")[-1].replace('"', '\\"')
        response.headers["Content-Disposition"] = f'attachment; filename="{safe_name}"'
        await response.prepare(request)
        response_started = True

        CHUNK_SIZE = 262144  # 256 KB
        async with sftp.open(remote_path, "rb") as f:
            while True:
                chunk = await f.read(CHUNK_SIZE)
                if not chunk:
                    break
                await response.write(chunk)

        await response.write_eof()
        return response
    except asyncssh.SFTPError as e:
        logger.error(f"VOD download SFTP error for user {token.user_id}: {e}")
        if response_started:
            return response  # Headers already sent, can't send error JSON
        return web.json_response({"error": "SFTP operation failed"}, status=502)
    except OSError as e:
        logger.error(f"VOD download error for user {token.user_id}: {e}")
        if response_started:
            return response
        return web.json_response({"error": "Download failed"}, status=502)
    finally:
        conn.close()


async def http_download_vod_archive(request: web.Request) -> web.Response:
    """Download multiple VOD files as a zip archive streamed from SFTP.

    POST body: {"files": ["StreamName/session/chunk_000.mkv", ...]}
    """
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    files = data.get("files", [])
    if not files or not isinstance(files, list):
        return web.json_response({"error": "No files specified"}, status=400)
    if len(files) > 500:
        return web.json_response({"error": "Too many files (max 500)"}, status=400)

    # Validate all paths
    for f in files:
        if ".." in f or f.startswith("/"):
            return web.json_response({"error": f"Invalid path: {f}"}, status=400)
        if not f.lower().endswith(".mkv"):
            return web.json_response({"error": f"Not an MKV file: {f}"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    # Derive archive name from common prefix
    parts_list = [f.split("/") for f in files]
    if len(parts_list) > 1 and len(parts_list[0]) > 1 and all(p[0] == parts_list[0][0] for p in parts_list):
        archive_name = parts_list[0][0]
        if len(parts_list[0]) > 2 and all(len(p) > 1 and p[1] == parts_list[0][1] for p in parts_list):
            archive_name += f"_{parts_list[0][1]}"
    elif len(files) == 1:
        archive_name = files[0].rsplit("/", 1)[-1].replace(".mkv", "")
    else:
        archive_name = "vods"
    archive_name = re.sub(r'[^\w\s-]', '_', archive_name)

    response = web.StreamResponse()
    response.content_type = "application/zip"
    response.headers["Content-Disposition"] = f'attachment; filename="{archive_name}.zip"'
    await response.prepare(request)

    remote_root = storage["remote_path"].rstrip("/")

    import struct
    import binascii

    # Track entries for central directory (written after all file data)
    entries = []  # list of (fname_bytes, crc32, size, local_header_offset)
    offset = 0    # running byte offset in the stream

    for filepath in files:
        remote_path = f"{remote_root}/{filepath}"
        try:
            fname_bytes = filepath.encode("utf-8")
            local_header_offset = offset

            # Local file header (no compression, data descriptor flag set)
            header = struct.pack(
                '<4sHHHHHIIIHH',
                b'PK\x03\x04',     # signature
                20,                 # version needed (2.0)
                0x08,               # flags: bit 3 = data descriptor follows
                0,                  # compression: stored
                0,                  # mod time
                0,                  # mod date
                0,                  # crc32 (deferred to data descriptor)
                0,                  # compressed size (deferred)
                0,                  # uncompressed size (deferred)
                len(fname_bytes),   # filename length
                0,                  # extra field length
            ) + fname_bytes
            await response.write(header)
            offset += len(header)

            # Stream file data from SFTP, computing CRC as we go
            crc = 0
            total_size = 0
            CHUNK_SIZE = 262144
            async with sftp.open(remote_path, "rb") as f:
                while True:
                    chunk = await f.read(CHUNK_SIZE)
                    if not chunk:
                        break
                    crc = binascii.crc32(chunk, crc) & 0xFFFFFFFF
                    total_size += len(chunk)
                    await response.write(chunk)
            offset += total_size

            # Data descriptor (with signature)
            desc = struct.pack('<4sIII',
                b'PK\x07\x08',   # signature
                crc,              # crc32
                total_size,       # compressed size (same as uncompressed for stored)
                total_size,       # uncompressed size
            )
            await response.write(desc)
            offset += len(desc)

            entries.append((fname_bytes, crc, total_size, local_header_offset))

        except (asyncssh.SFTPError, OSError) as e:
            logger.warning(f"Skipping VOD file in archive {filepath}: {e}")
            continue

    # Central directory
    cd_offset = offset
    cd_size = 0
    for fname_bytes, crc, size, local_offset in entries:
        cd_entry = struct.pack(
            '<4sHHHHHHIIIHHHHHII',
            b'PK\x01\x02',     # central directory signature
            20,                 # version made by (2.0)
            20,                 # version needed (2.0)
            0x08,               # flags: data descriptor
            0,                  # compression: stored
            0,                  # mod time
            0,                  # mod date
            crc,                # crc32
            size,               # compressed size
            size,               # uncompressed size
            len(fname_bytes),   # filename length
            0,                  # extra field length
            0,                  # file comment length
            0,                  # disk number start
            0,                  # internal file attributes
            0,                  # external file attributes
            local_offset,       # relative offset of local header
        ) + fname_bytes
        await response.write(cd_entry)
        cd_size += len(cd_entry)

    # End of central directory record
    entry_count = len(entries)
    eocd = struct.pack(
        '<4sHHHHIIH',
        b'PK\x05\x06',     # EOCD signature
        0,                  # disk number
        0,                  # disk with central dir
        entry_count,        # entries on this disk
        entry_count,        # total entries
        cd_size,            # size of central directory
        cd_offset,          # offset of central directory
        0,                  # comment length
    )
    await response.write(eocd)

    await response.write_eof()
    conn.close()
    return response


async def http_delete_vod(request: web.Request) -> web.Response:
    """Delete a VOD file from remote SFTP storage."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        return refusal

    filename = request.match_info.get("filename", "")

    # Security: prevent path traversal
    if not filename or ".." in filename or filename.startswith("/"):
        return web.json_response({"error": "Invalid filename"}, status=400)
    if not filename.lower().endswith(".mkv"):
        return web.json_response({"error": "Only MKV files can be deleted"}, status=400)

    storage = await db.get_vod_storage(token.user_id)
    if not storage:
        return web.json_response({"error": "No VOD storage configured"}, status=404)

    conn, sftp, error = await _connect_vod_sftp(token.user_id)
    if error:
        return web.json_response({"error": error}, status=502)

    try:
        remote_path = f"{storage['remote_path'].rstrip('/')}/{filename}"
        await sftp.remove(remote_path)
        if _vod_play_cache is not None:
            _vod_play_cache.purge(owner=token.user_id, path=filename)
        return web.json_response({"message": f"Deleted {filename}"})
    except asyncssh.SFTPError as e:
        logger.error(f"VOD delete SFTP error for user {token.user_id}: {e}")
        return web.json_response({"error": "SFTP operation failed"}, status=502)
    except OSError as e:
        logger.error(f"VOD delete error for user {token.user_id}: {e}")
        return web.json_response({"error": "Delete operation failed"}, status=502)
    finally:
        conn.close()


# =============================================================================
# VOD playback in the browser (remux of one MKV chunk into a cached MP4)
# =============================================================================
#
# GET /api/vods/play/{listed path}.mp4 serves the owner's chunk as MP4 (Range works). When the
# MP4 is not cached yet the route starts one job and answers 202; GET /api/vods/play-status/...
# says how it is going. A job pulls the chunk over the pinned SFTP connection, probes it, remuxes it
# with ffmpeg -c copy and puts the result in the byte-capped cache (vod_play.py). Playback is
# owner-only: the path is always resolved against the caller's own storage, whoever the caller is.

VOD_PLAY_SLOTS = 2                 # remux jobs running at the same time
VOD_PLAY_MAX_PER_USER = 3          # queued plus running jobs of one member
VOD_PLAY_MAX_JOBS = 16             # all members together
VOD_PLAY_FAST_WAIT = 1.5           # seconds a request waits for its job before it answers 202
VOD_PLAY_REQUEST_DEADLINE = 20.0   # seconds for everything a play request does before it answers (storage lookups, live check, FAST_WAIT)
VOD_PLAY_STAT_TTL = 15.0           # seconds a remote size and modification time is trusted
VOD_PLAY_KEEP_SECONDS = 600        # a finished job (and a download-only verdict) is remembered this long
VOD_PLAY_FAILED_KEEP = 30          # a failed job is shown to the status route this long, then retried
VOD_PLAY_PULL_TIMEOUT = 900
VOD_PLAY_PROBE_TIMEOUT = 60
VOD_PLAY_REMUX_TIMEOUT = 300
VOD_PLAY_RESERVE_WAIT = 600
VOD_PLAY_PROBE_MAX_BYTES = 1024 * 1024
VOD_SESSION_SEG_WAIT = 55.0        # a segment request waits this long for its job, then answers 503 (proxy limit: 100 s)
VOD_SESSION_PROBE_MAX = 4          # session duration probes running at the same time, all members together
VOD_SESSION_PROBE_FAILED_KEEP = 30

_vod_play_cache: Optional["vod_play.PlayCache"] = None
_vod_play_refused: Optional[str] = None      # why the cache folder is not usable (None: it is)
_vod_play_jobs: dict = {}                     # (owner, path) -> job dict
_vod_play_tasks: set = set()                  # strong references to the running job tasks
_vod_play_stats: dict = {}                    # (owner, ident, path) -> (size, mtime, at)
_vod_play_sem: Optional[asyncio.Semaphore] = None
_vod_play_sem_loop = None
_vod_play_locks: dict = {}                    # job key -> asyncio.Lock
_vod_session_probes: dict = {}                # (owner, folder) -> probe dict (duration measuring of a session)


def _vod_play_semaphore() -> asyncio.Semaphore:
    global _vod_play_sem, _vod_play_sem_loop
    loop = asyncio.get_running_loop()
    if _vod_play_sem is None or _vod_play_sem_loop is not loop:
        _vod_play_sem, _vod_play_sem_loop = asyncio.Semaphore(VOD_PLAY_SLOTS), loop
    return _vod_play_sem


def _vod_play_setup(path: Optional[str] = None) -> Optional[str]:
    """Create the cache folder and read its index. Returns None, or why the folder cannot be used
    (then playback answers 503 and nothing in the folder is touched). Blocking: run in a thread."""
    global _vod_play_cache, _vod_play_refused
    folder = path or Config.VOD_PLAY_CACHE_DIR
    try:
        vod_play.prepare_dir(folder, _PROJECT_ROOT, (STATIC_DIR,),
                             (VOD_TEMP_DIR, Config.VOD_TEMP_DIR_DEFAULT, Config.RECORDINGS_DIR))
    except (OSError, ValueError) as e:
        _vod_play_cache, _vod_play_refused = None, str(e)
        logger.error(f"VOD playback cache folder {folder} is not usable: {e}. "
                     f"Browser playback of VODs is off until this is fixed")
        return _vod_play_refused
    cache = vod_play.PlayCache(folder)
    stats = cache.reconcile()
    if stats["dropped"] or stats["strays"]:
        logger.info(f"VOD playback cache: kept {stats['kept']}, dropped {stats['dropped']} "
                    f"entries, removed {stats['strays']} stray file(s)")
    _vod_play_cache, _vod_play_refused = cache, None
    return None


async def _vod_play_reconcile_owners() -> None:
    """Drop entries of owners who no longer have VOD storage, or whose storage points elsewhere now."""
    cache = _vod_play_cache
    if cache is None:
        return
    for owner, idents in list(cache.owners().items()):
        try:
            storage = await db.get_vod_storage(owner)
        except Exception as e:
            logger.debug(f"VOD playback cache: storage of user {owner} unreadable: {e}")
            continue
        if not storage:
            cache.purge(owner=owner)
        else:
            cache.purge(owner=owner, ident_not=vod_play.storage_ident(storage))


def _vod_play_purge(owner: Optional[int] = None, ident_not: Optional[str] = None) -> None:
    """Forget what the cache and the job table hold for an owner (account or storage removed)."""
    for k in [k for k in _vod_play_jobs if owner is None or k[0] == owner]:
        job = _vod_play_jobs.get(k)
        if job and job.get("task") and not job["task"].done():
            job["task"].cancel()
        _vod_play_jobs.pop(k, None)
    for k in [k for k in _vod_session_probes if owner is None or k[0] == owner]:
        probe = _vod_session_probes.pop(k, None)
        if probe and probe.get("task") and not probe["task"].done():
            probe["task"].cancel()
    for k in [k for k in _vod_play_stats if owner is None or k[0] == owner]:
        _vod_play_stats.pop(k, None)
    if _vod_play_cache is not None:
        _vod_play_cache.purge(owner=owner, ident_not=ident_not)


async def _vod_play_cancel_all() -> None:
    tasks = list(_vod_play_tasks)
    for t in tasks:
        t.cancel()
    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)


async def _vod_play_cap() -> int:
    try:
        raw = await db.get_setting("vod_play_cache_mb")
    except Exception as e:
        logger.debug(f"vod_play_cache_mb unreadable, using the default: {e}")
        raw = None
    return vod_play.cache_cap_bytes(raw)


def _vod_play_off_message(cap: int) -> Optional[str]:
    if _vod_play_refused is not None or _vod_play_cache is None:
        return "Browser playback is not available on this server right now. Download the chunk instead."
    if cap <= 0:
        return "Browser playback is switched off on this server. Download the chunk instead."
    return None


async def _vod_play_public() -> dict:
    """What My VODs needs to know: whether to offer the Play button."""
    message = _vod_play_off_message(await _vod_play_cap())
    return {"enabled": message is None, "message": message}


def _vod_play_reply(data: dict, status: int = 200, retry_after: Optional[int] = None) -> web.Response:
    headers = {"Cache-Control": "private, no-store"}
    if retry_after:
        headers["Retry-After"] = str(retry_after)
    return web.json_response(data, status=status, headers=headers)


def _vod_play_file(path: str) -> web.FileResponse:
    resp = web.FileResponse(path, headers={
        "Cache-Control": "private, no-cache",       # never stored by a shared cache; the browser revalidates
        "Content-Type": "video/mp4",
        "Content-Disposition": "inline",
        "X-Content-Type-Options": "nosniff",
    })
    return resp


def _vod_play_prune_jobs() -> None:
    now = monotonic()
    for k, job in list(_vod_play_jobs.items()):
        fin = job.get("finished")
        if fin is None:
            continue
        keep = VOD_PLAY_FAILED_KEEP if job["state"] == "failed" else VOD_PLAY_KEEP_SECONDS
        if now - fin > keep:
            _vod_play_jobs.pop(k, None)
    if len(_vod_play_jobs) > 500:
        for k in sorted((k for k, j in _vod_play_jobs.items() if j.get("finished") is not None),
                        key=lambda k: _vod_play_jobs[k]["finished"])[:100]:
            _vod_play_jobs.pop(k, None)
    for k, lock in list(_vod_play_locks.items()):
        if not lock.locked() and not (k in _vod_play_jobs and _vod_play_jobs[k]["finished"] is None):
            _vod_play_locks.pop(k, None)
    for k, v in list(_vod_play_stats.items()):
        if now - v[2] > 600:
            _vod_play_stats.pop(k, None)


_VOD_PLAY_STORAGE_DOWN = "The VOD storage could not be reached right now; try again in a minute"


class _VodPlayRemoteError(Exception):
    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status, self.message = status, message


class _VodLink:
    """One SFTP connection for the steps of one request (size lookup, live check), opened on first use
    and closed by the request. A failed dial is remembered, so one request never dials twice."""

    def __init__(self, user_id: int):
        self.user_id = user_id
        self.conn = self.sftp = None
        self.error: Optional[str] = None
        self.dials = 0

    async def client(self):
        if self.sftp is None:
            if self.error is not None:
                raise _VodPlayRemoteError(502, self.error)
            self.dials += 1
            conn, sftp, error = await _connect_vod_sftp(self.user_id)
            if error:
                self.error = error
                raise _VodPlayRemoteError(502, error)
            self.conn, self.sftp = conn, sftp
        return self.sftp

    def close(self) -> None:
        if self.conn is not None:
            self.conn.close()
        self.conn = self.sftp = None


async def _vod_play_remote_stat(user_id: int, storage: dict, path: str, ident: str,
                                fresh: bool = False, link: Optional[_VodLink] = None) -> tuple:
    """(size, mtime) of the owner's chunk, from the pinned SFTP connection (remembered for a few seconds
    so that the Range requests of one playback do not each open a connection). Raises _VodPlayRemoteError:
    404 only when the storage says there is no such regular file, 502 when it cannot be reached or does not answer."""
    memo_key = (user_id, ident, path)
    hit = _vod_play_stats.get(memo_key)
    if hit and not fresh and monotonic() - hit[2] < VOD_PLAY_STAT_TTL:
        return hit[0], hit[1]
    own = link is None
    link = link or _VodLink(user_id)
    try:
        sftp = await link.client()
        remote = f"{storage['remote_path'].rstrip('/')}/{path}"
        try:
            attrs = await asyncio.wait_for(sftp.stat(remote), VOD_SFTP_META_TIMEOUT)
        except (asyncssh.SFTPNoSuchFile, asyncssh.SFTPNoSuchPath):
            _vod_play_stats.pop(memo_key, None)
            raise _VodPlayRemoteError(404, "VOD not found")      # the storage says there is no such file
        except (asyncssh.Error, OSError, asyncio.TimeoutError) as e:
            # a timeout, a lost connection or a refusal says nothing about the file: not "not found"
            _vod_play_stats.pop(memo_key, None)
            logger.warning(f"VOD playback stat failed for user {user_id}: {type(e).__name__}")
            raise _VodPlayRemoteError(502, _VOD_PLAY_STORAGE_DOWN)
        perms = attrs.permissions
        if perms is not None and not _stat.S_ISREG(perms):
            _vod_play_stats.pop(memo_key, None)
            raise _VodPlayRemoteError(404, "VOD not found")
        size, mtime = int(attrs.size or 0), int(attrs.mtime or 0)
        _vod_play_stats[memo_key] = (size, mtime, monotonic())
        return size, mtime
    finally:
        if own:
            link.close()


async def _vod_play_is_live_newest(user_id: int, storage: dict, path: str, link: Optional[_VodLink] = None) -> bool:
    """True when the chunk is the newest of a folder a recording is writing to right now."""
    base = storage["remote_path"].rstrip("/")
    dirpart = path.rpartition("/")[0]
    remote_dir = f"{base}/{dirpart}" if dirpart else base
    dirs = _vod_remote_dirs_in_use()
    if "*" not in dirs and remote_dir not in {str(d).rstrip("/") for d in dirs}:
        return False
    mine = vod_play.chunk_number(path.rpartition("/")[2])
    if mine is None:
        return False
    own = link is None
    link = link or _VodLink(user_id)
    try:
        try:
            sftp = await link.client()
        except _VodPlayRemoteError:
            return True        # cannot tell: the safe answer is to leave it alone
        try:
            names = await asyncio.wait_for(sftp.listdir(remote_dir), VOD_SFTP_META_TIMEOUT)
        except (asyncssh.Error, OSError, asyncio.TimeoutError):
            return True
    finally:
        if own:
            link.close()
    numbers = [n for n in (vod_play.chunk_number(x) for x in names) if n is not None]
    return bool(numbers) and mine >= max(numbers)


async def _vod_play_run_tool(argv: list, timeout: float, cwd: str, capture: bool):
    """Run ffmpeg or ffprobe at low priority on a local file. Returns (returncode, stdout bytes).
    On a timeout or a cancel the process is killed (it is ours) and reaped."""
    process = await _media_exec(
        argv, "idle", stdin=asyncio.subprocess.DEVNULL,
        stdout=asyncio.subprocess.PIPE if capture else asyncio.subprocess.DEVNULL,
        stderr=asyncio.subprocess.PIPE, cwd=cwd)

    async def read(stream, cap):
        buf = bytearray()
        while True:
            block = await stream.read(65536)
            if not block:
                return bytes(buf)
            if len(buf) < cap:
                buf += block[:cap - len(buf)]

    try:
        readers = [read(process.stderr, 4096)]
        if capture:
            readers.append(read(process.stdout, VOD_PLAY_PROBE_MAX_BYTES))
        results = await asyncio.wait_for(asyncio.gather(*readers), timeout)
        await asyncio.wait_for(process.wait(), 10)
        if not capture:
            err = results[0].decode("utf-8", "replace").strip()
            if err:
                logger.info(f"VOD playback {argv[0]}: {err[:300]}")
        return process.returncode, (results[1] if capture else b"")
    finally:
        if process.returncode is None:
            try:
                process.kill()
            except ProcessLookupError:
                pass
            try:
                await asyncio.wait_for(process.wait(), 10)
            except (asyncio.TimeoutError, ProcessLookupError):
                pass


async def _vod_play_pull(user_id: int, storage: dict, path: str, dest: str, size: int, mtime: int) -> None:
    """Copy the remote chunk to *dest* (0600, new file). Raises _VodPlayRemoteError."""
    conn, sftp, error = await _connect_vod_sftp(user_id)
    if error:
        raise _VodPlayRemoteError(502, error)
    fd = None
    try:
        remote = f"{storage['remote_path'].rstrip('/')}/{path}"
        attrs = await asyncio.wait_for(sftp.stat(remote), VOD_SFTP_META_TIMEOUT)
        if int(attrs.size or 0) != size or int(attrs.mtime or 0) != mtime:
            raise _VodPlayRemoteError(409, "The chunk changed while it was being prepared; try again")
        fd = os.open(dest, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        got = 0
        async with sftp.open(remote, "rb") as src:
            while True:
                block = await src.read(1024 * 1024)
                if not block:
                    break
                got += len(block)
                if got > size:
                    raise _VodPlayRemoteError(409, "The chunk changed while it was being prepared; try again")
                await asyncio.to_thread(os.write, fd, block)
        if got != size:
            raise _VodPlayRemoteError(409, "The chunk changed while it was being prepared; try again")
    except (asyncssh.SFTPError, OSError, asyncio.TimeoutError) as e:
        logger.warning(f"VOD playback pull failed for user {user_id}: {type(e).__name__}")
        raise _VodPlayRemoteError(502, "Could not read the chunk from the VOD storage")
    finally:
        if fd is not None:
            os.close(fd)
        conn.close()


def _vod_play_job_key(owner: int, path: str, kind: str = "mp4") -> tuple:
    return (owner, path) if kind == "mp4" else (owner, path, kind)


async def _vod_play_job(job: dict, storage: dict, size: int, mtime: int) -> None:
    """The job: reserve room, pull, probe, remux, store. Sets job state; leaves nothing behind on failure.
    job["kind"] is "mp4" (one chunk for the single-chunk player) or "ts" (one HLS segment of a session)."""
    cache = _vod_play_cache
    owner, path, key = job["owner"], job["path"], job["key"]
    kind = job.get("kind", "mp4")
    lock = _vod_play_locks.setdefault(_vod_play_job_key(owner, path, kind), asyncio.Lock())
    reserve = vod_play.job_reserve(size, kind, job.get("duration"))
    reserved = False
    work = None
    try:
        async with lock:                                   # one job per chunk, a newer version waits
            async with _vod_play_semaphore():              # at most VOD_PLAY_SLOTS at the same time
                cap = await _vod_play_cap()
                message = _vod_play_off_message(cap)
                if message:
                    raise _VodPlayRemoteError(503, message)
                if reserve > cap:
                    job["state"], job["reason"] = "unplayable", (
                        "it is too large for the playback cache of this server")
                    return
                job["state"] = "waiting"
                if job.get("prefetch"):
                    # ahead of the play position: only with room to spare, never at the cost of a copy in use
                    if not cache.try_reserve_free(reserve, cap):
                        raise _VodPlayRemoteError(503, "No room to prepare it ahead")
                elif not await cache.reserve(reserve, cap, VOD_PLAY_RESERVE_WAIT):
                    raise _VodPlayRemoteError(503, "The playback cache is busy; try again in a minute")
                reserved = True
                min_free = (await _vod_guard_limits())[0]
                free = await asyncio.to_thread(vod_staging.free_bytes, cache.root)
                if free - cache.reserved < min_free:           # every running job's reservation, this one included
                    raise _VodPlayRemoteError(
                        503, "Not enough free disk space on the server to prepare this chunk right now")
                work = cache.new_work_dir()
                src, out = os.path.join(work, "src.mkv"), os.path.join(work, "out.mp4")
                job["state"] = "pulling"
                await asyncio.wait_for(_vod_play_pull(owner, storage, path, src, size, mtime), VOD_PLAY_PULL_TIMEOUT)
                job["state"] = "probing"
                code, raw = await _vod_play_run_tool(vod_play.ffprobe_argv(src), VOD_PLAY_PROBE_TIMEOUT, work, True)
                try:
                    info = json.loads(raw.decode("utf-8", "replace")) if code == 0 else None
                except ValueError:
                    info = None
                ok, why = vod_play.verdict(info) if info is not None else (False, "the file could not be read")
                if not ok:
                    job["state"], job["reason"] = "unplayable", why
                    return
                job["state"] = "remuxing"
                limit = (vod_play.output_limit(size) if kind == "mp4"
                         else vod_play.output_limit(size, kind, job.get("duration")))
                code, _ = await _vod_play_run_tool(
                    vod_play.remux_argv(src, out, limit, kind), VOD_PLAY_REMUX_TIMEOUT, work, False)
                os.unlink(src)
                osize = os.lstat(out).st_size if os.path.lexists(out) else 0
                if code != 0 or osize <= 0 or osize >= limit:
                    raise _VodPlayRemoteError(500, "The chunk could not be converted")
                if kind == "mp4" and not vod_play.index_first(out):
                    raise _VodPlayRemoteError(500, "The chunk could not be converted")
                code, raw = await _vod_play_run_tool(
                    vod_play.ffprobe_argv(out, "mov" if kind == "mp4" else "mpegts"),
                    VOD_PLAY_PROBE_TIMEOUT, work, True)
                try:
                    check = json.loads(raw.decode("utf-8", "replace")) if code == 0 else None
                except ValueError:
                    check = None
                if check is None or not vod_play.verdict(check)[0]:
                    raise _VodPlayRemoteError(500, "The chunk could not be converted")
                seconds = vod_play.format_duration(check)
                if kind == "ts" and seconds is None:
                    raise _VodPlayRemoteError(500, "The chunk could not be converted")
                meta = {"owner": owner, "ident": job["ident"], "path": path, "rsize": size, "rmtime": mtime,
                        "kind": kind}
                stored = cache.add(key, out, meta, reserve)
                reserved = False                           # add() gave the reservation back either way
                if not stored:
                    raise _VodPlayRemoteError(500, "The chunk could not be stored")
                if kind == "ts":
                    # the length of what a player gets is the one the playlist should say
                    cache.set_duration(owner, job["ident"], path, size, mtime, seconds)
                cache.evict_to(await _vod_play_cap())
                job["state"] = "ready"
    except _VodPlayRemoteError as e:
        job["state"], job["error"], job["status"] = "failed", e.message, e.status
    except asyncio.CancelledError:
        job["state"], job["error"] = "failed", "Preparation was cancelled"
        raise
    except asyncio.TimeoutError:
        logger.warning(f"VOD playback job for user {owner} timed out")
        job["state"], job["error"] = "failed", "Preparing the chunk took too long"
    except Exception as e:
        logger.error(f"VOD playback job for user {owner} failed: {type(e).__name__}: {e}")
        job["state"], job["error"] = "failed", "The chunk could not be prepared"
    finally:
        if reserved:
            cache.release(reserve)
        if work:
            vod_play._remove_path(work)
        job["finished"] = monotonic()
        job["done"].set()


def _vod_play_job_view(job: Optional[dict]) -> dict:
    if job is None:
        return {"state": "idle"}
    state = job["state"]
    if state == "ready":
        return {"state": "ready"}
    if state == "unplayable":
        return {"state": "unplayable", "reason": job.get("reason"),
                "message": vod_play.download_only_message(job.get("reason") or "unsupported format")}
    if state == "failed":
        return {"state": "failed", "error": job.get("error") or "The chunk could not be prepared"}
    return {"state": "preparing", "stage": state}


async def _vod_play_prelude(request: web.Request, token, session: bool = False):
    """Shared start of the play routes, after their own sign-in check. Returns
    (token, storage, path, cap, None) or (None, None, None, 0, response). With *session* the "path" is the
    (folder, kind, stem) of a session URL instead of a chunk path."""
    if session:
        path = vod_play.session_from_url(request.match_info.get("name", ""))
    else:
        path = vod_play.chunk_path_from_url(request.match_info.get("name", ""))
    storage = await db.get_vod_storage(token.user_id)
    if path is None or not storage:
        return None, None, None, 0, _vod_play_reply({"error": "VOD not found"}, 404)
    cap = await _vod_play_cap()
    message = _vod_play_off_message(cap)
    if message:
        if cap <= 0 and _vod_play_cache is not None:
            _vod_play_cache.purge()                       # switched off: give the disk back
        return None, None, None, 0, _vod_play_reply({"error": message, "code": "playback_off"}, 503)
    _vod_play_cache.evict_to(cap)                         # a lowered cap takes effect here
    _vod_play_prune_jobs()
    return token, storage, path, cap, None


async def http_play_vod(request: web.Request) -> web.StreamResponse:
    """GET /api/vods/play/{path}.mp4 - the owner's chunk as MP4 (200/206), or 202 while it is prepared,
    404 (not yours or not there), 409 (newest chunk of a live recording), 415 (download only),
    429 (too many jobs), 503 (playback off or no room), 502 (storage unreachable)."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        refusal.headers["Cache-Control"] = "private, no-store"
        return refusal
    token, storage, path, cap, refusal = await _vod_play_prelude(request, token)
    if refusal is not None:
        return refusal
    user_id = token.user_id
    ident = vod_play.storage_ident(storage)
    cache = _vod_play_cache
    # The start of a playback (no Range header, or a range from byte 0) reads the chunk's size and
    # time afresh, so a chunk that changed on the storage is never served from an old copy; the
    # continuation ranges of that playback use the answer remembered for a few seconds.
    rng = request.headers.get("Range")
    start_of_playback = not rng or re.match(r"^\s*bytes\s*=\s*0*-", rng) is not None
    # One connection serves the size lookup and the live check, and one deadline covers everything up to
    # the answer (the wait for a fast job included), so a storage that hangs cannot hold the request for minutes.
    link = _VodLink(user_id)
    try:
        async with asyncio.timeout(VOD_PLAY_REQUEST_DEADLINE):
            size, mtime = await _vod_play_remote_stat(user_id, storage, path, ident, fresh=start_of_playback,
                                                      link=link)
            outcome, payload = await _vod_play_obtain(user_id, storage, ident, path, size, mtime, "mp4",
                                                      VOD_PLAY_FAST_WAIT, link=link)
    except _VodPlayRemoteError as e:
        return _vod_play_reply({"error": e.message}, e.status)
    except TimeoutError:
        logger.warning(f"VOD playback request for user {user_id} passed its deadline")
        return _vod_play_reply({"error": "The VOD storage is slow to answer; try again in a few seconds"},
                               503, retry_after=10)
    finally:
        link.close()
    if outcome == "file":
        return _vod_play_file(payload)
    if outcome == "live":
        return _vod_play_reply(
            {"error": "This is the newest chunk of a stream that is live right now; "
                      "it is still being recorded. Watch it when the stream has ended or the next chunk exists."},
            409)
    if outcome == "limit":
        return _vod_play_reply({"error": payload[1]}, payload[0], retry_after=10)
    job = payload
    if outcome == "unplayable":
        return _vod_play_reply(
            {"error": vod_play.download_only_message(job.get("reason") or "unsupported format"),
             "reason": job.get("reason"), "state": "unplayable"}, 415)
    if outcome == "failed":
        return _vod_play_reply({"error": job.get("error") or "The chunk could not be prepared", "state": "failed"},
                               job.get("status") or 500)
    return _vod_play_reply(dict(_vod_play_job_view(job), status_url=_vod_play_status_url(path)), 202, retry_after=2)


async def _vod_play_obtain(user_id: int, storage: dict, ident: str, path: str, size: int, mtime: int,
                           kind: str, wait: float, duration: Optional[float] = None,
                           prefetch: bool = False, link: Optional[_VodLink] = None) -> tuple:
    """The one place that turns a chunk into a cached output of *kind* ("mp4": the single-chunk player,
    "ts": a segment of a session) or starts, joins and waits for the job that makes it. Both play
    routes use it, so the gate, the cache, the job table, the locks and the slot limit are the same.

    Returns (outcome, payload):
      "file"        the cached file's path
      "unplayable"  the job (download only)
      "failed"      the job
      "preparing"   the job, still running after *wait* seconds
      "live"        None: the newest chunk of a folder a recording is writing to right now
      "limit"       (status, message): too many jobs
    """
    cache = _vod_play_cache
    key = vod_play.entry_key(user_id, ident, path, size, mtime, kind)
    jobkey = _vod_play_job_key(user_id, path, kind)
    cached = cache.get(key)
    if cached:
        return "file", cached

    job = _vod_play_jobs.get(jobkey)
    if job is not None and job["state"] in ("ready", "failed") and job["key"] != key:
        job = None                                            # an answer about another version of the chunk
    if job is not None and job["state"] == "ready":
        job = None                                            # evicted since: prepare it again
    if job is not None and job["state"] == "failed":
        job = None                                            # try again
    if job is not None and job["state"] == "unplayable":
        if job["key"] == key:
            return "unplayable", job
        job = None

    if job is None:
        if await _vod_play_is_live_newest(user_id, storage, path, link):
            return "live", None
        # no await from here to the registration: two requests for one chunk end up with one job
        current = _vod_play_jobs.get(jobkey)
        if current is not None and current["finished"] is None:
            job = current
    if job is None:
        active = [j for j in _vod_play_jobs.values() if j["finished"] is None]
        if len([j for j in active if j["owner"] == user_id]) >= VOD_PLAY_MAX_PER_USER:
            return "limit", (429, "Too many chunks are being prepared; wait for one to finish")
        if len(active) >= VOD_PLAY_MAX_JOBS:
            return "limit", (503, "The server is busy preparing videos; try again shortly")
        job = {"owner": user_id, "path": path, "key": key, "ident": ident, "state": "queued", "kind": kind,
               "finished": None, "done": asyncio.Event(), "started": monotonic(),
               "duration": duration, "prefetch": prefetch}
        _vod_play_jobs[jobkey] = job
        task = asyncio.create_task(_vod_play_job(job, storage, size, mtime))
        job["task"] = task
        _vod_play_tasks.add(task)
        task.add_done_callback(_vod_play_tasks.discard)
    if wait <= 0:
        return "preparing", job

    try:
        await asyncio.wait_for(asyncio.shield(job["done"].wait()), wait)
    except asyncio.TimeoutError:
        pass
    if job["state"] == "ready" and job["key"] == key:
        cached = cache.get(key)
        if cached:
            return "file", cached
    if job["state"] == "unplayable" and job["key"] == key:
        return "unplayable", job
    if job["state"] == "failed":
        return "failed", job
    return "preparing", job


def _vod_play_status_url(path: str) -> str:
    from urllib.parse import quote
    return "/api/vods/play-status/" + quote(path, safe="/") + ".mp4"


async def http_play_vod_status(request: web.Request) -> web.Response:
    """GET /api/vods/play-status/{path}.mp4 - {state: idle|preparing|ready|unplayable|failed, ...}.
    Never starts a job and never opens a connection to the storage."""
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        refusal.headers["Cache-Control"] = "private, no-store"
        return refusal
    token, storage, path, cap, refusal = await _vod_play_prelude(request, token)
    if refusal is not None:
        return refusal
    job = _vod_play_jobs.get((token.user_id, path))
    view = _vod_play_job_view(job)
    if job is None:
        ident = vod_play.storage_ident(storage)
        if any(e["owner"] == token.user_id and e["path"] == path and e["ident"] == ident
               and e.get("kind", "mp4") == "mp4" for e in _vod_play_cache.entries.values()):
            view = {"state": "ready"}
    return _vod_play_reply(view)


# -----------------------------------------------------------------------------
# Whole-session playback: GET /api/vods/session/{folder}/index.m3u8 and .../chunk_NNN.ts
# -----------------------------------------------------------------------------
#
# The chunks of one session folder as one HLS timeline. The playlist is written from the measured
# duration of every chunk (vod_play.PlayCache.durations): the recorder stores one at upload time, and for
# an older session a probe reads only the first 256 KB of each chunk (the matroska header carries the
# length), or converts the chunk when its header has none. The playlist request never pulls a chunk: it
# lists the folder over one SFTP connection and answers 202 {state: preparing} until all durations are
# known. A segment is one chunk remuxed to MPEG-TS by the same job machinery as the single-chunk MP4
# (_vod_play_obtain); a request waits for its job at most VOD_SESSION_SEG_WAIT seconds (under the proxy's
# 100 s) and then answers 503 with Retry-After, which hls.js retries. The next segment is prepared ahead
# when it fits in the cache without evicting anything. Same owner-only rule as the single-chunk routes.

def _vod_play_ts_file(path: str) -> web.FileResponse:
    return web.FileResponse(path, headers={
        "Cache-Control": "private, no-cache",
        "Content-Type": "video/mp2t",
        "Content-Disposition": "inline",
        "X-Content-Type-Options": "nosniff",
    })


def _vod_session_remote_dir(storage: dict, folder: str) -> str:
    return f"{storage['remote_path'].rstrip('/')}/{folder}"


def _vod_session_is_live(storage: dict, folder: str) -> bool:
    """True when a recording is writing to this session folder right now."""
    remote_dir = _vod_session_remote_dir(storage, folder)
    dirs = _vod_remote_dirs_in_use()
    return "*" in dirs or remote_dir in {str(d).rstrip("/") for d in dirs}


async def _vod_session_listing(user_id: int, storage: dict, folder: str) -> list:
    """[(number, filename, size, mtime)] of the regular chunk files in the folder, in chunk order, from one
    SFTP connection and one directory read. Raises _VodPlayRemoteError (404 no such folder, 502)."""
    conn, sftp, error = await _connect_vod_sftp(user_id)
    if error:
        raise _VodPlayRemoteError(502, error)
    try:
        try:
            names = await asyncio.wait_for(sftp.readdir(_vod_session_remote_dir(storage, folder)),
                                           VOD_SFTP_META_TIMEOUT * 2)
        except (asyncssh.SFTPError, OSError, asyncio.TimeoutError):
            raise _VodPlayRemoteError(404, "VOD not found")
    finally:
        conn.close()
    listing = []
    for entry in names:
        perms = entry.attrs.permissions
        if perms is not None and not _stat.S_ISREG(perms):
            continue
        listing.append((entry.filename if isinstance(entry.filename, str) else entry.filename.decode("utf-8", "replace"),
                        int(entry.attrs.size or 0), int(entry.attrs.mtime or 0)))
    return vod_play.session_chunks(listing)


async def _vod_session_probe_head(owner: int, storage: dict, ident: str, path: str, size: int, mtime: int) -> bool:
    """Learn a chunk's length (and whether it can be played) from its first bytes only. True when the
    duration is now remembered; False when the header has none (the chunk then needs a full conversion).
    Raises _VodPlayRemoteError."""
    cache = _vod_play_cache
    cap = await _vod_play_cap()
    if not await cache.reserve(vod_play.HEAD_BYTES, cap, 60):
        raise _VodPlayRemoteError(503, "The playback cache is busy; try again in a minute")
    work = None
    try:
        work = cache.new_work_dir()
        head = os.path.join(work, "head.mkv")
        conn, sftp, error = await _connect_vod_sftp(owner)
        if error:
            raise _VodPlayRemoteError(502, error)
        try:
            remote = f"{storage['remote_path'].rstrip('/')}/{path}"
            async with sftp.open(remote, "rb") as src:
                data = await asyncio.wait_for(src.read(vod_play.HEAD_BYTES), VOD_SFTP_META_TIMEOUT * 2)
        except (asyncssh.SFTPError, OSError, asyncio.TimeoutError):
            raise _VodPlayRemoteError(502, "Could not read the chunk from the VOD storage")
        finally:
            conn.close()
        fd = os.open(head, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, "wb") as fh:
            fh.write(data)
        async with _vod_play_semaphore():
            code, raw = await _vod_play_run_tool(vod_play.head_probe_argv(head), VOD_PLAY_PROBE_TIMEOUT, work, True)
        try:
            info = json.loads(raw.decode("utf-8", "replace")) if raw else None
        except ValueError:
            info = None
        if not isinstance(info, dict):
            return False
        ok, why = vod_play.verdict(info)
        seconds = vod_play.format_duration(info)
        if not ok:
            cache.set_duration(owner, ident, path, size, mtime, seconds or 1.0, False, why, save=False)
            return True
        if seconds is None:
            return False
        cache.set_duration(owner, ident, path, size, mtime, seconds, True, "", save=False)
        return True
    finally:
        cache.release(vod_play.HEAD_BYTES)
        if work:
            vod_play._remove_path(work)


async def _vod_session_probe_job(probe: dict, storage: dict, todo: list) -> None:
    """Measure the chunks that have no remembered duration, one after the other."""
    cache = _vod_play_cache
    owner, ident = probe["owner"], probe["ident"]
    try:
        for path, size, mtime in todo:
            if not await _vod_session_probe_head(owner, storage, ident, path, size, mtime):
                # no duration in the header: convert it (the job measures the segment and remembers it)
                outcome, payload = await _vod_play_obtain(
                    owner, storage, ident, path, size, mtime, "ts",
                    VOD_PLAY_RESERVE_WAIT + VOD_PLAY_PULL_TIMEOUT)
                if outcome == "unplayable":
                    cache.set_duration(owner, ident, path, size, mtime, 1.0, False,
                                       payload.get("reason") or "unsupported format", save=False)
                elif outcome != "file":
                    raise _VodPlayRemoteError(
                        503, "A chunk could not be measured yet; try again in a minute")
            probe["done"] += 1
        probe["state"] = "ready"
    except _VodPlayRemoteError as e:
        probe["state"], probe["error"], probe["status"] = "failed", e.message, e.status
    except asyncio.CancelledError:
        probe["state"], probe["error"] = "failed", "Measuring was cancelled"
        raise
    except Exception as e:
        logger.error(f"VOD session probe for user {owner} failed: {type(e).__name__}: {e}")
        probe["state"], probe["error"] = "failed", "The session could not be measured"
    finally:
        if cache is not None:
            cache.save_durations()
        probe["finished"] = monotonic()


def _vod_session_prune_probes() -> None:
    now = monotonic()
    for k, p in list(_vod_session_probes.items()):
        fin = p.get("finished")
        if fin is not None and now - fin > (VOD_SESSION_PROBE_FAILED_KEEP if p["state"] == "failed" else 5):
            _vod_session_probes.pop(k, None)


async def _vod_session_playlist(user_id: int, storage: dict, folder: str) -> web.Response:
    cache = _vod_play_cache
    ident = vod_play.storage_ident(storage)
    try:
        chunks = await _vod_session_listing(user_id, storage, folder)
    except _VodPlayRemoteError as e:
        return _vod_play_reply({"error": e.message}, e.status)
    live = _vod_session_is_live(storage, folder)
    if live and chunks:
        chunks = chunks[:-1]                          # the newest one is still being written
    if not chunks:
        if live:
            return _vod_play_reply({"error": "This session is being recorded and has no finished chunk yet",
                                    "state": "live"}, 409)
        return _vod_play_reply({"error": "VOD not found"}, 404)
    if len(chunks) > vod_play.MAX_SESSION_CHUNKS:
        return _vod_play_reply({"error": "This session has too many chunks for one timeline; play the chunks one by one"},
                               413)
    known = {}
    missing = []
    for number, name, size, mtime in chunks:
        path = f"{folder}/{name}"
        d = cache.get_duration(user_id, ident, path, size, mtime)
        if d:
            known[path] = d
        else:
            missing.append((path, size, mtime))
    for path, d in known.items():
        if not d["playable"]:
            return _vod_play_reply(
                {"error": vod_play.download_only_message(d.get("reason") or "unsupported format"),
                 "reason": d.get("reason"), "state": "unplayable"}, 415)
    if missing:
        _vod_session_prune_probes()
        probe = _vod_session_probes.get((user_id, folder))
        if probe is not None and probe["state"] == "failed":
            return _vod_play_reply({"error": probe.get("error") or "The session could not be measured",
                                    "state": "failed"}, probe.get("status") or 500)
        if probe is None or probe["state"] == "ready":
            if len([p for p in _vod_session_probes.values() if p["finished"] is None]) >= VOD_SESSION_PROBE_MAX:
                return _vod_play_reply({"error": "The server is busy measuring sessions; try again shortly"},
                                       503, retry_after=10)
            probe = {"owner": user_id, "folder": folder, "ident": ident, "state": "running", "total": len(missing),
                     "done": 0, "finished": None}
            _vod_session_probes[(user_id, folder)] = probe
            task = asyncio.create_task(_vod_session_probe_job(probe, storage, missing))
            probe["task"] = task
            _vod_play_tasks.add(task)
            task.add_done_callback(_vod_play_tasks.discard)
        return _vod_play_reply({"state": "preparing", "stage": "measuring", "done": probe["done"],
                                "total": probe["total"], "chunks": len(chunks)}, 202, retry_after=2)
    items = [(name[:-4] + ".ts", known[f"{folder}/{name}"]["duration"]) for _n, name, _s, _m in chunks]
    text = vod_play.playlist_text(items, finished=not live)
    return web.Response(text=text, headers={
        "Content-Type": "application/vnd.apple.mpegurl", "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff"})


def _vod_session_prefetch(user_id: int, storage: dict, ident: str, folder: str, stem: str) -> None:
    """After serving a segment: prepare the next chunk of the session, when its length is known and it fits
    in the cache without evicting anything (a failure is of no interest here)."""
    cache = _vod_play_cache
    number = int(stem.split("_")[1])
    later = [d for d in cache.session_durations(user_id, ident, folder)
             if d["playable"] and (vod_play.chunk_number(d["path"].rpartition("/")[2]) or -1) > number]
    if not later:
        return
    later.sort(key=lambda d: vod_play.chunk_number(d["path"].rpartition("/")[2]))
    nxt = later[0]
    if cache.get(vod_play.entry_key(user_id, ident, nxt["path"], nxt["rsize"], nxt["rmtime"], "ts")):
        return

    async def go():
        try:
            await _vod_play_obtain(user_id, storage, ident, nxt["path"], nxt["rsize"], nxt["rmtime"], "ts", 0,
                                   duration=nxt["duration"], prefetch=True)
        except Exception as e:                        # best effort
            logger.debug(f"VOD session prefetch: {type(e).__name__}: {e}")
    task = asyncio.create_task(go())
    _vod_play_tasks.add(task)
    task.add_done_callback(_vod_play_tasks.discard)


async def _vod_session_segment(user_id: int, storage: dict, folder: str, stem: str,
                               started: Optional[float] = None) -> web.Response:
    """*started* is when the request came in: the whole answer (stat, live check, waiting for the job)
    is held to VOD_SESSION_SEG_WAIT seconds, so a slow storage cannot push it past the proxy's limit."""
    cache = _vod_play_cache
    started = monotonic() if started is None else started
    ident = vod_play.storage_ident(storage)
    path = f"{folder}/{stem}.mkv"
    try:
        size, mtime = await _vod_play_remote_stat(user_id, storage, path, ident)
    except _VodPlayRemoteError as e:
        return _vod_play_reply({"error": e.message}, e.status)
    if _vod_session_is_live(storage, folder) and await _vod_play_is_live_newest(user_id, storage, path):
        # left out of the playlist, so left out here too, even when an earlier copy is cached
        return _vod_play_reply({"error": "This chunk is still being recorded", "state": "live"}, 409)
    d = cache.get_duration(user_id, ident, path, size, mtime)
    left = max(0.1, VOD_SESSION_SEG_WAIT - (monotonic() - started))
    outcome, payload = await _vod_play_obtain(user_id, storage, ident, path, size, mtime, "ts",
                                              left, duration=d["duration"] if d else None)
    if outcome == "file":
        _vod_session_prefetch(user_id, storage, ident, folder, stem)
        return _vod_play_ts_file(payload)
    if outcome == "live":
        return _vod_play_reply({"error": "This chunk is still being recorded", "state": "live"}, 409)
    if outcome == "limit":
        # 503, not 429: hls.js retries a 5xx segment but treats a 4xx as fatal
        return _vod_play_reply({"error": payload[1], "state": "busy"}, 503, retry_after=5)
    if outcome == "unplayable":
        return _vod_play_reply(
            {"error": vod_play.download_only_message(payload.get("reason") or "unsupported format"),
             "reason": payload.get("reason"), "state": "unplayable"}, 415)
    if outcome == "failed":
        return _vod_play_reply({"error": payload.get("error") or "The chunk could not be prepared", "state": "failed"},
                               payload.get("status") or 500, retry_after=5 if payload.get("status") in (503, 502) else None)
    # still being prepared after the wait: not 202 (a player would try to demux the body); 503 is retried
    return _vod_play_reply(dict(_vod_play_job_view(payload)), 503, retry_after=2)


async def http_play_session(request: web.Request) -> web.StreamResponse:
    """GET /api/vods/session/{folder}/index.m3u8 - the session's HLS playlist (200), or 202 while the
    chunk lengths are measured; GET /api/vods/session/{folder}/chunk_NNN.ts - one chunk as MPEG-TS.
    404 (not yours or not there), 409 (live), 413 (too many chunks), 415 (download only), 429, 502, 503."""
    started = monotonic()
    token, refusal = await _stream_user_auth(request)    # a stream key (live_) publishes only
    if refusal is not None:
        refusal.headers["Cache-Control"] = "private, no-store"
        return refusal
    token, storage, parsed, cap, refusal = await _vod_play_prelude(request, token, session=True)
    if refusal is not None:
        return refusal
    folder, kind, stem = parsed
    if kind == "playlist":
        return await _vod_session_playlist(token.user_id, storage, folder)
    return await _vod_session_segment(token.user_id, storage, folder, stem, started)


