async def http_sftp_vod_upload(request: web.Request) -> web.Response:
    """POST /api/sftp/vod/upload - Upload file to VOD storage."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    ssh_conn, sftp, err = await _get_vod_sftp(request, token)
    if err:
        return err
    try:
        reader = await request.multipart()
        target_path = "/"
        file_data = None
        file_name = None

        async for part in reader:
            if part.name == "path":
                target_path = (await part.text()).strip()
            elif part.name == "file":
                file_name = part.filename
                file_data, oversized = await read_multipart_part(part, Config.FILE_MANAGER_MAX_UPLOAD)
                if oversized:
                    return web.json_response(
                        {"error": f"File too large (max {Config.FILE_MANAGER_MAX_UPLOAD // (1024*1024)}MB)"}, status=400)

        if not file_data or not file_name:
            return web.json_response({"error": "No file provided"}, status=400)

        dest = target_path.rstrip("/") + "/" + file_name
        await sftp_browser.write_remote_file(sftp, dest, file_data)
        return web.json_response({"status": "success", "path": dest})
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)
    except Exception as e:
        logger.error(f"SFTP VOD upload error for user {token.user_id}: {e}")
        return web.json_response({"error": "SFTP operation failed"}, status=500)
    finally:
        ssh_conn.close()


