# Global service manager reference (initialized in PortalServer.start)
_service_manager: Optional[ServiceManager] = None


async def _can_control_service(token: TokenPayload, service_id: int, need: str = "control") -> bool:
    """True if the token is admin, or holds a service_grant covering `need`.

    `need` is 'control' (start/stop/restart) or 'logs' (logs + status)."""
    if token.has_scope("admin") or token.has_scope("*"):
        return True
    grant = await db.user_service_grant(token.user_id, service_id)
    return bool(grant and need in grant)


async def http_list_managed_services(request: web.Request) -> web.Response:
    """List all managed services (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    if not _service_manager:
        return web.json_response({"error": "Service manager not initialized"}, status=503)

    services = _service_manager.get_all_services()
    statuses = []
    for svc in services:
        enriched = await _service_manager.get_service_status(svc.id)
        status = enriched or svc.get_status()
        _attach_resource_usage(status)
        statuses.append(status)
    return web.json_response({"managed_services": statuses})


async def http_get_managed_service_types(request: web.Request) -> web.Response:
    """Get available managed service types."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    types = get_available_service_types()
    return web.json_response({
        "types": {
            name: {
                "name": info.name,
                "display_name": info.display_name,
                "description": info.description,
                "version": info.version,
                "icon": info.icon,
                "default_port": info.default_port,
                "config_schema": info.config_schema
            }
            for name, info in types.items()
        }
    })


async def http_create_managed_service(request: web.Request) -> web.Response:
    """Create a new managed service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)

    if not _service_manager:
        return web.json_response({"error": "Service manager not initialized"}, status=503)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    name = data.get("name")
    service_type = data.get("type")

    if not name or not service_type:
        return web.json_response({"error": "name and type required"}, status=400)

    # Check service type exists
    if service_type not in get_available_service_types():
        return web.json_response({
            "error": f"Unknown service type: {service_type}",
            "available_types": list(get_available_service_types().keys())
        }, status=400)

    if not re.match(r"^[a-z0-9][a-z0-9-]{0,63}$", str(name)):
        return web.json_response(
            {"error": "name must be lowercase letters, numbers and hyphens"},
            status=400,
        )

    config = data.get("config") or {}
    handler_class = get_service_class(service_type)

    # Validate the config against the handler's own rules before we create
    # a database row for it.
    try:
        probe = handler_class({"id": 0, "name": name, "config": config})
        ok, verr = probe.validate_config(config)
    except Exception:
        ok, verr = True, ""
    if not ok:
        return web.json_response({"error": verr}, status=400)

    # For a systemd-wrapped service, refuse up front if the unit isn't
    # installed on this host — a much clearer error than a failed start later.
    if hasattr(handler_class, "unit_exists"):
        unit = str(config.get("unit", "")).strip()
        if not await handler_class.unit_exists(unit):
            return web.json_response({
                "error": f"No systemd unit '{unit}.service' found on this host — "
                         "install it first, then add it here."
            }, status=400)

    try:
        service = await _service_manager.create_service(
            name=name,
            service_type=service_type,
            display_name=data.get("display_name"),
            description=data.get("description"),
            config=config,
            port=data.get("port"),
            enabled=data.get("enabled", False)
        )

        if not service:
            return web.json_response({"error": "Failed to create service"}, status=500)

        logger.info(f"Managed service '{name}' created by user {token.user_id}")
        return web.json_response({
            "service": service.get_status(),
            "message": "Service created successfully"
        }, status=201)

    except Exception as e:
        logger.error(f"Error creating managed service: {e}")
        return web.json_response({"error": safe_error_message(e)}, status=500)


async def http_get_managed_service(request: web.Request) -> web.Response:
    """Get a managed service by ID (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

