async def http_add_service_grant(request: web.Request) -> web.Response:
    """Grant one or more users control/logs on a managed service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)
    sid = request.match_info.get("id", "")
    if not sid.isdigit():
        return web.json_response({"error": "Invalid service ID"}, status=400)
    sid = int(sid)
    service = await db.get_service_by_id(sid)
    if not service:
        return web.json_response({"error": "Service not found"}, status=404)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)

    try:
        duration = grant_expiry.duration_from_body(data)
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)

    actions = [a for a in (data.get("actions") or ["control"]) if a in ("control", "logs", "files")] or ["control"]
    usernames = data.get("usernames") or ([data["username"]] if data.get("username") else [])
    added, skipped = [], []
    for name in usernames[:50]:
        u = await db.get_user_by_username(str(name).strip())
        if not u:
            skipped.append(name)
            continue
        if await db.add_service_grant(sid, u["id"], actions, token.user_id, duration):
            added.append(u["username"])
        else:
            skipped.append(name)
    if added:
        actor = await db.get_user_by_id(token.user_id)
        await audit_log(
            "service.grant", token.user_id, (actor or {}).get("username", "unknown"),
            target_id=sid, target_type="service", target_name=service.get("name"),
            details={"grantees": added, "actions": actions, "duration": duration or "unchanged"},
        )
    return web.json_response({"added": added, "skipped": skipped,
                              "grants": await db.list_service_grants(sid)})


async def http_remove_service_grant(request: web.Request) -> web.Response:
    """Revoke a user's grant on a managed service (admin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not token.has_scope("admin") and not token.has_scope("*"):
        return forbidden_response(request)
    sid = request.match_info.get("id", "")
    grantee = request.match_info.get("grantee", "")
    if not sid.isdigit() or not grantee.isdigit():
        return web.json_response({"error": "Invalid parameters"}, status=400)
    ok = await db.remove_service_grant(int(sid), int(grantee))
    if ok:
        await close_grant_dependents("svc", int(sid), int(grantee))
        actor = await db.get_user_by_id(token.user_id)
        await audit_log(
            "service.ungrant", token.user_id, (actor or {}).get("username", "unknown"),
            target_id=int(sid), target_type="service",
            details={"grantee_id": int(grantee)},
        )
    return web.json_response({"success": ok, "grants": await db.list_service_grants(int(sid))})


# =============================================================================
# Game Servers (SteamCMD) — see gameservers.py
# =============================================================================

def _is_admin(token: TokenPayload) -> bool:
    return token.has_scope("admin") or token.has_scope("*")


async def _gs_access(token: TokenPayload, gs: dict, need: str) -> bool:
    """admin, or a service_grant on this game server's backing service.

    `need`: 'control' (start/stop/restart/update), 'logs', or 'files'."""
    if _is_admin(token):
        return True
    sid = gs.get("service_id")
    if not sid:
        return False
    grant = await db.user_service_grant(token.user_id, sid)
    return bool(grant and need in grant)


async def _gs_or_404(request):
    gid = request.match_info.get("id", "")
    if not gid.isdigit():
        return None, web.json_response({"error": "Invalid ID"}, status=400)
    gs = await db.game_server_get(int(gid))
    if not gs:
        return None, web.json_response({"error": "Game server not found"}, status=404)
    return gs, None


async def http_game_catalog_list(request: web.Request) -> web.Response:
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    return web.json_response({"games": await db.game_catalog_list()})


async def http_game_catalog_add(request: web.Request) -> web.Response:
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not _is_admin(token):
        return forbidden_response(request)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    key = str(data.get("key", "")).strip().lower()
    if not re.match(r"^[a-z0-9][a-z0-9-]{1,31}$", key):
        return web.json_response({"error": "key must be lowercase letters/digits/hyphens"}, status=400)
    for f in ("name", "steam_app_id", "start_cmd"):
        if not data.get(f):
            return web.json_response({"error": f"{f} is required"}, status=400)
    try:
        data["key"] = key
        data["runtime"] = gameservers.normalize_runtime(data.get("runtime"))
        await db.game_catalog_upsert(data, builtin=False)
    except Exception as e:
        return web.json_response({"error": safe_error_message(e)}, status=400)
    return web.json_response({"games": await db.game_catalog_list()})


async def http_game_catalog_delete(request: web.Request) -> web.Response:
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not _is_admin(token):
        return forbidden_response(request)
    ok = await db.game_catalog_delete(request.match_info.get("key", ""))
    return web.json_response({"success": ok, "games": await db.game_catalog_list()})


async def http_game_servers_list(request: web.Request) -> web.Response:
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    servers = await db.game_server_list()
    if not _is_admin(token):
        granted = set((await db.get_user_granted_service_ids(token.user_id)).keys())
        servers = [s for s in servers if s.get("service_id") in granted]
    # enrich with live service status
    for s in servers:
        s["config_paths"] = _json_or(s.get("config_paths"), [])
        if s.get("service_id") and _service_manager:
            st = await _service_manager.get_service_status(s["service_id"])
            if st:
                s["status"] = st.get("status")
                s["health_status"] = st.get("health_status")
                s["pid"] = st.get("pid")
                _attach_resource_usage(s)
    return web.json_response({"game_servers": servers})


def _json_or(raw, default):
    try:
        return json.loads(raw) if raw else default
    except (json.JSONDecodeError, TypeError):
        return default


async def http_game_server_get(request: web.Request) -> web.Response:
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    gs, err = await _gs_or_404(request)
    if err:
        return err
    if not await _gs_access(token, gs, "logs"):
        return forbidden_response(request)
    gs["config_paths"] = _json_or(gs.get("config_paths"), [])
    return web.json_response({"game_server": gs})


async def http_list_storage_roots(request: web.Request) -> web.Response:
    """GET /api/game-storage-roots - List registered game-data storage roots."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not _is_admin(token):
        return forbidden_response(request)

    roots = await db.game_storage_root_list()
    servers = await db.game_server_list()
    out = []
    for r in roots:
        entry = dict(r)
        try:
            usage = shutil.disk_usage(r["path"])
            entry["disk"] = {"total": usage.total, "used": usage.used, "free": usage.free}
        except OSError as e:
            entry["disk"] = None
            entry["disk_error"] = str(e)
        install_dir_root = r["path"] + os.sep
        entry["server_count"] = sum(
            1 for gs in servers
            if os.path.realpath(gs.get("install_dir") or "").startswith(install_dir_root)
        )
        out.append(entry)
    return web.json_response({"storage_roots": out})


async def http_add_storage_root(request: web.Request) -> web.Response:
    """POST /api/game-storage-roots - Register a new game-data storage root."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not _is_admin(token):
        return forbidden_response(request)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    try:
        row = await gameservers.add_storage_root(
            db, path=data.get("path", ""), label=data.get("label"),
            create_if_missing=bool(data.get("create_if_missing", False)),
        )
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)
    except Exception as e:
        logger.exception("add storage root failed")
        return web.json_response({"error": safe_error_message(e)}, status=500)
    actor = await db.get_user_by_id(token.user_id)
    await audit_log("gameserver.storage_root_add", token.user_id,
                    (actor or {}).get("username", "unknown"), target_name=row["path"])
    return web.json_response({"storage_root": row}, status=201)


