async def http_login_page(request: web.Request) -> web.Response:
    """Serve login page."""
    # If already authenticated, redirect to dashboard
    token = await authenticate_request(request)
    if token:
        raise web.HTTPFound("/dashboard")

    html = load_static_file("login.html")
    # Inject search engine verification meta tags if configured
    verification_tags = []
    if Config.GOOGLE_SITE_VERIFICATION:
        verification_tags.append(f'<meta name="google-site-verification" content="{_html.escape(Config.GOOGLE_SITE_VERIFICATION)}">')
    if Config.BING_SITE_VERIFICATION:
        verification_tags.append(f'<meta name="msvalidate.01" content="{_html.escape(Config.BING_SITE_VERIFICATION)}">')
    if Config.YANDEX_SITE_VERIFICATION:
        verification_tags.append(f'<meta name="yandex-verification" content="{_html.escape(Config.YANDEX_SITE_VERIFICATION)}">')
    html = html.replace(
        "<!-- SEARCH_ENGINE_VERIFICATION -->",
        "\n    ".join(verification_tags) if verification_tags else ""
    )

    # Inject dynamic hostname for canonical URLs and OG tags
    hostname = Config.HOSTNAME or "localhost"
    html = html.replace("{{HOSTNAME}}", _html.escape(hostname))

    return web.Response(text=html, content_type="text/html")


async def http_login_submit(request: web.Request) -> web.Response:
    """Handle login form submission with optional 2FA support."""
    client_ip = get_client_ip(request)

    if not check_rate_limit(client_ip):
        return web.json_response({"error": "Rate limit exceeded"}, status=429)

    # Handle both form data and JSON
    content_type = request.content_type
    if "application/json" in content_type:
        try:
            data = await request.json()
        except json.JSONDecodeError:
            return web.json_response({"error": "Invalid JSON"}, status=400)
    else:
        data = await request.post()

    username = data.get("username")
    password = data.get("password")
    totp_code = data.get("totp_code")  # Optional 2FA code
    remember_me = data.get("remember", False)

    if not username or not password:
        if "application/json" in content_type:
            return web.json_response({"error": "Username and password required"}, status=400)
        return web.Response(
            status=401,
            text=load_static_file("login.html"),
            content_type="text/html"
        )

    user, fail_reason = await authenticate_user_reason(username, password)
    if not user:
        logger.warning(f"Failed web login for {_tried_label(username, fail_reason)} from {client_ip}")
        security_event_nowait("login_failed", request=request, ip=client_ip,
                              username=_tried_name(username, fail_reason),
                              result=fail_reason, details={"via": "web"})
        await _count_login_failure(client_ip, await _failure_user_id(username, fail_reason))
        if "application/json" in content_type:
            return web.json_response({"error": "Invalid credentials"}, status=401)
        return web.Response(
            status=401,
            text=load_static_file("login.html"),
            content_type="text/html"
        )

    # Check if 2FA is enabled for this user
    if user.get("totp_enabled"):
        if not totp_code or (isinstance(totp_code, str) and not totp_code.strip()):
            # 2FA required but not provided - request it
            logger.info(f"2FA required for user '{username}' from {client_ip}")
            security_event_nowait("2fa_required", request=request, ip=client_ip, user=user,
                                  details={"via": "web"})
            return web.json_response({
                "status": "2fa_required",
                "message": "Two-factor authentication required"
            }, status=200)

        # Verify TOTP or backup code (shared wrong-code throttle)
        result, retry_after = await verify_second_factor(user, totp_code, client_ip, request=request)
        if result == "throttled":
            return web.json_response(
                {"error": "Too many incorrect codes. Try again later."},
                status=429,
                headers={"Retry-After": str(retry_after)}
            )
        if result == "invalid":
            logger.warning(f"Failed 2FA for user '{username}' from {client_ip}")
            return web.json_response({"error": "Invalid 2FA code"}, status=401)
        if result == "backup":
            logger.info(f"Backup code used for user '{username}' from {client_ip}")
        else:
            logger.info(f"2FA verified for user '{username}' from {client_ip}")

    # Session duration: 30 days if "remember me", otherwise 24 hours
    REMEMBER_ME_SECONDS = 30 * 24 * 3600  # 30 days
    session_max_age = REMEMBER_ME_SECONDS if remember_me else Config.SESSION_COOKIE_MAX_AGE
    session_hours = session_max_age // 3600

    # Create session token
    scopes = ["*"] if user["is_admin"] else ["services:read", "access:*"]
    jwt_token, session_token_id = await create_access_token(
        user_id=user["id"],
        scopes=scopes,
        name="web_session",
        expires_in_hours=session_hours,
        ip=client_ip,
        user_agent=request.headers.get("User-Agent")
    )

    logger.info(f"Web login for user '{username}' from {client_ip} (remember={bool(remember_me)})")
    await _note_login_success(user, client_ip)
    await security_event("login_success", request=request, ip=client_ip, user=user,
                         details={"via": "web", "remember": bool(remember_me),
                                  "token_id": session_token_id[:8]})

    # For JSON requests, return token directly
    if "application/json" in content_type:
        response = web.json_response({
            "status": "logged_in",
            "user_id": user["id"],
            "username": user["username"]
        })
    else:
        # For form submissions, redirect to dashboard
        response = web.HTTPFound("/dashboard")

    response.set_cookie(
        Config.SESSION_COOKIE_NAME,
        jwt_token,
        max_age=session_max_age,
        path="/",
        secure=Config.SESSION_COOKIE_SECURE,
        httponly=Config.SESSION_COOKIE_HTTPONLY,
        samesite=Config.SESSION_COOKIE_SAMESITE,
    )

    if "application/json" not in content_type:
        raise response

    return response


async def http_logout(request: web.Request) -> web.Response:
    """Handle logout. GET (a link) answers with a redirect to the login page. POST {endpoint}
    (the push script) also removes the push device of this browser, found by its endpoint (in
    the body, never in the URL), then answers 200; a device of an earlier session of the same
    member is removed too, which revoking this session's token alone would miss."""
    post = request.method == "POST"
    endpoint = None
    if post:
        try:
            data = await request.json()
            endpoint = data.get("endpoint") if isinstance(data, dict) else None
        except (json.JSONDecodeError, UnicodeDecodeError, ValueError):
            endpoint = None
        if not isinstance(endpoint, str) or not endpoint or len(endpoint) > webpush.MAX_ENDPOINT_LEN:
            endpoint = None
    # Try to revoke the session token before clearing cookie
    cookie = request.cookies.get(Config.SESSION_COOKIE_NAME)
    if cookie:
        try:
            token = await authenticate_request(request)
            if token:
                # Revoke first: a subscribe still in flight is then refused by the database
                # (its write is conditional on a live session), and the device of this session
                # goes with the revoke; the endpoint of an earlier session's device is removed after.
                await db.revoke_token(token.token_id)
                if endpoint:
                    await db.delete_push_subscription(token.user_id, endpoint=endpoint)
                # The chat sockets opened with this session and its voice call
                # end with it (code 4001); the user's other sessions stay.
                await close_user_websockets(token.user_id, only_token_id=token.token_id)
                await security_event("logout", request=request, user_id=token.user_id,
                                     username=await _username_of(token.user_id),
                                     details={"token_id": token.token_id[:8]})
        except Exception:
            pass  # Best effort - still clear cookie

    if post:
        response = web.json_response({"success": True})
        response.del_cookie(Config.SESSION_COOKIE_NAME)
        return response
    response = web.HTTPFound("/login")
    response.del_cookie(Config.SESSION_COOKIE_NAME)
    raise response


