async def http_browser_page(request: web.Request) -> web.Response:
    """Serve embedded browser page for HTTP proxy connections."""
    token = await authenticate_request(request)
    if not token:
        raise web.HTTPFound("/login")

    conn_id = request.query.get("connection", "")
    if not conn_id:
        return web.Response(status=400, text="Missing connection parameter")

    connection = await db.get_accessible_connection(conn_id, token.user_id)
    if not connection:
        return web.Response(status=404, text="Connection not found")

    conn_type = connection.get("type", "custom")
    type_info = CONNECTION_TYPES.get(conn_type, {"plugin": "tcp_tunnel"})
    if type_info.get("plugin") != "http_proxy":
        return web.Response(status=400, text="Not an HTTP proxy connection")

    # Build target display URL for the address bar
    host = connection.get("host", "")
    config = connection.get("config", {})
    if isinstance(config, str):
        try:
            config = json.loads(config) if config else {}
        except json.JSONDecodeError:
            config = {}

    default_port = type_info.get("default_port", 80)
    port = connection.get("port") or config.get("port") or default_port
    https_types = {"https", "portainer", "truenas", "pfsense", "nextcloud", "cockpit"}
    scheme = "https" if (conn_type in https_types or port == 443) else "http"
    default_scheme_port = 443 if scheme == "https" else 80
    if int(port) == default_scheme_port:
        target_display = f"{scheme}://{host}"
    else:
        target_display = f"{scheme}://{host}:{port}"

    proxy_path = f"/proxy/{conn_id}"

    browser_mode = config.get("browser_mode", False)

    # Home / new-tab page. An explicit config["home_url"] wins; otherwise the
    # default "Web Browser" connection uses the portal's own private search
    # (SearXNG at /search/, same origin) as its home page when that managed
    # service is enabled, falling back to its configured target (DuckDuckGo)
    # when SearXNG is off. Only same-origin absolute portal paths are allowed.
    home_url = ""
    cfg_home = config.get("home_url") if isinstance(config, dict) else None
    if isinstance(cfg_home, str) and cfg_home.startswith("/") and not cfg_home.startswith("//"):
        home_url = cfg_home
    elif (conn_type in ("http", "https", "http_proxy")
          and connection.get("name") == "Web Browser"
          and host in ("duckduckgo.com", "portal.dddvm.xyz")):
        sx_available, _ = await _searxng_status()
        if sx_available:
            home_url = "/search/"

    html = load_static_file("browser.html")
    html = html.replace("{{CONNECTION_ID}}", conn_id)
    html = html.replace("{{SERVICE_NAME}}", _html.escape(connection.get("name", "Browser")))
    html = html.replace("{{PROXY_PATH}}", proxy_path)
    html = html.replace("{{TARGET_DISPLAY}}", _html.escape(target_display))
    html = html.replace("{{BROWSER_MODE}}", "true" if browser_mode else "false")
    html = html.replace("{{HOME_URL}}", _html.escape(home_url))

    return web.Response(text=html, content_type="text/html")


_PROXY_MAX_RESPONSE_SIZE = 50 * 1024 * 1024   # 50 MB for text content needing URL rewriting
_PROXY_MAX_REQUEST_SIZE = 10 * 1024 * 1024     # 10 MB
_PROXY_MAX_REDIRECTS = 5                       # hops the portal follows for a non-browser connection


_PROXY_TIMEOUT_DEFAULT = 60
_PROXY_TIMEOUT_MIN = 5
_PROXY_TIMEOUT_MAX = 300
_PROXY_CONNECT_TIMEOUT = 10


def _proxy_timeout_seconds(value) -> int:
    """The per-connection `timeout` setting, forced into 5-300 seconds.

    Anything that is not a number (missing, text, a boolean) gives the default.
    """
    if isinstance(value, bool):
        return _PROXY_TIMEOUT_DEFAULT
    try:
        seconds = int(float(value))
    except (TypeError, ValueError, OverflowError):
        return _PROXY_TIMEOUT_DEFAULT
    return max(_PROXY_TIMEOUT_MIN, min(_PROXY_TIMEOUT_MAX, seconds))


def _proxy_client_timeout(config: dict) -> aiohttp.ClientTimeout:
    """Connecting is bounded by a fixed 10 s; after that the response may take
    as long as it likes as long as bytes keep arriving (`timeout` is the longest
    silence). There is deliberately no total limit: a large download or a
    stream must not be cut off at a wall-clock time."""
    return aiohttp.ClientTimeout(
        total=None,
        connect=_PROXY_CONNECT_TIMEOUT,
        sock_read=_proxy_timeout_seconds(config.get("timeout")),
    )


# Never copied from the client. Every X-Forwarded-* header (not only the ones
# set below) is dropped as well, so a forward_headers pattern such as "x-*"
# cannot pass a client-supplied copy.
_PROXY_BLOCKED_HEADERS = frozenset({
    "host", "content-length", "transfer-encoding", "authorization",
    "accept-encoding", "x-real-ip", "forwarded",
    # Client address headers a CDN or another proxy put there: the portal sets
    # its own from the real peer, and in browser mode no site is told the member's address.
    "cf-connecting-ip", "true-client-ip", "x-client-ip",
    # Portal credentials (authenticate_request accepts both): never passed on.
    "x-api-key", "x-stream-key",
})
_PROXY_HOST_RE = re.compile(r"^[A-Za-z0-9._:\[\]-]{1,255}$")


_PROXY_HTML_CSP = (
    "default-src * 'unsafe-inline' 'unsafe-eval' data: blob:; "
    "worker-src 'none'; "
    "frame-ancestors 'self';"
)
# An SVG shown as a document: no script runs (sandbox without allow-scripts), nothing is fetched except
# styles, images and fonts. An SVG used as an image by a page is unaffected (a CSP on an image is not applied).
_PROXY_SVG_CSP = (
    "sandbox; default-src 'none'; style-src * 'unsafe-inline'; img-src * data:; font-src * data:; "
    "frame-ancestors 'self'"
)


def _proxy_document_csp(content_type: str):
    """The Content-Security-Policy a proxied response gets, by its type: the permissive HTML one
    (upstream pages need their own scripts, but no worker) for HTML, XHTML and XML documents, a
    scriptless sandbox for SVG, none for anything else."""
    ct = (content_type or "").split(";", 1)[0].strip().lower()
    if ct == "image/svg+xml":
        return _PROXY_SVG_CSP
    if ct in ("text/html", "application/xhtml+xml", "text/xml", "application/xml") or ct.endswith("+xml"):
        return _PROXY_HTML_CSP
    return None


def _proxy_header_blocked(lower_name: str) -> bool:
    return lower_name in _PROXY_BLOCKED_HEADERS or lower_name.startswith("x-forwarded-")


def _proxy_forwarded_scheme(request: web.Request) -> str:
    """Scheme the client used to reach the portal ("http" or "https").

    Cloudflare's CF-Visitor and X-Forwarded-Proto are believed only from a
    trusted proxy (the same rule as get_client_ip); otherwise it is the scheme
    of this connection itself.
    """
    peername = request.transport.get_extra_info("peername") if request.transport else None
    if peername and _is_trusted_proxy(peername[0]):
        visitor = request.headers.get("CF-Visitor")
        if visitor:
            try:
                scheme = str(json.loads(visitor).get("scheme", "")).lower()
            except (ValueError, AttributeError):
                scheme = ""
            if scheme in ("http", "https"):
                return scheme
        xfp = request.headers.get("X-Forwarded-Proto", "")
        scheme = xfp.split(",")[-1].strip().lower()
        if scheme in ("http", "https"):
            return scheme
    return "https" if request.secure else "http"


def _host_without_port(host: str) -> str:
    """Lower-cased host name of a Host header value (port and IPv6 brackets removed)."""
    host = (host or "").strip().lower()
    if host.startswith("["):
        return host[1:].split("]", 1)[0]
    return host.rsplit(":", 1)[0] if host.count(":") == 1 else host


def _proxy_forwarded_host(request: web.Request) -> str:
    """Host name for X-Forwarded-Host: always the portal's configured one.

    The client's own Host header is used only when it names the configured
    host (so its port is kept); a client cannot choose a different name, since
    an upstream that builds redirect URLs from it would send the portal to
    that name. Empty when nothing usable is configured.
    """
    configured = (Config.HOSTNAME or "").strip()
    host = request.host or ""
    if (configured and _PROXY_HOST_RE.match(host)
            and _host_without_port(host) == _host_without_port(configured)):
        return host
    return configured if _PROXY_HOST_RE.match(configured) else ""


def _proxy_query_string(request: web.Request) -> str:
    """Query string forwarded to the upstream.

    When the request was authenticated by a ?token= parameter, that parameter is
    the member's portal session and is removed (every occurrence of it); the
    other parameters are passed on exactly as sent.
    """
    if not request.get(_AUTH_VIA_QUERY_TOKEN):
        return request.query_string
    from urllib.parse import unquote_plus
    kept = [part for part in request.rel_url.raw_query_string.split("&")
            if part and unquote_plus(part.split("=", 1)[0]) != "token"]
    return "&".join(kept)


def _proxy_request_headers(request: web.Request, config: dict, upstream_host: str,
                           proxy_prefix: str, browser_mode: bool) -> CIMultiDict:
    """Headers sent to the upstream for one proxied request.

    Only headers matching the connection's forward_headers list are copied.
    The portal's session cookie and Authorization are never copied, and the
    forwarding headers always come from the portal, never from the client.
    X-Forwarded-Host and X-Forwarded-Prefix are sent only when the connection
    has forwarded_host on. Browser mode (any site on the internet) is told
    nothing about the member or the portal beyond the scheme.
    """
    import fnmatch as _fnmatch

    forward_patterns = [p.lower() for p in (config.get("forward_headers") or [])
                        if isinstance(p, str)][:20]
    out = CIMultiDict()
    cookies: list[str] = []
    for key, value in request.headers.items():
        k = key.lower()
        if _proxy_header_blocked(k):
            continue
        if k == "cookie":
            # Drop the portal session cookie; keep the rest.
            cookies += [c.strip() for c in value.split(";")
                        if c.strip() and not c.strip().startswith(Config.SESSION_COOKIE_NAME + "=")]
            continue
        # (non-whitelisted headers are dropped, the proxy default)
        if forward_patterns and any(_fnmatch.fnmatch(k, p) for p in forward_patterns):
            out.add(key, value)
    if cookies:
        out["Cookie"] = "; ".join(cookies)

    out["Host"] = upstream_host
    out["X-Forwarded-Proto"] = _proxy_forwarded_scheme(request)
    if not browser_mode:
        client_ip = get_client_ip(request)
        out["X-Forwarded-For"] = client_ip
        out["X-Real-IP"] = client_ip
        # Off by default: an app that honours X-Forwarded-Host without the prefix
        # writes links outside the proxy path.
        if config.get("forwarded_host") is True:
            host = _proxy_forwarded_host(request)
            if host:
                out["X-Forwarded-Host"] = host
            out["X-Forwarded-Prefix"] = proxy_prefix

    if config.get("auth_header"):
        out["Authorization"] = config["auth_header"]
    extra = config.get("extra_headers")
    if isinstance(extra, dict):
        for k, v in extra.items():
            out[k] = v
    return out


def _origin_parts(url: str):
    """(scheme, host, port) of an absolute http(s) URL, scheme and host
    lower-cased and the default port filled in; None when it cannot be parsed."""
    from urllib.parse import urlsplit
    try:
        parsed = urlsplit(url)
        scheme = parsed.scheme.lower()
        host = (parsed.hostname or "").lower()
        port = parsed.port or {"http": 80, "https": 443}.get(scheme)
    except ValueError:
        return None
    if scheme not in ("http", "https") or not host:
        return None
    return scheme, host, port


def _proxy_rewrite_location(loc: str, proxy_prefix: str, target_origin: str) -> str:
    """A Location header that reaches the client from a single-site connection.

    Redirects are followed by the portal itself, so this only sees what is
    left: a 201 with a Location, a 300, a 3xx the client has to handle. Such a
    Location has to land on /proxy/<id>/... A value already under the proxy
    path (an app that honours X-Forwarded-Prefix) is left alone, and an
    absolute URL on the portal's own host (an app that honours
    X-Forwarded-Host) is reduced to its path and treated the same way.
    Relative values need no change. Scheme and host are compared without
    regard to case. An absolute URL on the target's own host with a different
    scheme or port is another service: it is returned unchanged, never mapped
    back onto the target (that would be a redirect loop).
    """
    from urllib.parse import urlsplit

    def under_prefix(path: str) -> bool:
        return path == proxy_prefix or path.startswith((proxy_prefix + "/", proxy_prefix + "?"))

    target = _origin_parts(target_origin)
    # The origin must end where the Location says so: another port on the
    # same host, or a longer host name, is not the upstream's own origin.
    n = len(target_origin)
    if (loc[:n].lower() == target_origin.lower()
            and loc[n:n + 1] in ("", "/", "?", "#")):
        return proxy_prefix + loc[n:]
    if loc.startswith("//") and target:
        loc = target[0] + ":" + loc
    if loc.startswith("/"):
        return loc if under_prefix(loc) else proxy_prefix + loc
    if loc[:8].lower().startswith(("http://", "https://")):
        loc_origin = _origin_parts(loc)
        if loc_origin is None:
            return loc
        parsed = urlsplit(loc)
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        portal_host = _host_without_port(Config.HOSTNAME or "")
        if portal_host and loc_origin[1] == portal_host and under_prefix(path):
            return path
        if target and (loc_origin[0] != target[0] or loc_origin[2] != target[2]) and (
                loc_origin[1] == target[1] or loc_origin[1] != portal_host):
            # Another scheme or port: not the target, so never mapped onto it.
            return loc
        return proxy_prefix + path
    return loc


_PROXY_REDIRECT_STATUSES = (301, 302, 303, 307, 308)


class _ProxyTooManyRedirects(aiohttp.ClientError):
    """An upstream sent more than _PROXY_MAX_REDIRECTS redirects in a row."""


def _proxy_redirect_url(loc: str, current_url: str, proxy_prefix: str, target_origin: str):
    """Absolute URL the portal requests next for a redirect Location, or None
    when the Location cannot be used.

    The upstream is sent X-Forwarded-Host and X-Forwarded-Prefix, so an app
    that honours them answers with a Location on the portal's own host or
    under /proxy/<id>. Those name the portal, not a service to dial: they are
    mapped back onto the upstream (the prefix is removed), never requested as
    they stand. Anything else (another host, or the upstream's own host on
    another scheme or port, as in an http to https upgrade) is requested as
    given, through the outbound host policy.
    """
    from urllib.parse import urljoin

    try:
        absolute = urljoin(current_url, loc.strip())
        split = urlsplit(absolute)
    except ValueError:
        return None
    origin = _origin_parts(absolute)
    if origin is None:
        return None
    target = _origin_parts(target_origin)
    portal_host = _host_without_port(Config.HOSTNAME or "")
    on_target = origin == target
    on_portal = bool(target and portal_host and origin[1] == portal_host and origin[1] != target[1])
    if not (on_target or on_portal):
        return urlunsplit((split.scheme, split.netloc, split.path or "/", split.query, ""))
    path = split.path or "/"
    if path == proxy_prefix or path.startswith(proxy_prefix + "/"):
        path = path[len(proxy_prefix):] or "/"
    return urlunsplit((urlsplit(target_origin).scheme, urlsplit(target_origin).netloc, path, split.query, ""))


def _proxy_browser_location(loc: str, proxy_base: str, target_origin: str) -> str:
    """A Location from a site in general-browsing mode, kept inside the proxy.

    A protocol-relative value (//host/path) names another host and takes the
    current site's scheme; a root-relative value is put under the site's own
    path; an absolute URL (the scheme in any letter case) is wrapped as
    /proxy/<id>/<url>, with the scheme lower-cased so the handler recognises
    it, so the browser never leaves the proxy and no site sees the member's
    address.
    """
    if loc.startswith("//"):
        return f"{proxy_base}/{target_origin.split(':', 1)[0].lower()}:{loc}"
    if loc.startswith("/"):
        return f"{proxy_base}/{target_origin}{loc}"
    if loc[:8].lower().startswith(("http://", "https://")):
        scheme, rest = loc.split(":", 1)
        return f"{proxy_base}/{scheme.lower()}:{rest}"
    return loc


@asynccontextmanager
async def _proxy_open_upstream(session, method, url, headers, body, *, follow,
                               proxy_prefix, target_origin, own_headers, call=None):
    """The upstream response, after the redirects the portal follows itself.

    With follow=False the first response is returned as it is. Otherwise 301,
    302, 303, 307 and 308 are followed by hand (at most _PROXY_MAX_REDIRECTS
    hops, each one dialled through the session's policy connector). A Location
    that names the portal's own host or the proxy path is mapped back onto the
    upstream first (_proxy_redirect_url). A hop to another origin gets neither
    cookies, credentials nor the portal's forwarded host and prefix:
    `own_headers` are the configured header names (auth_header, extra_headers)
    that belong to the upstream alone. Once `call` (the registered request) is
    aborted by a revocation no further hop is made: the redirect response is
    returned as it is and the caller ends the request.
    """
    first_origin = _origin_parts(url)
    first_headers = headers
    resp = None
    hops = 0
    try:
        while True:
            resp = await session.request(method=method, url=url, headers=headers,
                                         data=body, allow_redirects=False)
            loc = resp.headers.get("Location")
            if not follow or resp.status not in _PROXY_REDIRECT_STATUSES or not loc:
                break
            nxt = _proxy_redirect_url(loc, url, proxy_prefix, target_origin)
            if nxt is None:
                break
            if call is not None and call.aborted:
                break
            if hops >= _PROXY_MAX_REDIRECTS:
                raise _ProxyTooManyRedirects(f"more than {_PROXY_MAX_REDIRECTS} redirects")
            hops += 1
            status = resp.status
            resp.release()
            resp = None
            # Like a browser: 303, and 301/302 after a POST, become a GET
            # without the body; 307 and 308 repeat the request as it was.
            if (status == 303 and method != "HEAD") or (status in (301, 302) and method == "POST"):
                method, body = "GET", None
            url = nxt
            nxt_split = urlsplit(url)
            if _origin_parts(url) == first_origin:
                headers = CIMultiDict(first_headers)
            else:
                headers = CIMultiDict(
                    (k, v) for k, v in first_headers.items()
                    if k.lower() not in ("cookie", "authorization", "x-forwarded-host", "x-forwarded-prefix",
                                         "x-forwarded-for", "x-real-ip")
                    and k.lower() not in own_headers)
            headers["Host"] = nxt_split.netloc
            if body is None:
                for k in ("Content-Type", "Content-Length", "Transfer-Encoding"):
                    headers.popall(k, None)
        yield resp
    finally:
        if resp is not None:
            resp.release()


def _rewrite_set_cookie(value: str, cookie_prefix: str) -> Optional[str]:
    """One upstream Set-Cookie value, made storable under the proxy path.

    Every Path is put under `cookie_prefix` (a missing one becomes the prefix
    root, so a cookie cannot leak to another connection's proxy path), and
    every Domain is dropped (it names the upstream host, which the browser
    would reject on the portal's origin). Only attributes after the first
    name=value pair are touched. Returns None for a cookie that must not be
    passed on: one named like the portal's own session cookie.
    """
    parts = value.split(";")
    if parts[0].split("=", 1)[0].strip() == Config.SESSION_COOKIE_NAME:
        return None
    path = ""
    kept = [parts[0].strip()]
    for attr in parts[1:]:
        attr = attr.strip()
        if not attr:
            continue
        name, _, val = attr.partition("=")
        lname = name.strip().lower()
        if lname == "domain":
            continue
        if lname == "path":
            val = val.strip()
            path = val if val.startswith("/") else ""
            continue
        kept.append(attr)
    if path == cookie_prefix or path.startswith(cookie_prefix + "/"):
        new_path = path          # an app that honours X-Forwarded-Prefix
    else:
        new_path = cookie_prefix + (path or "/")
    kept.append(f"Path={new_path}")
    return "; ".join(kept)


async def http_proxy_connection(request: web.Request) -> web.Response:
    """Reverse proxy for user HTTP connections.

    Forwards all HTTP requests to the target service, rewriting URLs
    so that navigation stays within the /proxy/{conn_id}/ path.
    Also handles WebSocket upgrades for real-time web UIs.
    """
    token = await authenticate_request(request)
    if not token:
        raise web.HTTPFound("/login")
    # Registered right after authentication, before any further await, so a
    # revocation that lands while the connection is looked up cannot slip
    # between the two: it aborts this call, and the handler checks `aborted`
    # before it dials the upstream. The registry holds it until the end.
    call = _ProxyHttpCall(request)
    _register_user_proxy_call(token.user_id, call, token.token_id)
    try:
        return await _proxy_connection_authed(request, token, call)
    finally:
        _unregister_user_proxy_call(token.user_id, call)


async def _proxy_connection_authed(request: web.Request, token, call: _ProxyHttpCall) -> web.Response:
    """The body of http_proxy_connection, after authentication and registration."""
    from urllib.parse import urlparse

    conn_uuid = request.match_info.get("conn_id", "")
    if not conn_uuid:
        return web.Response(status=400, text="Invalid connection ID")

    connection = await db.get_accessible_connection(conn_uuid, token.user_id)
    if not connection:
        return web.Response(status=404, text="Connection not found")
    # A proxied call (a long download, an event stream) opened through a share ends with it.
    if not await _track_shared_access(connection, token.user_id, call):
        return web.Response(status=404, text="Connection not found")

    conn_type = connection.get("type", "custom")
    type_info = CONNECTION_TYPES.get(conn_type, {"plugin": "tcp_tunnel"})

    if type_info.get("plugin") != "http_proxy":
        return web.Response(status=400, text="Not an HTTP proxy connection")

    config = connection.get("config", {})
    if isinstance(config, str):
        try:
            config = json.loads(config) if config else {}
        except json.JSONDecodeError:
            config = {}

    # Build target URL
    browser_mode = config.get("browser_mode", False)
    host = connection.get("host")
    default_port = type_info.get("default_port", 80)
    port = connection.get("port") or config.get("port") or default_port
    # Browser mode sends many requests per page: repeat checks of the same
    # name are cached briefly (the connector re-checks every dial).
    _check = resolve_checked_host_cached if browser_mode else resolve_checked_host
    try:
        _target_url_hosts = _user_connection_urls(config, ("target_url",))
        if _target_url_hosts:
            # A user-set target_url is dialled instead of host: check only that.
            for _h in _target_url_hosts:
                await _check(_h, 0)
        else:
            await _check(host, int(port))
    except (HostCheckError, ValueError):
        return web.Response(status=403, text="Host not allowed")
    if not config.get("target_url"):
        # Use HTTPS for types that default to 443 or are explicitly HTTPS
        https_types = {"https", "portainer", "truenas", "pfsense", "nextcloud", "cockpit"}
        scheme = "https" if (conn_type in https_types or port == 443) else "http"
        # Omit default ports (80 for HTTP, 443 for HTTPS) from URL
        default_scheme_port = 443 if scheme == "https" else 80
        if int(port) == default_scheme_port:
            config["target_url"] = f"{scheme}://{host}"
        else:
            config["target_url"] = f"{scheme}://{host}:{port}"

    verify_ssl = config.get("verify_ssl", False)
    proxy_base = f"/proxy/{conn_uuid}"

    # Browser mode: extract target URL from path for multi-site navigation
    raw_path = request.match_info.get("path", "")
    if browser_mode and (raw_path.startswith("http://") or raw_path.startswith("https://")):
        # Full URL in path — navigate to external site
        browse_query = request.query_string
        browse_full = f"{raw_path}?{browse_query}" if browse_query else raw_path
        parsed_browse = urlparse(browse_full)
        browse_host = parsed_browse.hostname or ""
        try:
            # Cached for a short time: the connector re-checks every dial.
            await resolve_checked_host_cached(browse_host, parsed_browse.port or 0)
        except (HostCheckError, ValueError):
            return web.Response(status=403, text="Host not allowed")
        target_origin = f"{parsed_browse.scheme}://{parsed_browse.netloc}"
        target_url = target_origin
        config["target_url"] = target_url
    else:
        target_url = config["target_url"].rstrip("/")

    parsed_target = urlparse(target_url)
    target_origin = f"{parsed_target.scheme}://{parsed_target.netloc}"
    proxy_prefix = f"{proxy_base}/{target_origin}" if browser_mode else proxy_base

    parsed_target = urlparse(target_url)
    target_origin = f"{parsed_target.scheme}://{parsed_target.netloc}"

    # Handle WebSocket upgrade
    if request.headers.get("Upgrade", "").lower() == "websocket":
        if call.aborted:
            return web.Response(status=401, text="Session revoked")
        ws = web.WebSocketResponse()
        await ws.prepare(request)

        ws_scheme = "wss" if parsed_target.scheme == "https" else "ws"
        ws_raw_path = request.match_info.get("path", "")
        ws_query = _proxy_query_string(request)
        if browser_mode and (ws_raw_path.startswith("http://") or ws_raw_path.startswith("https://")):
            ws_parsed = urlparse(f"{ws_raw_path}?{ws_query}" if ws_query else ws_raw_path)
            ws_url = f"{ws_scheme}://{ws_parsed.netloc}{ws_parsed.path}"
            if ws_parsed.query:
                ws_url = f"{ws_url}?{ws_parsed.query}"
        else:
            ws_url = f"{ws_scheme}://{parsed_target.netloc}/{ws_raw_path}"
            if ws_query:
                ws_url = f"{ws_url}?{ws_query}"

        try:
            # Registered inside the try so the finally below always unregisters
            # it, and a session revocation closes this relay as well.
            _register_user_ws(token.user_id, ws, token.token_id)
            # The relay is tracked in the WebSocket registry (closed with code
            # 4001) from here on. The call stayed registered through prepare(),
            # so a revocation during it is seen here.
            _unregister_user_proxy_call(token.user_id, call)
            if call.aborted:
                await ws.close(code=4001, message=b"session revoked")
                return ws
            # Through a share: the relay ends with it (checked again now that it is registered).
            if not await _track_shared_access(connection, token.user_id, ws):
                await ws.close(code=GRANT_ENDED_CLOSE_CODE, message=b"access ended")
                return ws
            # The upgrade's HTTP call record must not stay under the share: ending it would abort
            # the transport the relay runs on, and the client would see a dropped connection (1006)
            # instead of the 4010 close frame. The socket itself is what ends with the share now.
            if connection.get("shared"):
                _forget_grant_dependent("conn", connection["id"], token.user_id, call)
            # The upgrade awaited since the credential was checked; as the chat and
            # generic handlers do, check it again now that the socket is registered.
            if not await _credential_still_valid(token):
                await ws.close(code=4001, message=b"session revoked")
                return ws
            connector = _SSRFSafeConnector(ssl=verify_ssl)
            async with aiohttp.ClientSession(connector=connector) as session:
                async with session.ws_connect(ws_url) as upstream:
                    async def _fwd_client():
                        async for msg in ws:
                            if msg.type == aiohttp.WSMsgType.TEXT:
                                await upstream.send_str(msg.data)
                            elif msg.type == aiohttp.WSMsgType.BINARY:
                                await upstream.send_bytes(msg.data)
                            elif msg.type in (aiohttp.WSMsgType.CLOSE, aiohttp.WSMsgType.ERROR):
                                break

                    async def _fwd_upstream():
                        async for msg in upstream:
                            if msg.type == aiohttp.WSMsgType.TEXT:
                                await ws.send_str(msg.data)
                            elif msg.type == aiohttp.WSMsgType.BINARY:
                                await ws.send_bytes(msg.data)
                            elif msg.type in (aiohttp.WSMsgType.CLOSE, aiohttp.WSMsgType.ERROR):
                                break

                    tasks = [
                        asyncio.create_task(_fwd_client()),
                        asyncio.create_task(_fwd_upstream()),
                    ]
                    try:
                        done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
                    finally:
                        for t in tasks:
                            if not t.done():
                                t.cancel()
                        await asyncio.gather(*tasks, return_exceptions=True)
        except Exception as e:
            logger.error(f"Proxy WS {conn_uuid} error: {e}")
        finally:
            _unregister_user_ws(token.user_id, ws)
        return ws

    # Build upstream URL
    path = request.match_info.get("path", "")
    query = _proxy_query_string(request)
    if browser_mode and (path.startswith("http://") or path.startswith("https://")):
        # Browser mode: full URL already parsed above, extract just the path portion
        parsed_browse = urlparse(f"{path}?{query}" if query else path)
        upstream_path = parsed_browse.path.lstrip("/")
        upstream_url = f"{target_url}/{upstream_path}" if upstream_path else f"{target_url}/"
        if parsed_browse.query:
            upstream_url = f"{upstream_url}?{parsed_browse.query}"
        query = ""  # Already included
    else:
        upstream_url = f"{target_url}/{path}" if path else f"{target_url}/"
        if query:
            upstream_url = f"{upstream_url}?{query}"

    # Apply path rewrite rules (regex match/replace on the path component only)
    rewrite_rules = config.get("path_rewrite_rules") or []
    if rewrite_rules and isinstance(rewrite_rules, list):
        from urllib.parse import urlsplit, urlunsplit
        _split = urlsplit(upstream_url)
        _path = _split.path
        for rule in rewrite_rules:
            _pattern = rule.get("match", "") if isinstance(rule, dict) else ""
            _replace = rule.get("replace", "") if isinstance(rule, dict) else ""
            if _pattern:
                try:
                    _path = re.sub(_pattern, _replace, _path, count=1)
                except re.error:
                    pass  # silently skip invalid regex
        upstream_url = urlunsplit((_split.scheme, _split.netloc, _path, _split.query, _split.fragment))

    # Prepare headers: no Portal auth is passed on, and the forwarding headers
    # (client address, scheme, host, prefix) are set here, never copied.
    fwd_headers = _proxy_request_headers(
        request, config, parsed_target.netloc, proxy_prefix, browser_mode)

    # Record connection usage
    await db.record_connection_usage(connection["id"], token.user_id)
    if call.aborted:
        return web.Response(status=401, text="Session revoked")

    stream_started = False
    stream_resp = None
    try:
        connector = _SSRFSafeConnector(ssl=verify_ssl)
        async with aiohttp.ClientSession(
            connector=connector,
            timeout=_proxy_client_timeout(config),
            auto_decompress=True
        ) as session:
            body = None
            if request.body_exists:
                body = await request.content.read(_PROXY_MAX_REQUEST_SIZE + 1)
                if len(body) > _PROXY_MAX_REQUEST_SIZE:
                    return web.Response(status=413, text="Request body too large")

            _extra = config.get("extra_headers")
            if call.aborted:
                # revoked while the request body was being read
                return web.Response(status=401, text="Session revoked")
            async with _proxy_open_upstream(
                session, request.method, upstream_url, fwd_headers, body,
                # Browser mode: the redirect goes to the browser with its
                # Location rewritten (every hop then comes back through here).
                # Otherwise the portal follows it, every hop dialled through
                # the outbound policy connector.
                follow=not browser_mode,
                proxy_prefix=proxy_prefix,
                target_origin=target_origin,
                own_headers={str(k).lower() for k in _extra} if isinstance(_extra, dict) else set(),
                call=call,
            ) as resp:
                call.resp = resp
                if call.aborted:
                    return web.Response(status=401, text="Session revoked")
                # Build response headers (before reading body — needed for streaming path).
                # Repeated headers (several Set-Cookie lines) are all kept.
                resp_headers = CIMultiDict()
                for key, value in resp.headers.items():
                    k = key.lower()
                    if k in ("transfer-encoding", "connection", "keep-alive",
                             "proxy-authenticate", "proxy-authorization",
                             "te", "trailers", "upgrade",
                             "content-security-policy", "x-frame-options",
                             "content-encoding", "content-length",
                             "cache-control", "expires", "age",
                             # an upstream may not widen the scope of a worker it serves to the portal's own paths
                             "service-worker-allowed"):
                        continue

                    # Rewrite Location headers for redirects
                    if k == "location":
                        loc = value
                        if browser_mode:
                            # Browser mode: encode full URL in proxy path
                            loc = _proxy_browser_location(loc, proxy_base, target_origin)
                        else:
                            loc = _proxy_rewrite_location(loc, proxy_prefix, target_origin)
                        resp_headers.add(key, loc)
                        continue

                    # Every Set-Cookie: Path moved under the proxy path, Domain dropped
                    if k == "set-cookie":
                        # Per-site path in browser mode, so one site's cookies
                        # are never sent to another site.
                        rewritten = _rewrite_set_cookie(value, proxy_prefix)
                        if rewritten is not None:
                            resp_headers.add(key, rewritten)
                        continue

                    resp_headers.add(key, value)

                # Proxied content is per-connection and session-scoped — never let a shared
                # edge cache (e.g. Cloudflare) store it keyed by URL alone across sessions.
                resp_headers["Cache-Control"] = "private, no-store"
                # Documents get a policy before the body is streamed or buffered (see _proxy_document_csp)
                doc_csp = _proxy_document_csp(resp.headers.get("Content-Type", ""))
                if doc_csp:
                    resp_headers["Content-Security-Policy"] = doc_csp

                # Check if response needs URL rewriting
                content_type = resp.headers.get("Content-Type", "")
                needs_rewriting = any(t in content_type for t in ("text/html", "text/css", "javascript", "application/json"))

                if not needs_rewriting:
                    # Stream binary/media directly (no rewriting needed, no size limit)
                    stream_resp = web.StreamResponse(status=resp.status, headers=resp_headers)
                    await stream_resp.prepare(request)
                    stream_started = True
                    client_gone = False
                    async for chunk in resp.content.iter_chunked(65536):
                        try:
                            await stream_resp.write(chunk)
                        except ConnectionError:
                            client_gone = True
                            break
                    if not client_gone and not call.aborted:
                        try:
                            await stream_resp.write_eof()
                        except ConnectionError:
                            client_gone = True
                    if call.aborted:
                        # Ended by revocation, not by the upstream: never a clean end.
                        logger.info(f"Proxy connection {conn_uuid}: stream ended, session revoked")
                        call.abort()
                    return stream_resp

                # Text content: read with a size limit and, because it is held in
                # memory, a total time limit (the connection's timeout), so an
                # upstream that trickles bytes cannot hold the buffer for ever.
                async def _read_text_body():
                    chunks = []
                    total_size = 0
                    while True:
                        chunk = await resp.content.read(65536)
                        if not chunk:
                            return b''.join(chunks)
                        total_size += len(chunk)
                        if total_size > _PROXY_MAX_RESPONSE_SIZE:
                            return None
                        chunks.append(chunk)

                response_body = await asyncio.wait_for(
                    _read_text_body(), _proxy_timeout_seconds(config.get("timeout")))
                if response_body is None:
                    return web.Response(status=502, text="Upstream response too large")
                if call.aborted:
                    return web.Response(status=401, text="Session revoked")

                if needs_rewriting:
                    try:
                        charset = "utf-8"
                        if "charset=" in content_type:
                            charset = content_type.split("charset=")[1].split(";")[0].strip().strip('"\'')
                        text = response_body.decode(charset)

                        if browser_mode:
                            # Browser mode: rewrite target origin → proxy_prefix (which includes origin in path)
                            text = text.replace(target_origin, proxy_prefix)
                            # Protocol-relative //host — use negative lookbehind to skip ://host inside already-rewritten URLs
                            text = re.sub(
                                rf'(?<!:)//{re.escape(parsed_target.netloc)}',
                                proxy_prefix,
                                text
                            )

                            esc_base = re.escape(proxy_base[1:])

                            if "text/css" in content_type:
                                # Rewrite url(/...) to include target origin
                                text = re.sub(
                                    rf'url\(\s*(["\']?)/(?!/|{esc_base})',
                                    rf'url(\1{proxy_prefix}/',
                                    text
                                )

                            if "text/html" in content_type:
                                # Rewrite absolute external URLs in HTML attrs → proxy path
                                text = re.sub(
                                    rf'((?:href|src|action|data|poster|srcset|formaction)\s*=\s*["\'])(https?://)',
                                    rf'\1{proxy_base}/\2',
                                    text
                                )
                                # Fix double-rewriting: proxy_base/proxy_base → proxy_base
                                double_prefix = f"{proxy_base}/{proxy_base}/"
                                while double_prefix in text:
                                    text = text.replace(double_prefix, f"{proxy_base}/")
                                # Rewrite protocol-relative //host in HTML attrs (use target's scheme)
                                text = re.sub(
                                    rf'((?:href|src|action|data|poster|srcset|formaction)\s*=\s*["\'])//(?!{esc_base})',
                                    rf'\1{proxy_base}/{parsed_target.scheme}://',
                                    text
                                )
                                # Rewrite root-relative URLs in HTML attrs
                                text = re.sub(
                                    rf'((?:href|src|action|data|poster|srcset|formaction)\s*=\s*["\'])/(?!/|{esc_base})',
                                    rf'\1{proxy_prefix}/',
                                    text
                                )
                                # Rewrite url(/...) in inline styles
                                text = re.sub(
                                    rf'url\(\s*(["\']?)/(?!/|{esc_base})',
                                    rf'url(\1{proxy_prefix}/',
                                    text
                                )
                                # Meta refresh redirects
                                text = re.sub(
                                    r'(content\s*=\s*["\']\d+\s*;\s*url\s*=\s*)/',
                                    rf'\1{proxy_prefix}/',
                                    text,
                                    flags=re.IGNORECASE
                                )

                                # Browser-mode JS interceptor: rewrites ALL URLs through proxy
                                inject_js = (
                                    f'<script>(function(){{"use strict";'
                                    f'var B="{proxy_base}";'
                                    f'var O="{target_origin}";'
                                    f'var P=location.origin;'
                                    # Helper: rewrite a URL string
                                    f'function R(u){{if(typeof u!=="string")return u;'
                                    # Already rewritten — starts with proxy base
                                    f'if(u.startsWith(B+"/"))return u;'
                                    f'if(u.startsWith(P+B+"/"))return u.slice(P.length);'
                                    # Absolute URL — strip portal origin if present, then wrap
                                    f'if(u.startsWith(P+"/"))return B+"/"+O+u.slice(P.length);'
                                    f'if(u.startsWith(P))return B+"/"+O+u.slice(P.length);'
                                    f'if(u.startsWith("http://")||u.startsWith("https://"))return B+"/"+u;'
                                    f'if(u.startsWith("//"))return B+"/"+O.split("//")[0]+u;'
                                    f'if(u.startsWith("/")&&!u.startsWith(B))return B+"/"+O+u;'
                                    f'return u}}'
                                    # fetch()
                                    f'var _f=window.fetch;window.fetch=function(u,o){{'
                                    f'if(typeof u==="string")u=R(u);'
                                    f'else if(u instanceof Request)u=new Request(R(u.url),u);'
                                    f'return _f.call(this,u,o)}};'
                                    # XMLHttpRequest.open()
                                    f'var _xo=XMLHttpRequest.prototype.open;'
                                    f'XMLHttpRequest.prototype.open=function(){{'
                                    f'if(arguments.length>1)arguments[1]=R(arguments[1]);'
                                    f'return _xo.apply(this,arguments)}};'
                                    # WebSocket
                                    f'var _W=window.WebSocket;'
                                    f'function PW(u,p){{if(typeof u==="string"){{'
                                    f'if(u.startsWith("wss://")||u.startsWith("ws://"))'
                                    f'u="wss://"+location.host+B+"/"+u.replace("wss://","https://").replace("ws://","http://")}}'
                                    f'if(p!==undefined)return new _W(u,p);return new _W(u)}};'
                                    f'PW.prototype=_W.prototype;PW.CONNECTING=0;PW.OPEN=1;PW.CLOSING=2;PW.CLOSED=3;'
                                    f'window.WebSocket=PW;'
                                    # EventSource
                                    f'if(window.EventSource){{var _E=window.EventSource;'
                                    f'window.EventSource=function(u,o){{return new _E(R(u),o)}};'
                                    f'window.EventSource.prototype=_E.prototype}}'
                                    # Intercept src/href IDL property setters — dynamically-created
                                    # elements (webpack/Vite chunk loading: el.src=url; append(el))
                                    # start fetching the moment src is set, before MutationObserver
                                    # (which only fires on insertion, as a microtask) can rewrite it.
                                    f'[["HTMLScriptElement","src"],["HTMLImageElement","src"],'
                                    f'["HTMLIFrameElement","src"],["HTMLSourceElement","src"],'
                                    f'["HTMLEmbedElement","src"],["HTMLMediaElement","src"],'
                                    f'["HTMLLinkElement","href"]].forEach(function(pair){{'
                                    f'var ctor=window[pair[0]];if(!ctor)return;'
                                    f'var proto=ctor.prototype;var prop=pair[1];'
                                    f'var desc=Object.getOwnPropertyDescriptor(proto,prop);'
                                    f'if(!desc||!desc.set)return;'
                                    f'Object.defineProperty(proto,prop,{{configurable:true,enumerable:desc.enumerable,'
                                    f'get:desc.get,set:function(v){{return desc.set.call(this,R(v))}}}})}});'
                                    # Intercept setAttribute() for the same resource-bearing attrs —
                                    # covers frameworks that set attributes directly rather than IDL props.
                                    f'var _sa=Element.prototype.setAttribute;'
                                    f'var _RA={{src:1,href:1,action:1,data:1,poster:1,formaction:1}};'
                                    f'Element.prototype.setAttribute=function(name,value){{'
                                    f'if(_RA[String(name).toLowerCase()])value=R(value);'
                                    f'return _sa.call(this,name,value)}};'
                                    # window.open() — send to parent as new tab
                                    f'window.open=function(u){{if(u){{var ru=R(u);'
                                    f'try{{window.top.postMessage({{type:"openTab",url:ru}},location.origin)}}catch{{}}'
                                    f'}}return null}};'
                                    # navigator.sendBeacon()
                                    f'if(navigator.sendBeacon){{var _sb=navigator.sendBeacon.bind(navigator);'
                                    f'navigator.sendBeacon=function(u,d){{return _sb(R(u),d)}}}}'
                                    # Intercept link clicks — target=_blank opens in new tab
                                    f'document.addEventListener("click",function(e){{'
                                    f'var a=e.target.closest("a[href]");'
                                    f'if(a){{var h=a.getAttribute("href");'
                                    f'var t=a.getAttribute("target");'
                                    f'if(h){{var rh=R(h);'
                                    f'if(t==="_blank"||e.ctrlKey||e.metaKey||e.button===1){{'
                                    f'e.preventDefault();e.stopPropagation();'
                                    f'try{{window.top.postMessage({{type:"openTab",url:rh}},location.origin)}}catch{{}}'
                                    f'return}}a.setAttribute("href",rh)}}'
                                    f'}}}},true);'
                                    f'document.addEventListener("submit",function(e){{'
                                    f'var f=e.target;if(f.tagName==="FORM"){{'
                                    f'var a=f.getAttribute("action");'
                                    f'if(a){{f.action=R(a)}}'
                                    f'else{{f.action=R(location.pathname+location.search)}}'
                                    f'}}}},true);'
                                    # Override Location.prototype.assign/replace
                                    f'var _la=Location.prototype.assign;'
                                    f'Location.prototype.assign=function(u){{return _la.call(this,R(u))}};'
                                    f'var _lr=Location.prototype.replace;'
                                    f'Location.prototype.replace=function(u){{return _lr.call(this,R(u))}};'
                                    # MutationObserver for dynamically added elements
                                    f'new MutationObserver(function(ms){{ms.forEach(function(m){{'
                                    f'm.addedNodes.forEach(function(n){{if(n.nodeType!==1)return;'
                                    f'var els=n.querySelectorAll?[n].concat(Array.from(n.querySelectorAll("[src],[href],[action],[data],[poster],[formaction]"))):[n];'
                                    f'els.forEach(function(el){{'
                                    f'["src","href","action","data","poster","formaction"].forEach(function(a){{'
                                    f'var v=el.getAttribute&&el.getAttribute(a);'
                                    f'if(v)el.setAttribute(a,R(v))'
                                    f'}})}})}})}})}}).observe(document.documentElement,{{childList:true,subtree:true}});'
                                    # Override history.pushState/replaceState
                                    f'var _ps=history.pushState;history.pushState=function(s,t,u){{return _ps.call(this,s,t,u?R(u):u)}};'
                                    f'var _rs=history.replaceState;history.replaceState=function(s,t,u){{return _rs.call(this,s,t,u?R(u):u)}};'
                                    f'}})();</script>'
                                )
                                head_idx = text.lower().find("<head")
                                if head_idx >= 0:
                                    close_idx = text.find(">", head_idx)
                                    if close_idx >= 0:
                                        insert_at = close_idx + 1
                                        text = text[:insert_at] + inject_js + text[insert_at:]
                                else:
                                    text = inject_js + text

                        else:
                            # Standard single-site proxy mode
                            text = text.replace(target_origin, proxy_prefix)
                            text = text.replace(f"//{parsed_target.netloc}", proxy_prefix)
                            final_url = str(resp.url)
                            final_parsed = urlparse(final_url)
                            final_origin = f"{final_parsed.scheme}://{final_parsed.netloc}"
                            if final_origin != target_origin:
                                text = text.replace(final_origin, proxy_prefix)
                                text = text.replace(f"//{final_parsed.netloc}", proxy_prefix)

                            esc_pfx = re.escape(proxy_prefix[1:])

                            if "text/css" in content_type:
                                text = re.sub(
                                    rf'url\(\s*(["\']?)/(?!/|{esc_pfx})',
                                    rf'url(\1{proxy_prefix}/',
                                    text
                                )

                            if "text/html" in content_type:
                                text = re.sub(
                                    rf'((?:href|src|action|data|poster|srcset|formaction)\s*=\s*["\'])/(?!/|{esc_pfx})',
                                    rf'\1{proxy_prefix}/',
                                    text
                                )
                                text = re.sub(
                                    rf'url\(\s*(["\']?)/(?!/|{esc_pfx})',
                                    rf'url(\1{proxy_prefix}/',
                                    text
                                )
                                text = re.sub(
                                    r'(content\s*=\s*["\']\d+\s*;\s*url\s*=\s*)/',
                                    rf'\1{proxy_prefix}/',
                                    text,
                                    flags=re.IGNORECASE
                                )

                                final_url = str(resp.url)
                                final_parsed = urlparse(final_url)
                                final_origin = f"{final_parsed.scheme}://{final_parsed.netloc}"

                                inject_js = (
                                    f'<script>(function(){{"use strict";'
                                    f'var B="{proxy_prefix}";'
                                    f'var TO="{target_origin}";'
                                    f'var FO="{final_origin}";'
                                    f'function R(u){{if(typeof u!=="string")return u;'
                                    f'if(u.startsWith(TO))return B+u.slice(TO.length);'
                                    f'if(FO!==TO&&u.startsWith(FO))return B+u.slice(FO.length);'
                                    f'if(u.startsWith("/")&&!u.startsWith(B)&&!u.startsWith("//"))return B+u;'
                                    f'return u}}'
                                    f'var _f=window.fetch;window.fetch=function(u,o){{'
                                    f'if(typeof u==="string")u=R(u);'
                                    f'else if(u instanceof Request)u=new Request(R(u.url),u);'
                                    f'return _f.call(this,u,o)}};'
                                    f'var _xo=XMLHttpRequest.prototype.open;'
                                    f'XMLHttpRequest.prototype.open=function(){{'
                                    f'if(arguments.length>1)arguments[1]=R(arguments[1]);'
                                    f'return _xo.apply(this,arguments)}};'
                                    f'var _W=window.WebSocket;'
                                    f'function PW(u,p){{if(typeof u==="string"){{'
                                    f'var m=u.match(/^(wss?:\\/\\/[^/]+)(\\/.*)$/);'
                                    f'if(m&&!m[2].startsWith(B))u=m[1]+B+m[2]}}'
                                    f'if(p!==undefined)return new _W(u,p);return new _W(u)}};'
                                    f'PW.prototype=_W.prototype;PW.CONNECTING=0;PW.OPEN=1;PW.CLOSING=2;PW.CLOSED=3;'
                                    f'window.WebSocket=PW;'
                                    f'if(window.EventSource){{var _E=window.EventSource;'
                                    f'window.EventSource=function(u,o){{return new _E(R(u),o)}};'
                                    f'window.EventSource.prototype=_E.prototype}}'
                                    f'var _wo=window.open;window.open=function(u){{arguments[0]=R(u);return _wo.apply(this,arguments)}};'
                                    f'if(navigator.sendBeacon){{var _sb=navigator.sendBeacon.bind(navigator);'
                                    f'navigator.sendBeacon=function(u,d){{return _sb(R(u),d)}}}}'
                                    f'document.addEventListener("click",function(e){{'
                                    f'var a=e.target.closest("a[href]");'
                                    f'if(a&&a.href){{'
                                    f'var h=a.getAttribute("href");'
                                    f'if(h&&h.startsWith("/")&&!h.startsWith(B))a.setAttribute("href",B+h)'
                                    f'}}}},true);'
                                    f'document.addEventListener("submit",function(e){{'
                                    f'var f=e.target;if(f.action){{'
                                    f'var u=new URL(f.action,location.href);'
                                    f'if(u.pathname.startsWith("/")&&!u.pathname.startsWith(B))'
                                    f'f.action=B+u.pathname+u.search'
                                    f'}}}},true);'
                                    f'new MutationObserver(function(ms){{ms.forEach(function(m){{'
                                    f'm.addedNodes.forEach(function(n){{if(n.nodeType!==1)return;'
                                    f'var els=n.querySelectorAll?[n].concat(Array.from(n.querySelectorAll("[src],[href],[action],[data],[poster],[formaction]"))):[n];'
                                    f'els.forEach(function(el){{'
                                    f'["src","href","action","data","poster","formaction"].forEach(function(a){{'
                                    f'var v=el.getAttribute&&el.getAttribute(a);'
                                    f'if(v&&v.startsWith("/")&&!v.startsWith(B)&&!v.startsWith("//"))el.setAttribute(a,B+v)'
                                    f'}})}})}})}})}}).observe(document.documentElement,{{childList:true,subtree:true}});'
                                    f'var _ps=history.pushState;history.pushState=function(s,t,u){{return _ps.call(this,s,t,u?R(u):u)}};'
                                    f'var _rs=history.replaceState;history.replaceState=function(s,t,u){{return _rs.call(this,s,t,u?R(u):u)}};'
                                    f'}})();</script>'
                                )
                                head_idx = text.lower().find("<head")
                                if head_idx >= 0:
                                    close_idx = text.find(">", head_idx)
                                    if close_idx >= 0:
                                        insert_at = close_idx + 1
                                        text = text[:insert_at] + inject_js + text[insert_at:]
                                else:
                                    text = inject_js + text

                        response_body = text.encode(charset)
                    except (UnicodeDecodeError, UnicodeEncodeError, LookupError):
                        pass

                return web.Response(
                    status=resp.status,
                    headers=resp_headers,
                    body=response_body
                )

    except asyncio.TimeoutError:
        # Connect took over 10 s, the upstream was silent for `timeout` seconds,
        # or a rewritten text response did not arrive within `timeout` in total.
        # (aiohttp's own timeout errors are ClientErrors too, so this clause
        # comes first.)
        if call.aborted:
            return _proxy_revoked_response(call, stream_resp, conn_uuid)
        if stream_started:
            return _proxy_cut_download(call, stream_resp, conn_uuid, "idle timeout")
        logger.error(f"Proxy connection {conn_uuid} timed out")
        return web.Response(
            status=504,
            content_type="text/html",
            text="<html><body style='background:#1a1a2e;color:#e0e0e0;font-family:sans-serif;padding:2rem'>"
                 "<h2>Upstream service timed out</h2>"
                 "<p>The upstream service did not answer in time.</p>"
                 "<p><a href='/dashboard' style='color:#4fc3f7'>Back to Dashboard</a></p>"
                 "</body></html>"
        )
    except aiohttp.ClientError as e:
        if call.aborted:
            return _proxy_revoked_response(call, stream_resp, conn_uuid)
        if stream_started:
            return _proxy_cut_download(call, stream_resp, conn_uuid, f"{type(e).__name__}: {e}")
        logger.error(f"Proxy connection {conn_uuid} error: {e}")
        return web.Response(
            status=502,
            content_type="text/html",
            text="<html><body style='background:#1a1a2e;color:#e0e0e0;font-family:sans-serif;padding:2rem'>"
                 "<h2>Cannot reach upstream service</h2>"
                 "<p>The upstream service is unreachable. Check that it is running and accessible.</p>"
                 "<p><a href='/dashboard' style='color:#4fc3f7'>Back to Dashboard</a></p>"
                 "</body></html>"
        )


def _proxy_cut_download(call: _ProxyHttpCall, stream_resp, conn_uuid: str, why: str):
    """The upstream failed after the 200 and part of the body were sent.

    A new response would be written into that body and the download would
    end as if complete, so the client connection is dropped instead (the
    client sees an incomplete body). One warning line; returning the response
    rather than raising keeps aiohttp from logging a traceback for it.
    """
    logger.warning(f"Proxy connection {conn_uuid}: download cut short ({why})")
    call.abort()
    return stream_resp


def _proxy_revoked_response(call: _ProxyHttpCall, stream_resp, conn_uuid: str):
    logger.info(f"Proxy connection {conn_uuid}: ended, session revoked")
    call.abort()
    return stream_resp if stream_resp is not None else web.Response(status=401, text="Session revoked")


_SEARXNG_REQUEST_HOP_HEADERS = frozenset({
    "host", "content-length", "transfer-encoding", "connection", "keep-alive",
    "proxy-authenticate", "proxy-authorization", "te", "trailers", "upgrade",
    "accept-encoding", "authorization",
})
_SEARXNG_RESPONSE_HOP_HEADERS = frozenset({
    "transfer-encoding", "connection", "keep-alive", "proxy-authenticate",
    "proxy-authorization", "te", "trailers", "upgrade", "content-encoding",
    "content-length", "service-worker-allowed",
})
# Kept in sync with services/searxng.py DEFAULT_PORT (8888/8889 are MediaMTX).
_SEARXNG_DEFAULT_PORT = 8890

# Injected before </head> on SearXNG HTML pages so /search/ wears the portal
# navbar and follows the active portal theme. See static/{css,js}/searxng-portal.*
_SEARXNG_HEAD_INJECT = (
    b'<script src="/static/js/theme.js?v=3"></script>'
    b'<link rel="stylesheet" href="/static/css/portal.css?v=55">'
    b'<link rel="stylesheet" href="/static/css/searxng-portal.css?v=6">'
    b'<script src="/static/js/searxng-portal.js?v=4" defer></script>'
    b'<script src="/static/js/push.js?v=4" defer></script>'
)


async def _searxng_status() -> tuple[bool, int]:
    """Return (available, port) for the SearXNG managed service.

    "Available" means the service row exists, is enabled (the admin toggle), and
    is currently running. When SearXNG is not set up or is disabled, the portal
    stays fully functional — the /search/ route and nav link just go dark.
    """
    port = _SEARXNG_DEFAULT_PORT
    if not _service_manager:
        return False, port
    svc = await _service_manager.get_service_by_name("searxng")
    if svc is None or not getattr(svc, "enabled", False):
        return False, port
    try:
        port = int(svc.get_merged_config().get("port", port))
    except (TypeError, ValueError):
        pass
    return (svc.status == "running"), port


async def http_search_status(request: web.Request) -> web.Response:
    """Report whether SearXNG search is available (used to show/hide the nav link)."""
    token = await authenticate_request(request)
    if not token:
        return web.json_response({"available": False}, status=200)
    available, _ = await _searxng_status()
    return web.json_response({"available": available})


def _searxng_unavailable_response(request: web.Request) -> web.Response:
    if "application/json" in request.headers.get("Accept", "") or \
            request.query.get("format") == "json":
        return web.json_response({"error": "Search is not enabled on this portal"}, status=503)
    return web.Response(
        status=503, content_type="text/html",
        text="<html><body style='background:#1a1a2e;color:#e0e0e0;"
             "font-family:sans-serif;padding:2rem'>"
             "<h2>Search is not enabled</h2>"
             "<p>This portal does not currently have the SearXNG search service running. "
             "An admin can enable it from the Services panel.</p>"
             "<p><a href='/dashboard' style='color:#4fc3f7'>Back to Dashboard</a></p>"
             "</body></html>")


async def http_searxng_proxy(request: web.Request) -> web.Response:
    """Auth-gated reverse proxy for the SearXNG managed service.

    SearXNG mounts its whole app under ``/search/`` natively via
    ``server.base_url``, so requests are forwarded verbatim — no path or body
    rewriting. Only authenticated Portal users may reach it, and only when an
    admin has enabled the ``searxng`` managed service.
    """
    token = await authenticate_request(request)
    if not token:
        if "application/json" in request.headers.get("Accept", "") or \
                request.query.get("format") == "json":
            return web.json_response({"error": "Unauthorized"}, status=401)
        raise web.HTTPFound("/login")

    available, port = await _searxng_status()
    if not available:
        return _searxng_unavailable_response(request)

    upstream_url = f"http://127.0.0.1:{port}{request.raw_path}"

    fwd_headers = {}
    for key, value in request.headers.items():
        k = key.lower()
        if k in _SEARXNG_REQUEST_HOP_HEADERS:
            continue
        if k == "cookie":
            cookies = [c.strip() for c in value.split(";")
                       if not c.strip().startswith(Config.SESSION_COOKIE_NAME + "=")]
            if cookies:
                fwd_headers[key] = "; ".join(cookies)
            continue
        fwd_headers[key] = value
    fwd_headers["Host"] = f"127.0.0.1:{port}"
    fwd_headers["X-Forwarded-For"] = request.remote or ""
    fwd_headers["X-Forwarded-Proto"] = "https"
    fwd_headers["X-Real-IP"] = request.remote or ""

    body = None
    if request.body_exists:
        body = await request.read()
        if len(body) > _PROXY_MAX_REQUEST_SIZE:
            return web.Response(status=413, text="Request body too large")

    try:
        async with aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=60),
            auto_decompress=True,
        ) as session:
            async with session.request(
                method=request.method,
                url=upstream_url,
                headers=fwd_headers,
                data=body,
                allow_redirects=False,
            ) as resp:
                resp_headers = {
                    key: value for key, value in resp.headers.items()
                    if key.lower() not in _SEARXNG_RESPONSE_HOP_HEADERS
                }
                # Never let a shared edge cache store authenticated content.
                resp_headers["Cache-Control"] = "private, no-store"
                # SVG, XHTML and XML (SearXNG's image proxy passes any image/* type from any host)
                # get the HTTP proxy's policy; text/html keeps the portal page policy the middleware adds.
                sx_type = resp.headers.get("Content-Type", "").split(";", 1)[0].strip().lower()
                sx_csp = _proxy_document_csp(sx_type) if sx_type != "text/html" else None
                if sx_csp:
                    for key in [k for k in resp_headers if k.lower() == "content-security-policy"]:
                        del resp_headers[key]
                    resp_headers["Content-Security-Policy"] = sx_csp

                # Buffer the full body (StreamReader.read(n) can return early on a
                # chunked response, so loop to EOF) so security_headers_middleware
                # can still attach CSP/HSTS/etc.
                chunks = []
                total = 0
                while True:
                    chunk = await resp.content.read(65536)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > _PROXY_MAX_RESPONSE_SIZE:
                        return web.Response(status=502, text="Upstream response too large")
                    chunks.append(chunk)
                out = b"".join(chunks)

                # Give SearXNG pages the portal chrome + theme.
                if "text/html" in resp.headers.get("Content-Type", "") and b"</head>" in out:
                    out = out.replace(b"</head>", _SEARXNG_HEAD_INJECT + b"</head>", 1)

                return web.Response(status=resp.status, headers=resp_headers, body=out)
    except aiohttp.ClientError as e:
        logger.error(f"SearXNG proxy error: {e}")
        return web.Response(
            status=502, content_type="text/html",
            text="<html><body style='background:#1a1a2e;color:#e0e0e0;"
                 "font-family:sans-serif;padding:2rem'>"
                 "<h2>Cannot reach SearXNG</h2>"
                 "<p>The search backend is unreachable. Check that the service is running.</p>"
                 "<p><a href='/dashboard' style='color:#4fc3f7'>Back to Dashboard</a></p>"
                 "</body></html>")


async def http_admin_page(request: web.Request) -> web.Response:
    """Serve admin panel page (admin only)."""
    token = await authenticate_request(request)
    if not token:
        raise web.HTTPFound("/login")

    # Check admin access
    if not token.has_scope("admin") and not token.has_scope("*"):
        raise web.HTTPFound("/dashboard")

    html = load_static_file("admin.html")
    return web.Response(text=html, content_type="text/html")


async def http_api_docs_page(request: web.Request) -> web.Response:
    """Serve API documentation page (public access for SEO).

    Admin-only API sections are stripped server-side for non-admin users
    so the HTML source never contains admin endpoint documentation.
    """
    html = load_static_file("api-docs.html")

    # Strip admin-only sections server-side for non-admin users
    token = await authenticate_request(request)
    is_admin = False
    if token:
        user = await db.get_user_by_id(token.user_id) if token.user_id else None
        if user and (user.get("is_admin") or user.get("role") in ("superadmin", "admin")):
            is_admin = True

    if not is_admin:
        # Remove <div class="...admin-only...">...</div> blocks by tracking nesting
        result = []
        i = 0
        skip_depth = 0
        while i < len(html):
            if skip_depth > 0:
                if html[i:i+4].lower() == '<div':
                    skip_depth += 1
                elif html[i:i+6].lower() == '</div>':
                    skip_depth -= 1
                    if skip_depth == 0:
                        i += 6
                        continue
                i += 1
                continue

            if html[i:i+4].lower() == '<div':
                tag_end = html.find('>', i)
                if tag_end != -1:
                    tag = html[i:tag_end+1]
                    if 'admin-only' in tag:
                        skip_depth = 1
                        i = tag_end + 1
                        continue

            result.append(html[i])
            i += 1

        html = ''.join(result)
        # Also strip orphaned HTML comments that preceded admin-only divs
        import re as _re
        html = _re.sub(r'<!--\s*[^>]*\(Admin\)\s*-->\s*\n?\s*', '', html)

    # Inject dynamic hostname for canonical URLs and OG tags
    hostname = Config.HOSTNAME or "localhost"
    html = html.replace("{{HOSTNAME}}", _html.escape(hostname))
    return web.Response(text=html, content_type="text/html")


