# =============================================================================
# Chat/Forum System
# =============================================================================

# Chat room state: channel -> set of (ws, user_id, username)
chat_rooms: dict[str, set] = {}

# Mutable chat user state: user_id -> dict with anonymous, nickname, avatar
# Updated by HTTP handlers so WS handlers see changes immediately
chat_user_state: dict[int, dict] = {}
# Number of open chat sockets per user; the state dict above is shared by all of them
_chat_state_refs: dict[int, int] = {}


def _chat_state_acquire(user_id: int, fresh: dict) -> dict:
    """Return the one state dict every chat socket of this user shares.

    A user can hold several chat sockets (main tab and pop-out window). The HTTP
    handlers update the registry entry, so each socket must use that same dict,
    otherwise an older socket keeps stale anonymous/nickname/avatar values.
    Call it inside the try whose finally calls _chat_state_release.
    """
    state = chat_user_state.get(user_id)
    if state is None:
        state = chat_user_state[user_id] = dict(fresh)
    # else: an older socket is connected and the HTTP handlers keep this dict
    # current. `fresh` was read from the database before the handshake and may
    # be older than a change made since, so the live state wins.
    _chat_state_refs[user_id] = _chat_state_refs.get(user_id, 0) + 1
    return state


def _chat_state_release(user_id: int) -> None:
    """Drop one socket's hold on the shared state; forget it with the last socket."""
    count = _chat_state_refs.get(user_id, 1) - 1
    if count <= 0:
        _chat_state_refs.pop(user_id, None)
        chat_user_state.pop(user_id, None)
    else:
        _chat_state_refs[user_id] = count

# Voice chat state: channel_name -> {user_id -> {ws, username, muted, deafened, speaking}}
voice_state: dict[str, dict[int, dict]] = {}
# Rate-limit speaking broadcasts: (channel, user_id) -> last_broadcast_time
_voice_speaking_last: dict[tuple, float] = {}
# Slowmode tracking: (channel_id, user_id) -> monotonic timestamp of last message
_slowmode_last_msg: dict[tuple[int, int], float] = {}

# DM WebSocket tracking: user_id -> set of ws connections for DM delivery
dm_user_connections: dict[int, set] = {}

# Automod rule cache
_automod_rules_cache: list = []
_automod_cache_time: float = 0
_AUTOMOD_CACHE_TTL = 30  # seconds


async def audit_log(action: str, actor_id: int, actor_username: str, **kwargs) -> None:
    """Create an audit log entry. Never raises — failures are logged silently."""
    try:
        await db.create_audit_entry(
            action=action,
            actor_id=actor_id,
            actor_username=actor_username,
            target_id=kwargs.get("target_id"),
            target_type=kwargs.get("target_type"),
            target_name=kwargs.get("target_name"),
            details=kwargs.get("details"),
            channel_id=kwargs.get("channel_id"),
            channel_name=kwargs.get("channel_name"),
        )
    except Exception as e:
        logger.error(f"[AuditLog] Failed to log {action}: {e}")


async def _get_automod_rules() -> list:
    """Get automod rules with caching."""
    global _automod_rules_cache, _automod_cache_time
    now = monotonic()
    if now - _automod_cache_time > _AUTOMOD_CACHE_TTL:
        _automod_rules_cache = await db.get_automod_rules(enabled_only=True)
        _automod_cache_time = now
    return _automod_rules_cache


_automod_regex = automod.RegexRunner()
_automod_warned_patterns: set = set()


async def _check_word_filter(text: str, config: dict, user_id=None) -> bool:
    """Check if message matches a word filter rule."""
    words = config.get("words", [])
    match_mode = config.get("match_mode", "contains")
    text_lower = text.lower()
    for word in words:
        if not isinstance(word, str):
            continue
        word_lower = word.lower()
        if match_mode == "exact":
            if word_lower in text_lower.split():
                return True
        elif match_mode == "regex":
            # Rules stored before validation existed may hold unsafe patterns.
            problem = automod.regex_problem(word)
            if problem:
                if word not in _automod_warned_patterns and len(_automod_warned_patterns) < 1000:
                    _automod_warned_patterns.add(word)
                    logger.warning(f"[AutoMod] Skipping unsafe stored regex pattern: {problem}")
                continue
            if await _automod_regex.search(word, text, user_id=user_id):
                return True
        else:  # contains
            if word_lower in text_lower:
                return True
    return False


def _check_link_filter(text: str, config: dict) -> bool:
    """Check if message contains blocked links."""
    urls = re.findall(r'https?://([^\s/]+)', text)
    if not urls:
        return False
    if config.get("block_all", False):
        allow_list = [d.lower() for d in config.get("allow_list", [])]
        for url in urls:
            if url.lower() not in allow_list:
                return True
        return False
    block_list = [d.lower() for d in config.get("block_list", [])]
    for url in urls:
        if url.lower() in block_list:
            return True
    return False


def _check_caps_filter(text: str, config: dict) -> bool:
    """Check if message has excessive caps."""
    min_length = config.get("min_length", 10)
    if len(text) < min_length:
        return False
    alpha = [c for c in text if c.isalpha()]
    if not alpha:
        return False
    caps_pct = sum(1 for c in alpha if c.isupper()) / len(alpha) * 100
    return caps_pct > config.get("max_caps_percent", 70)


def _check_mention_spam(text: str, config: dict, mass_allowed: bool = True) -> bool:
    """Check if message has too many @mentions. Where the sender may mass mention in the channel
    (mass_allowed), an @here or @everyone counts MASS_MENTION_WEIGHT times (it is already one
    hit of the pattern, so it adds weight - 1). Where they may not, the text is plain text and
    counts as one mention like any other @name."""
    mentions = re.findall(r'@[\w\- ]+', text)
    weight = len(mentions)
    if mass_allowed:
        weight += (MASS_MENTION_WEIGHT - 1) * len(_mass_mention_tokens(text))
    return weight > config.get("max_mentions", 5)


async def check_automod(text: str, user_id: int, channel_id: int, channel_name: str,
                        mass_allowed: bool = True) -> dict | None:
    """Check message against automod rules. Returns action dict if triggered, None if clean.
    mass_allowed: the sender may use @here and @everyone in this channel (see _check_mention_spam)."""
    rules = await _get_automod_rules()
    for rule in rules:
        try:
            config = json.loads(rule["config"]) if isinstance(rule["config"], str) else rule["config"]
        except (json.JSONDecodeError, TypeError):
            continue
        triggered = False
        rule_type = rule["type"]
        if rule_type == "word_filter":
            triggered = await _check_word_filter(text, config, user_id=user_id)
        elif rule_type == "link_filter":
            triggered = _check_link_filter(text, config)
        elif rule_type == "caps_filter":
            triggered = _check_caps_filter(text, config)
        elif rule_type == "mention_spam":
            triggered = _check_mention_spam(text, config, mass_allowed)
        if triggered:
            try:
                await db.create_automod_action(
                    rule_id=rule["id"],
                    user_id=user_id,
                    channel_id=channel_id,
                    message_text=text[:500],
                    action_taken=rule["action"]
                )
            except (ValueError, KeyError, TypeError) as e:
                logger.warning(f"Failed to create automod action: {e}")
            await audit_log(
                "automod_trigger", 0, "AutoMod",
                target_id=user_id, target_type="user",
                details=json.dumps({"rule": rule["name"], "action": rule["action"]}),
                channel_id=channel_id, channel_name=channel_name
            )
            return {
                "action": rule["action"],
                "duration": rule.get("action_duration", 300),
                "rule_name": rule["name"],
                "rule_id": rule["id"],
                "created_by": rule.get("created_by")
            }
    return None


async def apply_automod(ws, text: str, *, user_id: int, user_role: str, channel: dict,
                        channel_name: str, username: str, my_state: dict,
                        edit_of: dict | None = None) -> bool:
    """Run automod on text a member is about to post or save, and carry out the action.

    Returns True if the text is blocked; the caller must then not store it. Staff
    (moderator and above) are still blocked but are exempt from the timeout and
    mute penalties. The author is told through ws; nobody else is. edit_of is
    the stored message when the text is an edit of it.
    """
    try:
        # The weight of @here / @everyone applies only where the sender may use them; the
        # permission is looked up only for a text that holds one
        mass_allowed = True
        if _mass_mention_tokens(text):
            mass_allowed = await _may_mass_mention(
                channel, user_id, user_role, await db.get_stream_by_chat_channel(channel["id"]))
        automod_result = await check_automod(text, user_id, channel["id"], channel_name, mass_allowed)
    except automod.RegexCheckError:
        # A regex rule could not be evaluated in time: fail closed. The author is told
        # in neutral words; no penalty is booked and nobody else hears of it.
        await ws.send_json({
            "type": "error",
            "error_code": "automod_unchecked",
            "message": ("Your edit could not be checked; shorten or rephrase it. Your message was not changed"
                        if edit_of is not None else
                        "Your message could not be checked; shorten or rephrase it")
        })
        if edit_of is not None:
            await ws.send_json({
                "type": "edit_rejected",
                "message_id": edit_of["id"],
                "message": edit_of["message"]
            })
        return True
    if not automod_result:
        return False
    am_action = automod_result["action"]
    is_privileged = user_role in ("admin", "superadmin", "moderator")
    rule_name = automod_result["rule_name"]
    alerts.automod_triggered(
        rule_id=automod_result.get("rule_id"), rule_name=rule_name, rule_action=am_action,
        member=username, member_id=user_id, anonymous=bool(my_state.get("anonymous")),
        channel=channel_name, member_role=user_role, private=await _alert_context_private(channel))
    # chat_timeouts.moderator_id must be a real account: the penalty is booked to the
    # account that created the rule (it is announced to the channel as "AutoMod").
    penalty_by = automod_result.get("created_by")
    if am_action in ("timeout", "mute") and not is_privileged and not penalty_by:
        logger.warning(f"[AutoMod] Rule {rule_name!r} has no creator account; {am_action} not applied")
    elif am_action in ("timeout", "mute") and not is_privileged and await db.is_user_timed_out(user_id, channel["id"]):
        # Already timed out or muted (for example by another socket a moment ago):
        # no second penalty row and no second announcement; the author is still told.
        pass
    elif am_action in ("timeout", "mute") and not is_privileged:
        reason = f"AutoMod: {rule_name}"
        display = "Anonymous" if my_state.get("anonymous") else (my_state.get("nickname") or username)
        anon = user_id if my_state.get("anonymous") else None
        try:
            if am_action == "timeout":
                duration = automod_result.get("duration") or 300
                await db.create_chat_timeout(user_id, penalty_by, "timeout", channel["id"], reason, duration)
                await _voice_drop_for_penalty(user_id, channel)
                await broadcast_to_channel(channel_name, {
                    "type": "user_timed_out",
                    "user_id": user_id,
                    "username": display,
                    "duration": duration,
                    "reason": reason,
                    "moderator": "AutoMod"
                }, anon_subject=anon)
            else:
                await db.create_chat_timeout(user_id, penalty_by, "mute", channel["id"], reason)
                await _voice_drop_for_penalty(user_id, channel)
                await broadcast_to_channel(channel_name, {
                    "type": "user_muted",
                    "user_id": user_id,
                    "username": display,
                    "reason": reason,
                    "moderator": "AutoMod"
                }, anon_subject=anon)
        except Exception as e:
            logger.warning(f"[AutoMod] Could not apply {am_action} for rule {rule_name!r}: {e}")
    if edit_of is not None:
        await ws.send_json({
            "type": "error",
            "error_code": "automod",
            "message": f"Edit blocked by auto-moderation ({rule_name}); your message was not changed"
        })
        # The client shows an edit before the server confirms it; give the author the stored text back.
        await ws.send_json({
            "type": "edit_rejected",
            "message_id": edit_of["id"],
            "message": edit_of["message"]
        })
    else:
        await ws.send_json({
            "type": "error",
            "error_code": "automod",
            "message": f"Message blocked by auto-moderation ({rule_name})"
        })
    return True


async def _chat_member_blocked(ws, channel: dict, *, user_id: int, user_role: str,
                               msg_times: list, rate_limit: int, rate_window: float,
                               slowmode: bool = True) -> bool:
    """The checks a member's chat message or edit must pass before anything else runs.

    slowmode=False skips the slow-mode wait (edits: fixing a typo right after
    posting is not a new message; the rate limit still applies).

    Read access (_can_read_channel: a stream chat closed to this member, a stream
    ban, a private channel the member no longer belongs to), timeout or mute, the
    per-socket rate limit and slow mode, in that order; the error reply is sent
    to ws and True is returned when one applies.
    A send and an edit both go through here, and automod runs only after it, so a
    member who is timed out, muted, banned or sending too fast never reaches the
    rules (and never costs them regex work or a new penalty). A passed rate limit
    check counts against msg_times.
    """
    # The same read check as join, history, react and polls: a socket that joined
    # while it could read the channel does not keep sending or editing after that
    # stopped (stream made private, stream ban, removed from a private channel)
    access = await _can_read_channel(channel, user_id, user_role)
    if not access:
        await ws.send_json({"type": "error", "message": access.message})
        return True

    # Check if user is timed out or muted
    timeout_info = await db.is_user_timed_out(user_id, channel["id"])
    if timeout_info:
        if timeout_info["type"] == "mute":
            await ws.send_json({
                "type": "error",
                "error_code": "muted",
                "message": "You are muted in this channel"
            })
        else:
            expires = timeout_info.get("expires_at", "")
            await ws.send_json({
                "type": "error",
                "error_code": "timeout",
                "message": f"You are timed out until {expires}",
                "expires_at": expires
            })
        return True

    # Rate limit: max N messages per window
    now = monotonic()
    msg_times[:] = [t for t in msg_times if now - t < rate_window]
    if len(msg_times) >= rate_limit:
        await ws.send_json({
            "type": "error",
            "message": "Slow down! You're sending messages too fast."
        })
        return True
    msg_times.append(monotonic())

    # Slowmode check (the owner of a stream's chat, its mods and staff bypass)
    slowmode_secs = (channel.get("slowmode_seconds") or 0) if slowmode else 0
    if slowmode_secs > 0 and await chat_mod_level(
            channel, {"id": user_id, "role": user_role}) == CHAT_LEVEL_NONE:
        last_msg_time = _slowmode_last_msg.get((channel["id"], user_id), 0)
        now_sm = monotonic()
        if now_sm - last_msg_time < slowmode_secs:
            remaining = int(slowmode_secs - (now_sm - last_msg_time)) + 1
            await ws.send_json({
                "type": "error",
                "error_code": "slowmode",
                "message": f"Slowmode active. Wait {remaining}s before sending another message.",
                "cooldown_remaining": remaining
            })
            return True
    return False


async def _dm_participant_blocked(user_id: int, conv_id: int) -> bool:
    """True if user_id and another participant of the conversation have blocked each other."""
    for pid in await db.get_dm_participant_ids(conv_id):
        if pid != user_id and await db.is_blocked_bidirectional(user_id, pid):
            return True
    return False


def _format_poll_for_client(poll: dict, user_id: int = None) -> dict:
    """Transform DB poll dict to frontend-friendly format."""
    if not poll:
        return poll
    votes = {}
    my_votes = []
    for opt in poll.get("options_data", []):
        votes[opt["index"]] = opt["count"]
        if user_id and user_id in opt.get("voter_ids", []):
            my_votes.append(opt["index"])
    result = {
        "id": poll["id"],
        "channel_id": poll["channel_id"],
        "message_id": poll.get("message_id"),
        "user_id": poll["user_id"],
        "question": poll["question"],
        "options": poll.get("options_list", []),
        "allow_multiple": poll.get("allow_multiple"),
        "anonymous_votes": poll.get("anonymous_votes"),
        "is_closed": poll.get("is_closed", 0),
        "expires_at": poll.get("expires_at"),
        "total_votes": poll.get("total_votes", 0),
        "votes": votes,
        "my_votes": my_votes,
    }
    return result


async def _anonymous_poll_creator(poll: dict):
    """The poll creator's user id if the poll was posted anonymously, else None."""
    msg_id = poll.get("message_id")
    msg = await db.get_chat_message(msg_id) if msg_id else None
    if msg and msg.get("anonymous"):
        return poll.get("user_id")
    return None


async def _parse_mentions(text: str) -> set[int]:
    """Parse @mentions from message text, return set of mentioned user IDs."""
    pattern = r'@([\w\- ]+?)(?=\s*[@\n]|[.,!?;:\)\]}>]|\s*$)'
    mentioned_names = set(re.findall(pattern, text))
    if not mentioned_names:
        return set()

    mentioned_user_ids = set()
    for name in mentioned_names:
        name = name.strip()
        if not name:
            continue
        if is_reserved_mention_name(name):
            # @here and @everyone are the mass mentions; an account that already carries such
            # a name (made before they were reserved) is not reachable by it
            continue
        user = await db.get_user_by_username(name)
        if user:
            mentioned_user_ids.add(user["id"])
            continue
        user = await db.get_user_by_nickname(name)
        if user:
            mentioned_user_ids.add(user["id"])
    return mentioned_user_ids


# ---------------------------------------------------------------------------
# @here and @everyone
#
# Resolved in _notify_mentions, the one place a posted message's @mentions become notifications.
# The token is looked for in plain text only (fenced and inline code spans are removed first).
# Who may use it: global staff and anyone with chat_mod_level above none in that channel, or
# every member where staff (or the owner of a stream's chat) switched allow_mass_mentions on.
# Elsewhere the text is ordinary text. A sender who is not admin or superadmin gets one mass
# mention per MASS_MENTION_COOLDOWN seconds; the message is posted either way and the sender is
# told through a notice frame. An anonymous sender's mass mention is dropped exactly like an
# anonymous @mention (the caller never gets here). @everyone reaches every member who may read the
# channel (private channel: its members; admins who are not members are not pinged), @here the
# ones with an open chat socket who do not appear offline. A member whose level is none or whose
# timed mute runs gets nothing; level mentions still does. Members in the room are included
# (unlike a direct @mention, a mass mention is meant to be seen). At most MASS_MENTION_CAP members
# are reached per message. When a mass mention is carried out, every row of the message (the
# members it reaches and those named in the text) goes in one transaction, one row per member (a
# member named in the text keeps the personal title); without one, named members are notified as
# before through send_notification.
# ---------------------------------------------------------------------------

MASS_MENTION_RE = re.compile(r'(?<![\w@])@(everyone|here)(?![\w\-])', re.IGNORECASE)
_CODE_SPAN_RE = re.compile(r'```.*?```|`[^`\n]*`', re.DOTALL)
MASS_MENTION_WEIGHT = 5
MASS_MENTION_COOLDOWN = 60.0
MASS_MENTION_CAP = 500
_mass_clock = monotonic                       # injectable in tests
_mass_mention_last: dict[int, float] = {}     # sender id -> when their last effective one was


def _mass_mention_tokens(text: str) -> list[str]:
    """The @here / @everyone tokens in the plain text of a message (lower case)."""
    return [m.lower() for m in MASS_MENTION_RE.findall(_CODE_SPAN_RE.sub(" ", text or ""))]


def _mass_mention_kind(text: str) -> Optional[str]:
    """"everyone", "here" (when only that is present) or None."""
    found = _mass_mention_tokens(text)
    if "everyone" in found:
        return "everyone"
    return "here" if found else None


def _mass_mention_wait(user_id: int, role: str) -> int:
    """0 and the slot is taken, or the seconds until the sender may try again. Checked and set with
    no await in between, so two sockets of one sender cannot both pass. Admins are not limited."""
    if role in ("admin", "superadmin"):
        return 0
    now = _mass_clock()
    last = _mass_mention_last.get(user_id)
    if last is not None and now - last < MASS_MENTION_COOLDOWN:
        return int(MASS_MENTION_COOLDOWN - (now - last)) + 1
    if len(_mass_mention_last) > 1000:
        for k in [k for k, v in _mass_mention_last.items() if now - v >= MASS_MENTION_COOLDOWN]:
            _mass_mention_last.pop(k, None)
    _mass_mention_last[user_id] = now
    return 0


async def _may_mass_mention(channel, user_id: int, role: str, stream) -> bool:
    if channel.get("allow_mass_mentions"):
        return True
    return await chat_mod_level(channel, {"id": user_id, "role": role}, stream) != CHAT_LEVEL_NONE


async def _mass_mention_recipients(channel, kind: str, sender_id: int, stream) -> tuple[list, bool]:
    """([user ids], capped) for an @everyone or @here in this channel, in id order."""
    private = channel.get("visibility", "public") == "private"
    candidates = await db.get_mass_mention_candidates(channel["id"], private)
    online = {uid for uid, _ in _chat_sockets.values()} if kind == "here" else None
    pool = []
    for c in candidates:
        uid = c["id"]
        if uid == sender_id or (online is not None and uid not in online):
            continue
        if kind == "here" and (c.get("status") == "offline" or c.get("status_preference") == "offline"):
            continue
        pool.append(c)
    prefs = await db.get_channel_notify_prefs(channel["id"], [c["id"] for c in pool])
    now = _notify_clock()
    out, capped = [], False
    for c in pool:
        level, muted_until = prefs.get(c["id"], ("default", 0))
        if level == "none" or (muted_until and muted_until > now):
            continue
        if not await _can_read_channel(channel, c["id"], c["role"], stream):
            continue
        if len(out) >= MASS_MENTION_CAP:
            capped = True
            break
        out.append(c["id"])
    return out, capped


async def _notify_mentions(ws, channel, user_id: int, user_role: str, display_name: str,
                           text: str, msg_id: int) -> None:
    """Notify the members a posted (non-anonymous) message mentions: by name, and by @here or
    @everyone where the sender may. Never raises."""
    try:
        direct: dict[int, tuple] = {}     # named in the text
        rows: dict[int, tuple] = {}       # reached by @here / @everyone (named members join them)
        mass_done = False
        data = {"channel": channel["name"], "channel_id": channel["id"], "message_id": msg_id}
        mentioned_ids = await _parse_mentions(text)
        if mentioned_ids:
            channel_viewer_ids = {entry[1] for entry in chat_rooms.get(channel["name"], ())}
            for mid in mentioned_ids:
                if mid == user_id or mid in channel_viewer_ids:
                    continue
                # Don't notify members who cannot read the channel
                m_user = await db.get_user_by_id(mid)
                if not m_user:
                    continue
                m_role = m_user.get("role") or ("superadmin" if m_user.get("is_admin") else "user")
                if not await _can_read_channel(channel, mid, m_role):
                    continue
                # level none turns mentions off too; a mute or level mentions does not
                if (await _notify_prefs_for(mid)).get(channel["id"], ("default", 0))[0] == "none":
                    continue
                direct[mid] = (mid, "mention", f"{display_name} mentioned you in #{channel['name']}", None, dict(data))
        kind = _mass_mention_kind(text)
        if kind:
            stream = await db.get_stream_by_chat_channel(channel["id"])
            if await _may_mass_mention(channel, user_id, user_role, stream):
                wait = _mass_mention_wait(user_id, user_role)
                if wait:
                    # A closed sender socket must not drop the notifications of the names in the text
                    try:
                        await ws.send_json({
                            "type": "notice", "code": "mass_mention_limited", "retry_after": wait,
                            "message": f"Your message was posted without @{kind}: "
                                       f"one @here or @everyone per {int(MASS_MENTION_COOLDOWN)} seconds"})
                    except Exception as e:
                        logger.debug(f"Mass mention notice not delivered: {e}")
                else:
                    mass_done = True
                    ids, capped = await _mass_mention_recipients(channel, kind, user_id, stream)
                    label = "everyone" if kind == "everyone" else "everyone online"
                    for mid in ids:
                        row = direct.get(mid)
                        if row:      # also mentioned by name: one row, the personal one
                            row[4]["mass"] = kind
                        else:
                            rows[mid] = (mid, "mention",
                                         f"{display_name} mentioned {label} in #{channel['name']}",
                                         None, {**data, "mass": kind})
                    if capped:
                        try:
                            await ws.send_json({
                                "type": "notice", "code": "mass_mention_capped",
                                "message": f"@{kind} reached the first {MASS_MENTION_CAP} members"})
                        except Exception as e:
                            logger.debug(f"Mass mention notice not delivered: {e}")
        # Who may be pushed: named members, and the members an @everyone reached (never @here)
        push_direct = set(direct)
        push_everyone = set(rows) if (mass_done and kind == "everyone") else set()
        if mass_done:
            # one transaction for everybody this message notifies; a member named in the text
            # keeps the personal title and is in it once
            rows = {**direct, **rows}
        else:
            for row in direct.values():
                await send_notification(row[0], row[1], row[2], row[3], row[4])
        if rows:
            made = await db.create_notifications_bulk(list(rows.values()))
            for (uid, nid), row in zip(made, rows.values()):
                try:
                    await _push_notification_frame(uid, nid, row[1], row[2], row[3] or "", row[4])
                except Exception as e:
                    logger.debug(f"Mention push failed: {e}")
        if push_direct or push_everyone:
            _schedule_push(_push_mentions(channel, msg_id, sorted(push_direct), sorted(push_everyone)))
    except Exception as e:
        logger.error(f"Mention notification error: {e}")


async def http_chat_users(request: web.Request) -> web.Response:
    """List users for DM search (any authenticated user, returns basic info only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    query = request.query.get("q", "").strip().lower()
    users = await db.get_all_users()
    results = []
    for u in users:
        if u["id"] == token.user_id:
            continue
        uname = (u.get("username") or "").lower()
        nname = (u.get("nickname") or "").lower()
        if query and query not in uname and query not in nname:
            continue
        results.append({
            "id": u["id"],
            "username": u["username"],
            "nickname": u.get("nickname"),
        })
        if len(results) >= 20:
            break
    return web.json_response({"users": results})


async def http_get_chat_channels(request: web.Request) -> web.Response:
    """Get all chat channels (filtered by user access)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or ("superadmin" if user.get("is_admin") else "user")) if user else "user"
    channels = []
    # Enrich with stream association data
    for ch in await db.get_accessible_channels(token.user_id, user_role):
        stream = await db.get_stream_by_chat_channel(ch["id"])
        # The chat of a stream that is not public is closed to everyone but its
        # owner and admins (join and history answer "Channel not found"): it is
        # not listed either, with its stream, live state and owner
        if _stream_chat_hidden(stream, token.user_id, user_role):
            continue
        channels.append(ch)
        ch["is_stream_channel"] = bool(stream)
        if stream:
            ch["stream_id"] = stream["id"]
            ch["stream_is_live"] = stream.get("is_live", 0)
            # A private stream's playback key is shown to its owner only
            if stream.get("is_public") or stream.get("user_id") == token.user_id:
                ch["stream_public_key"] = stream.get("public_key", "")
            else:
                ch["stream_public_key"] = ""
            ch["stream_owner"] = stream.get("owner_nickname") or stream.get("owner_username", "")
    # Enrich with unread counts
    unread_counts = await db.get_unread_counts(token.user_id)
    notify_prefs = await _notify_prefs_for(token.user_id)
    next_cleanup = (datetime.fromtimestamp(_cleanup_next_at, timezone.utc).isoformat()
                    if _cleanup_next_at else None)
    for ch in channels:
        ch["unread_count"] = unread_counts.get(ch["id"], 0)
        ch.update(_notify_pref_public(notify_prefs.get(ch["id"])))
        # when the channel's own retention applies (a stream's chat follows the global setting)
        # the next periodic cleanup is stated next to it
        stream_bound = bool(ch.get("is_stream_channel")) and not ch.get("is_default")
        for field in ("retention_days", "file_retention_days"):
            ch[field] = _own_retention_value(ch.get(field))
        if ch.get("retention_days") is not None and not stream_bound:
            ch["retention_next_cleanup"] = next_cleanup
        elif stream_bound:
            ch["retention_days"] = None
    return web.json_response({"channels": channels})


async def http_create_chat_channel(request: web.Request) -> web.Response:
    """Create a new chat channel."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    name = data.get("name", "").strip().lower()
    description = data.get("description", "").strip()
    category = data.get("category", "").strip() or None

    if not name:
        return web.json_response({"error": "Channel name is required"}, status=400)

    # Validate channel name
    if not re.match(r'^[a-z0-9-]+$', name):
        return web.json_response({
            "error": "Channel name must be lowercase letters, numbers, and hyphens only"
        }, status=400)

    if len(name) > 32:
        return web.json_response({"error": "Channel name too long (max 32 chars)"}, status=400)

    if category and len(category) > 32:
        return web.json_response({"error": "Category name too long (max 32 chars)"}, status=400)

    visibility = data.get("visibility", "public").strip()
    mode = data.get("mode", "open").strip()
    if visibility not in ("public", "private"):
        return web.json_response({"error": "Visibility must be 'public' or 'private'"}, status=400)
    if mode not in ("open", "readonly"):
        return web.json_response({"error": "Mode must be 'open' or 'readonly'"}, status=400)

    # Only moderator+ can create private/readonly channels
    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or ("superadmin" if user.get("is_admin") else "user")) if user else "user"
    if (visibility == "private" or mode == "readonly") and user_role not in ("admin", "superadmin", "moderator"):
        return web.json_response({"error": "Moderator access required for private/readonly channels"}, status=403)

    # Check if exists
    existing = await db.get_chat_channel_by_name(name)
    if existing:
        return web.json_response({"error": "Channel already exists"}, status=409)

    channel_id = await db.create_chat_channel(name, description, token.user_id, category=category)

    # Set visibility/mode if non-default
    if visibility != "public" or mode != "open":
        await db.update_chat_channel(channel_id, visibility=visibility, mode=mode)

    # Auto-add creator as channel moderator for private channels
    if visibility == "private":
        await db.add_channel_member(channel_id, token.user_id, role="moderator", added_by=token.user_id)

    await audit_log("channel_create", token.user_id, user["username"] if user else "unknown",
                    target_id=channel_id, target_type="channel", target_name=name,
                    details=json.dumps({"visibility": visibility, "mode": mode}))

    return web.json_response({
        "id": channel_id,
        "name": name,
        "description": description,
        "category": category,
        "visibility": visibility,
        "mode": mode
    }, status=201)


async def http_update_chat_channel(request: web.Request) -> web.Response:
    """Update a chat channel (moderator+ or channel-moderator, cannot modify defaults or stream channels)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Require moderator+ role or channel moderator
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)
    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    is_mod = role in ("admin", "superadmin", "moderator")
    if not is_mod:
        # Check if user is channel moderator
        try:
            chan_id = int(request.match_info["id"])
        except (ValueError, TypeError):
            return web.json_response({"error": "Invalid channel ID"}, status=400)
        ch_role = await db.get_channel_member_role(chan_id, token.user_id)
        if ch_role != "moderator":
            return web.json_response({"error": "Moderator access required"}, status=403)

    try:
        channel_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)

    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    if channel.get("is_default"):
        return web.json_response({"error": "Cannot modify default channels"}, status=400)

    stream = await db.get_stream_by_chat_channel(channel_id)
    if stream:
        return web.json_response({"error": "Cannot modify stream-associated channels"}, status=400)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    # Prevent changing visibility on default or stream channels
    if "visibility" in data and channel.get("is_default"):
        return web.json_response({"error": "Cannot change visibility of default channels"}, status=400)
    if "visibility" in data and data["visibility"] not in ("public", "private"):
        return web.json_response({"error": "Visibility must be 'public' or 'private'"}, status=400)
    if "mode" in data and data["mode"] not in ("open", "readonly"):
        return web.json_response({"error": "Mode must be 'open' or 'readonly'"}, status=400)

    old_name = channel["name"]
    success = await db.update_chat_channel(channel_id, **data)
    _forget_activity_verdicts(channel_id)       # visibility may have widened
    if not success:
        return web.json_response({"error": "No updates applied"}, status=400)

    await audit_log("channel_update", token.user_id, user["username"],
                    target_id=channel_id, target_type="channel", target_name=old_name,
                    details=json.dumps({k: v for k, v in data.items() if k in ("name", "description", "category", "slowmode_seconds", "visibility", "mode")}))

    # If name was changed, broadcast rename and move chat_rooms entry
    new_name = data.get("name")
    if new_name and new_name != old_name:
        if old_name in chat_rooms:
            await broadcast_to_channel(old_name, {
                "type": "channel_renamed",
                "old_name": old_name,
                "new_name": new_name
            })
            chat_rooms[new_name] = chat_rooms.pop(old_name)

    # A channel that was just made private: members of its voice call who are
    # not allowed in a private channel leave the call now, not at their next
    # reconnect.
    if data.get("visibility") == "private":
        # The sockets of members who do not belong to it leave the text room (and its
        # call) first, so they are not sent the call's last updates
        await _evict_unreadable_by_id(channel_id)
        for voice_user_id in list((voice_state.get(new_name or old_name) or {}).keys()):
            await _voice_eject_if_not_allowed(voice_user_id)

    return web.json_response({"success": True})


async def http_delete_chat_channel(request: web.Request) -> web.Response:
    """Delete a chat channel (admin only, cannot delete defaults or stream channels)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    if not token.has_scope("admin") and not token.has_scope("*"):
        return web.json_response({"error": "Admin access required"}, status=403)

    try:
        channel_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)

    # Look up channel before deleting (need name for cleanup)
    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    if channel.get("is_default"):
        return web.json_response({"error": "Cannot delete default channels"}, status=400)

    stream = await db.get_stream_by_chat_channel(channel_id)
    if stream:
        return web.json_response({"error": "Cannot delete stream-associated channels"}, status=400)

    success = await db.delete_chat_channel(channel_id)
    if not success:
        return web.json_response({"error": "Failed to delete channel"}, status=500)

    await audit_log("channel_delete", token.user_id, "admin",
                    target_id=channel_id, target_type="channel", target_name=channel["name"])

    # Notify connected users and clean up
    channel_name = channel["name"]
    if channel_name in chat_rooms:
        await broadcast_to_channel(channel_name, {
            "type": "channel_deleted",
            "channel": channel_name
        })
        del chat_rooms[channel_name]

    return web.json_response({"success": True})


async def http_clear_chat_channel(request: web.Request) -> web.Response:
    """Clear all messages in a chat channel (superadmin only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Only superadmins can clear channel history
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return web.json_response({"error": "User not found"}, status=404)

    role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    if role != "superadmin":
        return web.json_response({"error": "Super admin access required"}, status=403)

    try:
        channel_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)

    # Get channel info for broadcasting
    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    # Clear all messages
    clear_stats = {}
    deleted_count = await db.clear_channel_messages(channel_id, stats=clear_stats)
    if clear_stats.get("files"):
        logger.info(f"Cleared channel {channel_id}: removed {clear_stats['files']} upload file(s), {clear_stats['bytes']} bytes")

    # Broadcast to channel that history was cleared
    channel_name = channel["name"]
    if channel_name in chat_rooms:
        await broadcast_to_channel(channel_name, {
            "type": "channel_cleared",
            "channel": channel_name,
            "cleared_by": user["username"],
            "message_count": deleted_count
        })

    await audit_log("channel_clear", token.user_id, user["username"],
                    target_id=channel_id, target_type="channel", target_name=channel_name,
                    details=json.dumps({"deleted_count": deleted_count}))

    result = {
        "success": True,
        "deleted_count": deleted_count
    }
    if clear_stats.get("skipped"):
        # The messages are gone but their upload files were not looked at.
        result["chat_files_skipped"] = clear_stats["skipped"]
    return web.json_response(result)


# ---------------------------------------------------------------------------
# Per-channel retention and the manual prune
#
# Only administrators set a channel's retention (PUT /api/chat/channels/{id}/retention); no chat
# socket action sets it (REST only) and the generic channel PUT ignores both fields. The periodic cleanup (_run_chat_retention) works per
# channel through database._purge_messages. The manual prune is a background task per channel.
# ---------------------------------------------------------------------------

_cleanup_next_at = 0.0               # epoch seconds of the next periodic cleanup (0 = not known yet)
_RETENTION_FOREVER = ("forever", "never")
_prune_tasks: dict = {}              # channel id -> running prune task (strong reference)
_prune_status: dict = {}             # channel id -> {"running", "removed", "total", "status"} of the last prune
PRUNE_BATCH = 200                    # messages per batch; the loop yields to the event loop after each


def _chat_retention_cap(config: dict) -> int:
    """The ceiling of a channel's own retention (setting retention_chat_max_days, 1..3650)."""
    try:
        cap = int(config.get("retention_chat_max_days", 3650))
    except (TypeError, ValueError):
        cap = 3650
    return max(1, min(cap, 3650))


_PRUNE_COUNT_MAX = 10 ** 9      # a count above this is not a count of messages: 400, not a comparison


def _prune_margin(shown: int) -> int:
    """How far the live count of a prune may be from the count the dry run showed: 2 messages
    or 2 percent of the shown count, whichever is larger (messages arrive and go while the dialog
    is open). The one rule: the margin is always taken from the count the dry run showed, which is
    the live count of the dry run and the expected_count a real run sends back."""
    return max(2, int(shown) // 50)


def _prune_count_changed(live: int, expected: int) -> bool:
    """Whether the live count is further from the shown (expected) count than its margin."""
    return abs(int(live) - int(expected)) > _prune_margin(expected)


def _own_retention_value(value):
    """A channel's stored retention (message or file) as a positive number of days, or None when it is
    unset or 0 or less. Only a manual edit of the database can store 0 or less; it is treated as "no own
    value" (the channel follows the global setting), never as one day."""
    try:
        days = int(value)
    except (TypeError, ValueError):
        return None
    return days if days > 0 else None


def _chat_message_retention_days(channel: dict, config: dict):
    """Days after which the next cleanup removes this channel's messages: its own value as stored (the
    cap setting limits a value when it is set, never afterwards: lowering the cap shortens nothing that
    is already stored), else the global chat retention, else None (kept)."""
    own = _own_retention_value(channel.get("retention_days"))
    if own is not None:
        return own
    try:
        glob = int(config.get("retention_chat_days", 7))
    except (TypeError, ValueError):
        glob = 7
    return glob if glob > 0 else None


async def _pending_upload_names() -> set:
    """Upload files of messages a stopped, cancelled or killed prune or cleanup had already deleted
    (chat_upload_pending); an empty set when they cannot be read."""
    try:
        return await db.pending_upload_names()
    except Exception as e:
        logger.error(f"[Retention] Pending chat upload list failed: {e}")
        return set()


async def _run_chat_retention(config: dict, stats: dict) -> int:
    """The chat part of the periodic cleanup (and of 'run cleanup now'): the global retention for
    every channel without a value of its own, then each channel's own retention_days, then each
    channel's file_retention_days. The upload files are removed once at the end. Returns the number
    of messages deleted; a failing step is logged and the others still run."""
    names: set = await _pending_upload_names()        # deletions of a stopped or killed prune or cleanup
    total = 0
    try:
        chat_days = int(config.get("retention_chat_days", 7))
        if chat_days > 0:
            d = await db.cleanup_old_chat_messages(days=chat_days, stats=stats, names=names)
            if d > 0:
                logger.info(f"[Retention] Cleaned {d} chat messages older than {chat_days} days")
            total += d
    except Exception as e:
        logger.error(f"[Retention] Chat cleanup failed: {e}")
    try:
        channels = await db.get_channels_with_own_retention()
    except Exception as e:
        logger.error(f"[Retention] Channel retention list failed: {e}")
        channels = []
    for ch in channels:
        try:
            days = _own_retention_value(ch["retention_days"])      # as stored: a lowered cap shortens nothing
            if days is None:
                continue
            d = await db.cleanup_channel_messages(ch["id"], days, stats, names=names)
            if d > 0:
                logger.info(f"[Retention] Cleaned {d} messages older than {days} days in channel {ch['id']}")
            total += d
        except Exception as e:
            logger.error(f"[Retention] Cleanup of channel {ch.get('id')} failed: {e}")
    try:
        file_channels = await db.get_channels_with_file_retention()
    except Exception as e:
        logger.error(f"[Retention] Channel file retention list failed: {e}")
        file_channels = []
    for ch in file_channels:
        try:
            limit = _chat_message_retention_days(ch, config)
            days = _own_retention_value(ch["file_retention_days"])
            if days is None:
                continue
            if limit:
                days = min(days, limit)
            n = await db.remove_channel_files(ch["id"], days, stats, names)
            if n > 0:
                logger.info(f"[Retention] Removed the files of {n} messages older than {days} days in channel {ch['id']}")
        except Exception as e:
            logger.error(f"[Retention] File cleanup of channel {ch.get('id')} failed: {e}")
    try:
        await db.finish_purge_files(names, stats)
    except Exception as e:
        logger.error(f"[Retention] Chat upload removal failed: {e}")
    return total


def _parse_retention_value(raw, cap: int):
    """One retention field of the request: ("clear", None) for null, ("forever", cap) for 0 or
    "forever", ("days", n) for a positive whole number (capped), or raises ValueError."""
    if raw is None:
        return "clear", None
    if isinstance(raw, bool):
        raise ValueError("a number of days, 0, \"forever\" or null")
    if isinstance(raw, str):
        text = raw.strip().lower()
        if text in _RETENTION_FOREVER:
            return "forever", cap
        if not text.isdigit() or len(text) > 9:
            raise ValueError("a number of days, 0, \"forever\" or null")
        raw = int(text)
    if isinstance(raw, float):
        # JSON Infinity, -Infinity and NaN parse to floats; int() of them raises, so refuse them first
        if not math.isfinite(raw) or raw != int(raw):
            raise ValueError("a number of days, 0, \"forever\" or null")
        raw = int(raw)
    if not isinstance(raw, int) or raw < 0 or raw > 10 ** 9:
        raise ValueError("a number of days, 0, \"forever\" or null")
    if raw == 0:
        return "forever", cap
    return "days", min(raw, cap)


async def http_set_channel_retention(request: web.Request) -> web.Response:
    """Set the retention of one channel (administrators only).

    Body: retention_days and/or file_retention_days: a number of days, 0 or "forever" (stored as the
    global cap retention_chat_max_days), or null (follow the global setting); a field left out is kept.
    file_retention_days removes only the uploaded files of older messages and never exceeds the
    message retention. A change that makes the removal sooner is not applied without "confirm": true;
    the answer without it ({"applied": false, "confirm_required": true}) carries the number of
    messages and of files the next cleanup would remove. "dry_run": true only looks."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)
    if not has_full_user_scope(token):
        return full_scope_required_response()
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return unauthorized_response(request)
    if _user_role_of(user) not in ("admin", "superadmin"):
        return web.json_response({"error": "Administrator access required"}, status=403)
    try:
        channel_id = _row_id(request.match_info.get("id"))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)
    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)
    stream = await db.get_stream_by_chat_channel(channel_id)
    if stream and not channel.get("is_default"):
        return web.json_response({"error": "A stream's chat keeps the global retention"}, status=400)
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict) or not ({"retention_days", "file_retention_days"} & set(data)):
        return web.json_response({"error": "retention_days or file_retention_days required"}, status=400)
    for flag in ("confirm", "dry_run"):
        if flag in data and not isinstance(data[flag], bool):
            return web.json_response({"error": f"{flag} must be true or false"}, status=400)

    config = await db.get_retention_config()
    cap = _chat_retention_cap(config)
    old = {"retention_days": _own_retention_value(channel.get("retention_days")),
           "file_retention_days": _own_retention_value(channel.get("file_retention_days"))}
    new = dict(old)
    capped = False
    forever_file = False
    try:
        if "retention_days" in data:
            kind, value = _parse_retention_value(data["retention_days"], cap)
            capped = capped or (kind == "days" and isinstance(data["retention_days"], (int, str))
                                and str(data["retention_days"]).strip().isdigit() and int(data["retention_days"]) > cap)
            new["retention_days"] = value
        if "file_retention_days" in data:
            kind, value = _parse_retention_value(data["file_retention_days"], cap)
            forever_file = kind == "forever"
            new["file_retention_days"] = value
    except ValueError as e:
        return web.json_response({"error": f"Invalid value: expected {e}"}, status=400)

    limit = _chat_message_retention_days({"retention_days": new["retention_days"]}, config) or cap
    if new["file_retention_days"] is not None:
        if forever_file:
            new["file_retention_days"] = limit        # keep files as long as the messages
        elif new["file_retention_days"] > limit:
            if "file_retention_days" in data:
                return web.json_response(
                    {"error": f"file_retention_days cannot exceed the message retention ({limit} days)"},
                    status=400)
            new["file_retention_days"] = limit       # the message retention was shortened under it

    def eff_msg(values):
        return _chat_message_retention_days({"retention_days": values["retention_days"]}, config)

    def eff_file(values):
        f = values["file_retention_days"]
        if f is None:
            return None
        m = eff_msg(values)
        return min(f, m) if m else f

    inf = float("inf")
    old_m, new_m = eff_msg(old) or inf, eff_msg(new) or inf
    old_f, new_f = eff_file(old) or inf, eff_file(new) or inf
    msg_shorter, file_shorter = new_m < old_m, new_f < old_f
    report = {"old": old, "new": new, "capped": capped, "cap_days": cap}
    if msg_shorter:
        report["would_remove_messages"] = await db.count_channel_expiring(channel_id, int(new_m))
    if file_shorter:
        report["would_remove_files"] = await db.count_channel_files_expiring(channel_id, int(new_f))
    shortening = msg_shorter or file_shorter
    if data.get("dry_run") or (shortening and not data.get("confirm")):
        report.update({"applied": False, "confirm_required": shortening, "dry_run": True})
        return web.json_response(report)
    if new != old:
        if not await db.set_channel_retention(channel_id, new["retention_days"], new["file_retention_days"]):
            return web.json_response({"error": "Channel not found"}, status=404)
        await audit_log("channel_retention_change", token.user_id, user["username"],
                        target_id=channel_id, target_type="channel", target_name=channel["name"],
                        channel_id=channel_id, channel_name=channel["name"],
                        details=json.dumps({"old": old, "new": new, "cap_days": cap,
                                            "confirmed": bool(data.get("confirm")),
                                            "would_remove_messages": report.get("would_remove_messages"),
                                            "would_remove_files": report.get("would_remove_files")}))
    report.update({"applied": True, "confirm_required": False, "dry_run": False,
                   "retention_days": new["retention_days"], "file_retention_days": new["file_retention_days"]})
    if new["retention_days"] is not None and _cleanup_next_at:
        report["next_cleanup_at"] = datetime.fromtimestamp(_cleanup_next_at, timezone.utc).isoformat()
    return web.json_response(report)


PRUNE_SHUTDOWN_WAIT = 20.0      # seconds a shutdown waits for the cancelled prunes to write their entry


def _ask_prunes_to_stop() -> dict:
    """Ask every running prune to end at its next batch boundary; the tasks that are running."""
    tasks = {cid: t for cid, t in list(_prune_tasks.items()) if not t.done()}
    for cid in tasks:
        if cid in _prune_status:
            _prune_status[cid]["_stop"] = True
    return tasks


async def _cancel_prune_tasks() -> None:
    """Shutdown: stop the running prunes and wait for them (at most PRUNE_SHUTDOWN_WAIT seconds)
    while the database is still open, so each writes its one 'interrupted' audit entry (see _run_prune).
    A prune is asked to stop and ends at its next batch boundary, never inside a batch (a cancel inside
    one leaves the shared connection with an uncommitted half batch); only one that has not stopped
    within the bound is cancelled. The upload files of its committed batches are not removed then: their
    names are in chat_upload_pending and go at the next start or cleanup. Never raises."""
    tasks = _ask_prunes_to_stop()
    if not tasks:
        return
    _, pending = await asyncio.wait(tasks.values(), timeout=PRUNE_SHUTDOWN_WAIT)
    if pending:
        for task in pending:
            task.cancel()
        logger.warning(f"[Prune] {len(pending)} prune(s) did not stop within {PRUNE_SHUTDOWN_WAIT:.0f}s, cancelled")
        await asyncio.wait(pending, timeout=PRUNE_SHUTDOWN_WAIT)


async def _prune_gate(request: web.Request):
    """(token, user, role, channel, stream, level) of a prune request, or (response,)*: the
    reader check first (an unreadable channel answers exactly like a missing one), then the
    moderator level of chat_mod_level; a member without any answers the same 404."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request), None, None, None, None, None
    if not has_full_user_scope(token):
        return full_scope_required_response(), None, None, None, None, None
    user = await db.get_user_by_id(token.user_id)
    if not user:
        return unauthorized_response(request), None, None, None, None, None
    role = _user_role_of(user)
    missing = web.json_response({"error": "Channel not found"}, status=404)
    try:
        channel_id = _row_id(request.match_info.get("id"))
    except (ValueError, TypeError):
        return missing, None, None, None, None, None
    channel = await db.get_chat_channel(channel_id)
    stream = await db.get_stream_by_chat_channel(channel_id) if channel else None
    if not await _can_read_channel(channel, token.user_id, role, stream):
        return missing, None, None, None, None, None
    level = await chat_mod_level(channel, {"id": token.user_id, "role": role}, stream)
    if level == CHAT_LEVEL_NONE:
        return missing, None, None, None, None, None
    return None, token, user, role, (channel, stream), level


async def _prune_protected(channel, stream, actor_id: int, actor_role: str, level: int) -> tuple[list, bool]:
    """(author ids a prune must leave alone, whether posts without an author may go): the rank
    rules of a single message delete (_chat_may_act_on), taken from where rank comes from (global
    staff, the stream's owner, its stream mods) so a new poster cannot slip through. Everyone may
    prune their own posts; a post with no author (a system post) goes only for the owner and staff."""
    ranked: dict = {}
    for u in await db.list_chat_staff_candidates():
        role = _user_role_of(u)
        if role in _CHAT_STAFF_ROLES:
            ranked[u["id"]] = (CHAT_LEVEL_STAFF, role)
    if _real_stream_chat(stream):
        if stream.get("user_id") is not None:
            ranked.setdefault(stream["user_id"], (CHAT_LEVEL_OWNER, "user"))
        for mod_id in await db.get_channel_moderator_ids(channel["id"]):
            ranked.setdefault(mod_id, (CHAT_LEVEL_MOD, "user"))
    excluded = sorted(uid for uid, (rank, role) in ranked.items()
                      if uid != actor_id and not _chat_may_act_on(level, actor_role, rank, role))
    return excluded, level in (CHAT_LEVEL_OWNER, CHAT_LEVEL_STAFF)


def _parse_prune_time(raw, field: str) -> str:
    """An ISO 8601 date-time (no offset = UTC) as the UTC isoformat string the messages are stored
    with, so the range compares as text."""
    if not isinstance(raw, str) or not raw.strip():
        raise ValueError(f"{field} (an ISO 8601 date and time) is required")
    try:
        dt = datetime.fromisoformat(raw.strip())
    except ValueError:
        raise ValueError(f"{field} is not an ISO 8601 date and time")
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        return dt.astimezone(timezone.utc).isoformat()
    except (OverflowError, ValueError):
        raise ValueError(f"{field} is out of range")


async def http_get_prune_status(request: web.Request) -> web.Response:
    """State of the last manual prune in a channel (same gate as the prune itself)."""
    refusal, token, user, role, ctx, level = await _prune_gate(request)
    if refusal is not None:
        return refusal
    channel = ctx[0]
    st = _prune_status.get(channel["id"])
    if not st:
        return web.json_response({"running": False, "status": "none"})
    out = {k: v for k, v in st.items() if not k.startswith("_")}
    return web.json_response(out)


async def http_prune_chat_channel(request: web.Request) -> web.Response:
    """Prune the messages of one channel inside a date range (administrators, and the moderators of
    that chat per chat_mod_level; anyone else, and anyone who may not read the channel, gets the
    404 of a missing channel).

    Body: from, to (ISO 8601, both required, both ends inclusive), user (optional: an account id or a
    name), skip_pinned (default true), dry_run, expected_count. A dry run answers {"count": n}. A real
    run must echo that count as expected_count: it is refused with 409 when the live count differs by
    more than max(2, 2 percent of it). It then runs as a background task (202) in batches of
    PRUNE_BATCH, broadcasts one messages_pruned frame (ids only) per batch to the room and writes one
    audit entry at the end. One prune per channel at a time (409). A user filter never matches an
    anonymous message, for anybody (the history afterwards would show whose they were); an
    administrator removes those one at a time. The caller prunes only
    what a single delete would let them delete (_prune_protected): a stream mod ordinary members, the
    owner everybody but staff, staff everybody of a lower role; their own posts always. That rank rule
    covers named posts only: for every caller but an administrator an anonymous post is rankless, and
    an administrator's prune with no user filter leaves anonymous posts alone when any author is
    excluded, so no count, frame or entry depends on who wrote one."""
    refusal, token, user, role, ctx, level = await _prune_gate(request)
    if refusal is not None:
        return refusal
    channel, stream = ctx
    try:
        data = await request.json()
    except (json.JSONDecodeError, ValueError):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    if not isinstance(data, dict):
        return web.json_response({"error": "Invalid JSON"}, status=400)
    try:
        start = _parse_prune_time(data.get("from"), "from")
        end = _parse_prune_time(data.get("to"), "to")
    except ValueError as e:
        return web.json_response({"error": str(e)}, status=400)
    if start > end:
        return web.json_response({"error": "from must not be after to"}, status=400)
    # The range never reaches past the moment of the request: a later "to" would take in every message
    # posted while the batches run, which no dry run counted
    end = min(end, datetime.now(timezone.utc).isoformat())
    skip_pinned = data.get("skip_pinned", True)
    dry_run = data.get("dry_run", False)
    if not isinstance(skip_pinned, bool) or not isinstance(dry_run, bool):
        return web.json_response({"error": "skip_pinned and dry_run must be true or false"}, status=400)

    # The user filter: an account id or a name; one that matches no account matches nothing
    user_id = None
    user_label = None
    raw_user = data.get("user", data.get("user_id"))
    if raw_user is not None and raw_user != "":
        target = None
        if isinstance(raw_user, int) and not isinstance(raw_user, bool):
            if abs(raw_user) > _SQLITE_INT_MAX:
                return web.json_response({"error": "user must be an account id or a name"}, status=400)
            target = await db.get_user_by_id(raw_user)
        elif isinstance(raw_user, str) and len(raw_user) <= 64:
            target = (await db.get_user_by_id(int(raw_user)) if raw_user.strip().isdigit()
                      and len(raw_user.strip()) < 15 else None) or await db.get_user_by_username(raw_user.strip())
        else:
            return web.json_response({"error": "user must be an account id or a name"}, status=400)
        user_id = target["id"] if target else -1
        user_label = target["username"] if target else None
    may_name_anonymous = role in ("admin", "superadmin")
    excluded, authorless_ok = await _prune_protected(channel, stream, token.user_id, role, level)
    where, params = db.prune_where(channel["id"], start, end, user_id, skip_pinned, may_name_anonymous,
                                   excluded, authorless_ok, anonymous_rankless=not may_name_anonymous)
    live = await db.count_where_chat_messages(where, params)
    margin = _prune_margin(live)        # of the count shown, which a real run sends back as expected_count
    if dry_run:
        return web.json_response({"dry_run": True, "count": live, "margin": margin,
                                  "skip_pinned": skip_pinned})

    running = _prune_tasks.get(channel["id"])
    if running is not None and not running.done():
        return web.json_response({"error": "A prune is already running in this channel"}, status=409)
    expected = data.get("expected_count")
    if isinstance(expected, bool) or not isinstance(expected, int) or expected < 0 or expected > _PRUNE_COUNT_MAX:
        return web.json_response({"error": "expected_count (the count of the dry run) is required"}, status=400)
    if _prune_count_changed(live, expected):
        return web.json_response({"error": "The number of messages changed since the dry run; run it again",
                                  "count": live, "expected_count": expected,
                                  "margin": _prune_margin(expected)}, status=409)
    state = {"running": True, "removed": 0, "total": live, "status": "running", "_actor_id": token.user_id}
    _prune_status[channel["id"]] = state
    task = asyncio.create_task(_run_prune(
        channel["id"], token.user_id, user["username"], level, where, params, state, {
            "from": start, "to": end, "user_id": None if user_id is None else (user_id if user_id > 0 else None),
            "user": user_label, "skip_pinned": skip_pinned, "expected_count": expected}))
    _prune_tasks[channel["id"]] = task
    task.add_done_callback(lambda t, cid=channel["id"]: _prune_tasks.pop(cid, None) if _prune_tasks.get(cid) is t else None)
    return web.json_response({"started": True, "count": live}, status=202)


async def _run_prune(channel_id: int, actor_id: int, actor_name: str, level: int, where: str, params: tuple,
                     state: dict, rng: dict) -> None:
    """The background part of a prune: delete in batches, tell the room after each batch (ids only,
    nothing about who or why), remove the upload files once, and write the single audit entry."""
    stats = {"files": 0, "bytes": 0}
    names: set = set()
    status = "completed"
    error = None

    async def on_batch(ids):
        state["removed"] += len(ids)
        ch = await db.get_chat_channel(channel_id)
        if not ch:
            return
        await broadcast_to_channel(ch["name"], {"type": "messages_pruned", "channel": ch["name"], "ids": ids})

    try:
        await db.prune_chat_messages(where, params, stats, names, on_batch, batch_size=PRUNE_BATCH,
                                     should_stop=lambda: bool(state.get("_stop")))
    except PurgeStopped:
        status = "interrupted"
    except asyncio.CancelledError:
        status = "interrupted"
        raise
    except Exception as e:
        status = "failed"
        error = f"{type(e).__name__}: {e}"
        logger.error(f"[Prune] Channel {channel_id} failed after {state['removed']} messages: {e}")
    finally:
        # A prune that was stopped or cancelled, or that ended while a shutdown was asking it to stop, leaves
        # the upload files of its committed batches to the next start or cleanup: their names are in
        # chat_upload_pending, and the check can take long
        if status != "interrupted" and not state.get("_stop"):
            try:
                await db.finish_purge_files(names, stats)
            except BaseException as e:
                logger.warning(f"[Prune] Upload removal failed: {type(e).__name__} {e}")
        state.update({"running": False, "status": status, "files": stats["files"]})
        ch = None
        try:
            ch = await db.get_chat_channel(channel_id)
        except BaseException:
            pass
        details = {"level": CHAT_LEVEL_NAMES.get(level, "none"), "from": rng["from"], "to": rng["to"],
                   "user": rng["user"], "user_id": rng["user_id"], "skip_pinned": rng["skip_pinned"],
                   "expected_count": rng["expected_count"], "count": state["removed"], "status": status,
                   "files_removed": stats["files"]}
        if error:
            details["error"] = error
        await asyncio.shield(audit_log(
            "chat_prune", actor_id, actor_name, target_id=channel_id, target_type="channel",
            target_name=ch["name"] if ch else str(channel_id), channel_id=channel_id,
            channel_name=ch["name"] if ch else None, details=json.dumps(details)))


async def http_upload_chat_image(request: web.Request) -> web.Response:
    """Upload a file for chat (images + documents + archives + code)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    # Excluded: text/html, text/css, text/javascript, application/xml (XSS risk)
    ALLOWED_TYPES = {
        "image/jpeg": ".jpg", "image/png": ".png", "image/gif": ".gif", "image/webp": ".webp",
        "application/pdf": ".pdf", "text/plain": ".txt", "text/markdown": ".md", "text/csv": ".csv",
        "application/zip": ".zip", "application/gzip": ".gz",
        "application/x-tar": ".tar", "application/x-7z-compressed": ".7z",
        "application/json": ".json",
        "application/x-python": ".py", "text/x-python": ".py",
        "audio/mpeg": ".mp3", "audio/ogg": ".ogg", "video/mp4": ".mp4", "video/webm": ".webm",
        "application/octet-stream": None,  # allow if extension is valid
    }
    ALLOWED_EXTENSIONS = {
        ".jpg", ".jpeg", ".png", ".gif", ".webp",
        ".pdf", ".txt", ".md", ".csv", ".log",
        ".zip", ".gz", ".tar", ".7z",
        ".json", ".py", ".go", ".rs", ".sh",
        ".mp3", ".ogg", ".mp4", ".webm",
        ".conf", ".cfg", ".ini", ".yaml", ".yml", ".toml",
    }

    try:
        reader = await request.multipart()
        field = await reader.next()

        if field is None or field.name not in ("image", "file"):
            return web.json_response({"error": "No file provided"}, status=400)

        content_type = field.headers.get(aiohttp.hdrs.CONTENT_TYPE, "application/octet-stream")
        original_filename = field.filename or "unknown"
        ext = Path(original_filename).suffix.lower()

        # Validate file type
        if content_type not in ALLOWED_TYPES and ext not in ALLOWED_EXTENSIONS:
            return web.json_response({"error": f"File type not allowed: {content_type} ({ext})"}, status=400)

        # Determine extension
        # Keep the stored name to a plain extension so the URL always passes
        # _valid_chat_upload_url; the original filename is returned separately.
        safe_ext = ext if re.fullmatch(r"\.[a-z0-9]{1,10}", ext or "") else ""
        file_ext = ALLOWED_TYPES.get(content_type) or safe_ext or ".bin"
        is_image = content_type.startswith("image/")

        # Size limits: 5MB for images, 25MB for other files
        max_size = 5 * 1024 * 1024 if is_image else 25 * 1024 * 1024

        filename = f"{uuid.uuid4().hex}{file_ext}"
        upload_dir = Path(__file__).parent / "static" / "uploads" / "chat"
        upload_dir.mkdir(parents=True, exist_ok=True)
        filepath = upload_dir / filename

        size = 0
        with open(filepath, "wb") as f:
            while True:
                chunk = await field.read_chunk()
                if not chunk:
                    break
                size += len(chunk)
                if size > max_size:
                    f.close()
                    filepath.unlink()
                    limit_mb = max_size // (1024 * 1024)
                    return web.json_response({"error": f"File too large (max {limit_mb}MB)"}, status=400)
                f.write(chunk)

        file_url = f"/static/uploads/chat/{filename}"
        return web.json_response({
            "url": file_url,
            "filename": original_filename,
            "size": size,
            "content_type": content_type,
            "is_image": is_image
        })

    except Exception as e:
        logger.error(f"Chat file upload error: {e}")
        return web.json_response({"error": "Upload failed"}, status=500)


