# =============================================================================
# Channel Members / Permissions API
# =============================================================================

async def http_get_channel_members(request: web.Request) -> web.Response:
    """Get members of a channel (members + moderator+ can view)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        channel_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)

    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or "user") if user else "user"
    is_mod = user_role in ("admin", "superadmin", "moderator")
    is_member = await db.is_channel_member(channel_id, token.user_id)

    if not is_mod and not is_member:
        return web.json_response({"error": "Access denied"}, status=403)
    if await _member_routes_closed(channel, user_role):
        return web.json_response({"error": "Access denied"}, status=403)

    members = await db.get_channel_members(channel_id)
    return web.json_response({"members": members})


async def _member_routes_closed(channel: dict, user_role: str) -> bool:
    """True when the generic channel-member routes must refuse this caller: the
    channel is the chat of one stream (its mods are managed on the stream's own
    /mods routes, by its owner and admins) and the caller is not an admin."""
    if user_role in ("admin", "superadmin"):
        return False
    return _real_stream_chat(await db.get_stream_by_chat_channel(channel["id"]))


async def http_add_channel_member(request: web.Request) -> web.Response:
    """Add a member to a channel (admin, moderator+, or channel-moderator)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        channel_id = int(request.match_info["id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid channel ID"}, status=400)

    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    # Auth: admin/moderator+ or channel moderator
    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or "user") if user else "user"
    is_mod = user_role in ("admin", "superadmin", "moderator")
    ch_role = await db.get_channel_member_role(channel_id, token.user_id)
    if not is_mod and ch_role != "moderator":
        return web.json_response({"error": "Moderator access required"}, status=403)
    if await _member_routes_closed(channel, user_role):
        return web.json_response({"error": "Moderator access required"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    try:
        target_id = int(data.get("user_id", 0))
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid user_id"}, status=400)

    target = await db.get_user_by_id(target_id)
    if not target:
        return web.json_response({"error": "User not found"}, status=404)

    member_role = data.get("role", "member")
    if member_role not in ("member", "moderator"):
        return web.json_response({"error": "Role must be 'member' or 'moderator'"}, status=400)

    # Only admin+ can set channel moderator role
    if member_role == "moderator" and not is_mod:
        return web.json_response({"error": "Admin access required to set moderator role"}, status=403)
    # A stream chat's mods are appointed on /api/streams/{id}/mods (cap, audit, checks)
    if member_role == "moderator" and _real_stream_chat(await db.get_stream_by_chat_channel(channel_id)):
        return web.json_response({"error": "Appoint chat mods through the stream's mods list"}, status=400)

    # Adding a stream mod as a plain member replaces the row: that ends the appointment
    was_mod_of = await _mod_row_of(channel_id, target_id)
    await db.add_channel_member(channel_id, target_id, role=member_role, added_by=token.user_id)
    _forget_activity_verdicts(channel_id)       # a remembered "not allowed" for the new member
    if was_mod_of and member_role != "moderator":
        await _stream_mod_ended(channel, was_mod_of, token.user_id,
                                user["username"] if user else "unknown", user_role, target_id)

    await audit_log("channel_member_add", token.user_id, user["username"] if user else "unknown",
                    target_id=target_id, target_type="user",
                    target_name=target["username"],
                    channel_id=channel_id, channel_name=channel["name"],
                    details=json.dumps({"role": member_role}))

    return web.json_response({"success": True}, status=201)


async def http_remove_channel_member(request: web.Request) -> web.Response:
    """Remove a member from a channel."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        channel_id = int(request.match_info["id"])
        target_id = int(request.match_info["user_id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)

    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or "user") if user else "user"
    is_mod = user_role in ("admin", "superadmin", "moderator")
    ch_role = await db.get_channel_member_role(channel_id, token.user_id)

    # Users can leave channels themselves
    if target_id == token.user_id:
        was_mod_of = await _mod_row_of(channel_id, target_id)
        await db.remove_channel_member(channel_id, target_id)
        # Out of the room and out of the activity memo before anything else is awaited
        await _evict_unreadable_sockets(channel)
        if was_mod_of:
            await _stream_mod_ended(channel, was_mod_of, token.user_id,
                                    user["username"] if user else "unknown", user_role, target_id)
        await _voice_eject_if_not_allowed(target_id)
        return web.json_response({"success": True})

    # Otherwise need mod/channel-mod access
    if not is_mod and ch_role != "moderator":
        return web.json_response({"error": "Moderator access required"}, status=403)
    if await _member_routes_closed(channel, user_role):
        return web.json_response({"error": "Moderator access required"}, status=403)

    was_mod_of = await _mod_row_of(channel_id, target_id)
    await db.remove_channel_member(channel_id, target_id)
    # Out of the room and out of the activity memo before anything else is awaited
    await _evict_unreadable_sockets(channel)
    if was_mod_of:
        await _stream_mod_ended(channel, was_mod_of, token.user_id,
                                user["username"] if user else "unknown", user_role, target_id)
    await _voice_eject_if_not_allowed(target_id)

    target = await db.get_user_by_id(target_id)
    await audit_log("channel_member_remove", token.user_id, user["username"] if user else "unknown",
                    target_id=target_id, target_type="user",
                    target_name=target["username"] if target else str(target_id),
                    channel_id=channel_id, channel_name=channel["name"])
    # Removing someone else from a channel is a kick. The target's chat_anonymous flag decides
    # whether a sent alert may name them.
    alerts.moderation_action(
        "kick", actor=(user["username"] if user else "a moderator"),
        target=(target["username"] if target else None),
        anonymous=bool(target and target.get("chat_anonymous")) or not target,
        actor_id=token.user_id, target_id=target_id, channel=channel["name"],
        actor_anonymous=bool(user and user.get("chat_anonymous")),
        actor_role=(user or {}).get("role"), private=await _alert_context_private(channel))

    return web.json_response({"success": True})


async def http_update_channel_member_role(request: web.Request) -> web.Response:
    """Update a channel member's role (admin/moderator+ only)."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    try:
        channel_id = int(request.match_info["id"])
        target_id = int(request.match_info["user_id"])
    except (ValueError, TypeError):
        return web.json_response({"error": "Invalid ID"}, status=400)

    channel = await db.get_chat_channel(channel_id)
    if not channel:
        return web.json_response({"error": "Channel not found"}, status=404)

    user = await db.get_user_by_id(token.user_id)
    user_role = (user.get("role") or "user") if user else "user"
    if user_role not in ("admin", "superadmin", "moderator"):
        return web.json_response({"error": "Moderator access required"}, status=403)

    try:
        data = await request.json()
    except json.JSONDecodeError:
        return web.json_response({"error": "Invalid JSON"}, status=400)

    new_role = data.get("role", "member")
    if new_role not in ("member", "moderator"):
        return web.json_response({"error": "Role must be 'member' or 'moderator'"}, status=400)
    if await _member_routes_closed(channel, user_role):
        return web.json_response({"error": "Moderator access required"}, status=403)
    if new_role == "moderator" and _real_stream_chat(await db.get_stream_by_chat_channel(channel_id)):
        return web.json_response({"error": "Appoint chat mods through the stream's mods list"}, status=400)

    # Remove and re-add with new role
    was_mod_of = await _mod_row_of(channel_id, target_id)
    await db.remove_channel_member(channel_id, target_id)
    await db.add_channel_member(channel_id, target_id, role=new_role, added_by=token.user_id)
    _forget_activity_verdicts(channel_id)
    if was_mod_of and new_role != "moderator":
        await _stream_mod_ended(channel, was_mod_of, token.user_id,
                                user["username"] if user else "unknown", user_role, target_id)

    target_user = await db.get_user_by_id(target_id)
    await audit_log("channel_member_role", token.user_id, user["username"] if user else "unknown",
                    target_id=target_id, target_type="user",
                    target_name=target_user["username"] if target_user else str(target_id),
                    channel_id=channel_id, channel_name=channel["name"],
                    details=json.dumps({"new_role": new_role}))

    return web.json_response({"success": True})


async def handle_chat_websocket(request: web.Request) -> web.WebSocketResponse:
    """Handle chat WebSocket connections."""
    token = await authenticate_request(request)
    if not token:
        ws = web.WebSocketResponse()
        await ws.prepare(request)
        await ws.send_json({"type": "error", "message": "Authentication required"})
        await ws.close()
        return ws

    user = await db.get_user_by_id(token.user_id)
    if not user:
        ws = web.WebSocketResponse()
        await ws.prepare(request)
        await ws.send_json({"type": "error", "message": "User not found"})
        await ws.close()
        return ws

    ws = web.WebSocketResponse(heartbeat=30)
    await ws.prepare(request)

    username = user["username"]
    user_id = user["id"]
    user_role = user.get("role") or ("superadmin" if user.get("is_admin") else "user")
    current_channel = None
    voice_room = None  # Track which voice room user is in (channel name or "dm:{conv_id}")

    # Mutable state dict - HTTP handlers update this directly
    _avatar = {}
    if user.get("avatar"):
        try:
            _avatar = json.loads(user["avatar"])
        except (json.JSONDecodeError, TypeError):
            pass
    chat_fresh_state = {
        "anonymous": bool(user.get("chat_anonymous")),
        "nickname": user.get("nickname"),
        "avatar": _avatar,
    }
    my_state = None  # taken inside the try below, released by its finally

    # Rate limiting: max 5 messages per 5 seconds
    chat_rate_limit = 5
    chat_rate_window = 5.0
    chat_msg_times: list[float] = []
    # Typing signals: at most one per second is handled on a socket
    chat_typing_last = [None]

    logger.info(f"[Chat] User {username} connected")

    raw_ws = ws  # Keep raw reference for active_connections and notification cleanup
    active_connections.add(raw_ws)
    _online_users[user_id] = _online_users.get(user_id, 0) + 1
    chat_conn_id = str(uuid.uuid4())
    client_ip = get_client_ip(request)
    traffic_metrics.start_connection(chat_conn_id, SERVICE_ID_CHAT, user_id, "chat", client_ip)
    ws = MetricsWebSocket(raw_ws, chat_conn_id)  # Shadow ws for automatic traffic recording

    user_entry = (ws, user_id, username, user_role)

    # Subscribe to notifications
    if user_id not in notification_subscribers:
        notification_subscribers[user_id] = set()
    notification_subscribers[user_id].add(raw_ws)

    # Register for DM delivery
    if user_id not in dm_user_connections:
        dm_user_connections[user_id] = set()
    dm_user_connections[user_id].add(raw_ws)

    try:
        # Everything that holds a reference is taken inside this try, with no
        # suspension point before it, so a cancellation later on still runs the finally.
        my_state = _chat_state_acquire(user_id, chat_fresh_state)
        # One member's sockets share one regex worker through automod, so the number
        # of them is capped like the generic handler's. Counted in the registry,
        # with no await between this check and the registration below, so sockets
        # opened together cannot all pass it. The pop-out chat adds one or two.
        if len(_user_websockets.get(user_id, ())) >= _MAX_WS_PER_USER:
            logger.warning(f"User {user_id} exceeded max WebSocket connections ({_MAX_WS_PER_USER})")
            await raw_ws.close(code=1013, message=b"too many connections")
            return raw_ws
        _register_user_ws(user_id, raw_ws, token.token_id)
        # Authentication and the upgrade awaited before this point; a revocation in that
        # window did not see this socket, so check the credential once it is registered.
        if not await _credential_still_valid(token):
            await raw_ws.close(code=4001, message=b"session revoked")
            return raw_ws
        try:
            await _notify_prefs_load(user_id)
        except Exception as e:
            logger.warning(f"[Chat] Could not load notification levels of user {user_id}: {e}")
        # Offered to the activity signal only now that the choices are loaded (no await between
        # the load and this line): a member at level none is never told for a moment. If the
        # socket ended during the load, the finally below runs _chat_socket_close, which drops
        # the cache entry when this was the member's last socket.
        _chat_socket_open(user_entry[0], user_id, user_role)

        # Send DM conversations list on connect
        try:
            dm_convs = await db.get_dm_conversations(user_id)
            dm_unread = await db.get_dm_unread_counts(user_id)
            await ws.send_json({
                "type": "dm_conversations_list",
                "conversations": dm_convs,
                "unread_counts": dm_unread
            })
        except (ConnectionError, ConnectionResetError, TypeError):
            pass

        async for msg in ws:
            if msg.type == aiohttp.WSMsgType.TEXT:
                try:
                    data = json.loads(msg.data)
                    msg_type = data.get("type")

                    # Put out of its room (access lost, see _evict_unreadable_sockets):
                    # the socket has no current channel until it joins one again
                    if current_channel and user_entry not in chat_rooms.get(current_channel, ()):
                        current_channel = None

                    if msg_type == "join":
                        # Support multiple join methods:
                        # 1. stream_key (pub_xxx or live_xxx) - preferred for stream chat
                        # 2. channel_id (integer) - direct channel ID
                        # 3. channel (string) - channel name (legacy)
                        stream_key = data.get("stream_key")
                        channel_id = data.get("channel_id")
                        channel_name = data.get("channel")
                        channel = None
                        stream = None

                        if stream_key:
                            # Look up stream by key (public or private)
                            if stream_key.startswith("pub_"):
                                stream = await db.get_stream_by_public_key(stream_key)
                            elif stream_key.startswith("live_"):
                                stream = await db.get_stream_by_key(stream_key)
                            else:
                                # Try both formats
                                stream = await db.get_stream_by_public_key(stream_key)
                                if not stream:
                                    stream = await db.get_stream_by_key(f"live_{stream_key}")

                            if not stream:
                                await ws.send_json({"type": "error", "message": "Invalid stream key"})
                                continue

                            if not stream.get("chat_channel_id"):
                                await ws.send_json({"type": "error", "message": "Stream has no chat channel"})
                                continue

                            channel = await db.get_chat_channel(stream["chat_channel_id"])
                        elif channel_id:
                            # Direct channel ID lookup
                            try:
                                channel = await db.get_chat_channel(int(channel_id))
                            except (ValueError, TypeError):
                                await ws.send_json({"type": "error", "message": "Invalid channel ID"})
                                continue
                            if channel:
                                stream = await db.get_stream_by_chat_channel(channel["id"])
                        else:
                            # Channel name lookup (default to "general")
                            channel_name = channel_name or "general"
                            channel = await db.get_chat_channel_by_name(channel_name)
                            if channel:
                                stream = await db.get_stream_by_chat_channel(channel["id"])

                        if not channel:
                            missing = {"type": "error", "message": "Channel not found"}
                            if not stream_key and not channel_id:
                                missing["channel"] = channel_name
                            await ws.send_json(missing)
                            continue

                        # Leave current text channel (voice stays in its own room)
                        if current_channel and current_channel in chat_rooms:
                            chat_rooms[current_channel].discard(user_entry)
                            # Another socket of this user (pop-out chat window) may
                            # still be in the room: then nobody has left.
                            still_here = _user_has_other_socket(current_channel, user_id, ws)
                            display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                            if not still_here:
                                await broadcast_to_channel(current_channel, {
                                    "type": "user_left",
                                    "user_id": user_id,
                                    "username": display_name
                                }, exclude=ws, anon_subject=user_id if my_state["anonymous"] else None)
                            # Broadcast updated users list to remaining users
                            await broadcast_users_list(current_channel)

                        # Stream ban and private-channel membership: the same check
                        # every way of reading a channel's messages uses
                        # (a stream found by its key carries no channel-level data: ask
                        # for the stream the channel is bound to)
                        check_stream = stream
                        if stream_key and stream:
                            check_stream = await db.get_stream_by_chat_channel(channel["id"])
                        access = await _can_read_channel(channel, user_id, user_role, check_stream)
                        if not access:
                            # The old room is already left and the client has switched
                            # its view: later sends must not go to the room it left
                            current_channel = None
                            await ws.send_json({"type": "error", "message": access.message,
                                                "channel": channel["name"]})
                            continue

                        # Join new channel (use channel name from DB)
                        current_channel = channel["name"]
                        if current_channel not in chat_rooms:
                            chat_rooms[current_channel] = set()
                        # A second socket of the same user (pop-out chat window) joins
                        # silently: the first one already announced the user.
                        announce_join = not _user_has_other_socket(current_channel, user_id, ws)
                        chat_rooms[current_channel].add(user_entry)

                        # Send channel info (include stream data if this is a stream channel)
                        can_send = await db.can_send_in_channel(channel["id"], user_id, user_role)
                        channel_info = {
                            "type": "channel_info",
                            "id": channel["id"],
                            "name": channel["name"],
                            "description": channel.get("description"),
                            "topic": channel.get("topic"),
                            "visibility": channel.get("visibility", "public"),
                            "mode": channel.get("mode", "open"),
                            "can_send": can_send,
                            "slowmode_seconds": channel.get("slowmode_seconds") or 0,
                            # what this member may do here (chat_mod_level), for the page's menus
                            "mod_level": CHAT_LEVEL_NAMES[await chat_mod_level(
                                channel, {"id": user_id, "role": user_role}, check_stream)],
                            "stream_chat": _real_stream_chat(check_stream),
                            # the channel's own retention (a stream's chat follows the global setting), for
                            # the notice and the administrators' settings window
                            "retention_days": None if check_stream and not channel.get("is_default") else _own_retention_value(channel.get("retention_days")),
                            "file_retention_days": None if check_stream and not channel.get("is_default") else _own_retention_value(channel.get("file_retention_days")),
                            "retention_next_cleanup": (datetime.fromtimestamp(_cleanup_next_at, timezone.utc).isoformat()
                                                       if _cleanup_next_at and _own_retention_value(channel.get("retention_days")) is not None
                                                       and not (check_stream and not channel.get("is_default")) else None),
                            # @here / @everyone: the channel's switch and whether this member may use them
                            "allow_mass_mentions": bool(channel.get("allow_mass_mentions")),
                            "can_mass_mention": await _may_mass_mention(channel, user_id, user_role, check_stream)
                        }
                        if stream:
                            channel_info["stream_id"] = stream["id"]
                            channel_info["stream_name"] = stream.get("name", "")
                            channel_info["stream_is_live"] = stream.get("is_live", 0)
                            if stream.get("is_public") or stream.get("user_id") == user_id:
                                channel_info["stream_public_key"] = stream.get("public_key", "")
                            else:
                                channel_info["stream_public_key"] = ""
                        await ws.send_json(channel_info)

                        # Send message history (enriched and masked for this viewer)
                        page = await _channel_history(channel, user_id, user_role,
                                                      limit=HISTORY_PAGE_DEFAULT)
                        messages = page["messages"]
                        await ws.send_json({
                            "type": "history",
                            "channel_id": channel["id"],
                            "messages": messages,
                            "has_more": page["has_more"]
                        })

                        # Send pinned messages
                        pinned = await db.get_pinned_messages(channel["id"])
                        if pinned:
                            await _enrich_channel_messages(pinned, user_id, user_role, channel["id"])
                            for p_msg in pinned:
                                # who pinned it is not sent: a pinner may be anonymous
                                p_msg.pop("pinned_by", None)
                                p_msg.pop("pinned_by_username", None)
                            await ws.send_json({
                                "type": "pinned_messages",
                                "messages": pinned
                            })

                        # Mark channel as read
                        if messages:
                            last_msg_id = messages[-1]["id"]
                            await db.update_read_position(user_id, channel["id"], last_msg_id)

                        # Send user list with status info
                        user_ids = [entry[1] for entry in chat_rooms[current_channel]]
                        users_info = await db.get_users_status(list(set(user_ids)))
                        users_list = _chat_users_list(users_info, current_channel, user_id, user_role)
                        await ws.send_json({
                            "type": "users",
                            "users": users_list
                        })

                        # Notify others
                        display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                        if announce_join:
                            await broadcast_to_channel(current_channel, {
                                "type": "user_joined",
                                "user_id": user_id,
                                "username": display_name,
                                "role": user_role,
                                "anonymous": my_state["anonymous"]
                            }, exclude=ws, anon_subject=user_id if my_state["anonymous"] else None)
                        # Broadcast updated users list to all in channel
                        await broadcast_users_list(current_channel)

                        # Fire webhook + auto-online on first connection
                        if _online_users.get(user_id, 0) == 1:
                            asyncio.create_task(fire_webhook_event("user.connected", {
                                "user_id": user_id, "username": display_name
                            }, meta={"user_id": user_id}))
                            # Auto-set online if currently offline, unless user explicitly chose offline
                            try:
                                u_status = await db.get_user_status(user_id)
                                if (u_status and u_status.get("status") == "offline"
                                        and u_status.get("status_preference") != "offline"):
                                    await db.set_user_status(user_id, "online", u_status.get("status_message"))
                                    for ch in list(chat_rooms.keys()):
                                        for entry in chat_rooms.get(ch, set()):
                                            if entry[1] == user_id:
                                                await broadcast_to_channel(ch, {
                                                    "type": "user_status_changed",
                                                    "user_id": user_id,
                                                    "username": display_name,
                                                    "status": "online",
                                                    "status_message": u_status.get("status_message")
                                                }, anon_subject=user_id if my_state["anonymous"] else None)
                                                break
                            except Exception as e:
                                logger.debug(f"Auto-online status update failed: {e}")

                    elif msg_type == "history_page":
                        # Older messages (before_id), a window around one message
                        # (around_id) or, with neither, the newest page again. The
                        # channel is the one this socket joined, looked up here;
                        # nothing the client sends names a channel. Never marks
                        # anything as read.
                        req = data.get("req")
                        if not isinstance(req, (int, str)) or isinstance(req, bool) or len(str(req)) > 40:
                            req = None
                        try:
                            h_before, h_around, h_limit = _parse_history_request(
                                data.get("before_id"), data.get("around_id"), data.get("limit"))
                        except ValueError as e:
                            await ws.send_json({"type": "history_error", "error_code": "invalid",
                                                "message": str(e), "req": req})
                            continue
                        wait = _history_rate_wait(user_id)
                        if wait:
                            await ws.send_json({"type": "history_error", "error_code": "rate_limited",
                                                "message": "Too many history requests, try again shortly",
                                                "retry_after": wait, "req": req})
                            continue
                        h_channel = await db.get_chat_channel_by_name(current_channel) if current_channel else None
                        if not await _can_read_channel(h_channel, user_id, user_role):
                            await ws.send_json({"type": "history_error", "error_code": "not_found",
                                                "message": "Channel not found", "req": req})
                            continue
                        page = await _channel_history(h_channel, user_id, user_role,
                                                      before_id=h_before, around_id=h_around, limit=h_limit)
                        await ws.send_json({
                            "type": "history_around" if (h_around is not None or h_before is None) else "history_older",
                            "req": req,
                            **page
                        })

                    elif msg_type == "message":
                        if not current_channel:
                            continue

                        message_text = data.get("message", "").strip()
                        image_url = data.get("image_url", "").strip() or None
                        attachment_url = data.get("attachment_url", "").strip() or None
                        attachment_name = data.get("attachment_name", "").strip() or None
                        attachment_size = data.get("attachment_size")
                        attachment_type = data.get("attachment_type", "").strip() or None

                        # Validate image_url if provided
                        if image_url and not _valid_chat_upload_url(image_url):
                            image_url = None

                        # Validate attachment_url if provided
                        if attachment_url and not _valid_chat_upload_url(attachment_url):
                            attachment_url = None
                            attachment_name = None
                            attachment_size = None
                            attachment_type = None

                        # Validate attachment_size
                        if attachment_size is not None:
                            try:
                                attachment_size = int(attachment_size)
                            except (ValueError, TypeError):
                                attachment_size = None

                        # Must have text, image, or attachment
                        if not message_text and not image_url and not attachment_url:
                            continue
                        if len(message_text) > 4000:
                            continue

                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue

                        # Ban, timeout/mute, rate limit and slow mode first (shared with edits)
                        if await _chat_member_blocked(ws, channel, user_id=user_id, user_role=user_role,
                                                      msg_times=chat_msg_times, rate_limit=chat_rate_limit,
                                                      rate_window=chat_rate_window):
                            continue

                        # Auto-moderation check (applies to all users)
                        # Mod+ are exempt from timeout/mute penalties but messages are still blocked
                        if message_text:
                            if await apply_automod(ws, message_text, user_id=user_id, user_role=user_role,
                                                   channel=channel, channel_name=current_channel,
                                                   username=username, my_state=my_state):
                                continue

                        # Channel permission check (readonly channels: only mod+/channel-mod can send)
                        can_send = await db.can_send_in_channel(channel["id"], user_id, user_role)
                        if not can_send:
                            await ws.send_json({
                                "type": "error",
                                "error_code": "readonly",
                                "message": "This channel is read-only"
                            })
                            continue

                        # Handle reply_to
                        reply_to_id = data.get("reply_to")
                        reply_preview = None
                        if reply_to_id:
                            try:
                                reply_to_id = int(reply_to_id)
                            except (ValueError, TypeError):
                                reply_to_id = None
                        if reply_to_id:
                            replied_msg = await db.get_chat_message(reply_to_id)
                            if replied_msg and replied_msg["channel_id"] == channel["id"]:
                                r_username = replied_msg["username"]
                                r_text = replied_msg["message"]
                                if replied_msg.get("anonymous"):
                                    r_username = "Anonymous"
                                if len(r_text) > 100:
                                    r_text = r_text[:100] + "..."
                                reply_preview = {
                                    "id": replied_msg["id"],
                                    "username": r_username,
                                    "message": r_text
                                }
                            else:
                                reply_to_id = None

                        # Save message (always save real username in DB)
                        msg_id = await db.create_chat_message(
                            channel["id"], user_id, username, message_text or "",
                            anonymous=my_state["anonymous"],
                            reply_to=reply_to_id,
                            image_url=image_url,
                            reply_preview_username=reply_preview["username"] if reply_preview else None,
                            reply_preview_text=reply_preview["message"] if reply_preview else None,
                            attachment_url=attachment_url,
                            attachment_name=attachment_name,
                            attachment_size=attachment_size,
                            attachment_type=attachment_type
                        )

                        # Update slowmode tracker
                        if (channel.get("slowmode_seconds") or 0) > 0:
                            _slowmode_last_msg[(channel["id"], user_id)] = monotonic()

                        # Broadcast to channel (display: Anon > Nickname > Username)
                        display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                        broadcast_payload = {
                            "type": "message",
                            "id": msg_id,
                            "user_id": user_id,
                            "username": display_name,
                            "nickname": my_state["nickname"] if not my_state["anonymous"] else None,
                            "role": user_role,
                            "anonymous": my_state["anonymous"],
                            "avatar": my_state["avatar"] if not my_state["anonymous"] else {},
                            "message": message_text,
                            "channel": channel["name"],
                            "channel_id": channel["id"],
                            "created_at": datetime.now(timezone.utc).isoformat()
                        }
                        if reply_to_id and reply_preview:
                            broadcast_payload["reply_to"] = reply_to_id
                            broadcast_payload["reply_preview"] = reply_preview
                        if not my_state["anonymous"]:
                            badge = await _stream_badge(channel, user_id)
                            if badge:
                                broadcast_payload["stream_role"] = badge
                        if image_url:
                            broadcast_payload["image_url"] = image_url
                        if attachment_url:
                            broadcast_payload["attachment_url"] = attachment_url
                            broadcast_payload["attachment_name"] = attachment_name
                            broadcast_payload["attachment_size"] = attachment_size
                            broadcast_payload["attachment_type"] = attachment_type
                        await broadcast_to_channel(current_channel, broadcast_payload,
                                                   anon_subject=user_id if my_state["anonymous"] else None)

                        # Fire webhook event
                        asyncio.create_task(fire_webhook_event("message.created", _message_webhook_payload(
                            msg_id, current_channel, user_id, display_name, message_text,
                            broadcast_payload["created_at"], anonymous=bool(my_state["anonymous"])),
                            meta={"channel_id": channel["id"], "anonymous": bool(my_state["anonymous"])}))

                        # @mention, @here and @everyone notifications
                        if message_text and not my_state["anonymous"]:
                            await _notify_mentions(ws, channel, user_id, user_role, display_name,
                                                   message_text, msg_id)
                        # Members not in this room: a badge signal (no text, no author)
                        _spawn_channel_activity(channel, user_id)

                    elif msg_type == "typing":
                        now_typing = monotonic()
                        if chat_typing_last[0] is not None and now_typing - chat_typing_last[0] < 1.0:
                            continue    # dropped before any lookup
                        chat_typing_last[0] = now_typing
                        typing_ch = await db.get_chat_channel_by_name(current_channel) if current_channel else None
                        if typing_ch and await _socket_may_act_in(ws, typing_ch, user_id, user_role, notify=False):
                            typing_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                            await broadcast_to_channel(current_channel, {
                                "type": "typing",
                                "username": typing_name
                            }, exclude=ws)

                    elif msg_type == "delete":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        if not message_id:
                            continue
                        try:
                            message_id = _ws_id(message_id)
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid message_id"})
                            continue
                        # Verify message belongs to current channel
                        del_msg = await db.get_chat_message(message_id)
                        if not del_msg:
                            continue
                        del_ch = await db.get_chat_channel_by_name(current_channel)
                        if not del_ch or del_msg["channel_id"] != del_ch["id"]:
                            continue
                        if not await _socket_may_act_in(ws, del_ch, user_id, user_role):
                            continue
                        # Moderators (chat_mod_level) delete the messages of members they
                        # may act on; everybody deletes their own
                        is_mod = False
                        mod_level = CHAT_LEVEL_NONE
                        if del_msg.get("user_id") != user_id:
                            mod_level = await chat_mod_level(del_ch, {"id": user_id, "role": user_role})
                            if del_msg.get("user_id") is None:
                                # No author (a system post): the owner and staff only
                                is_mod = mod_level in (CHAT_LEVEL_OWNER, CHAT_LEVEL_STAFF)
                            else:
                                is_mod = mod_level != CHAT_LEVEL_NONE and await chat_mod_may_act(
                                    del_ch, {"id": user_id, "role": user_role}, del_msg.get("user_id"))
                        if is_mod:
                            success = await db.delete_chat_message(message_id)
                        else:
                            success = await db.delete_chat_message(message_id, user_id=user_id)
                        if success:
                            await broadcast_to_channel(current_channel, {
                                "type": "message_deleted",
                                "message_id": message_id,
                                "deleted_by": None if (is_mod and _anon_actor(user_role, my_state)) else user_id
                            }, anon_subject=del_msg["user_id"] if del_msg.get("anonymous") else None)
                            asyncio.create_task(fire_webhook_event("message.deleted", _message_deleted_webhook_payload(
                                message_id, current_channel,
                                None if (is_mod and _anon_actor(user_role, my_state)) else user_id, del_msg),
                                meta={"channel_id": del_ch["id"]}))
                            if is_mod:
                                await _audit_chat_mod("message_delete", user_id, username, mod_level, del_ch,
                                                      target_id=message_id, target_type="message")

                    elif msg_type == "react":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        emoji = data.get("emoji", "").strip()
                        if not message_id or not emoji or len(emoji) > 36:
                            continue
                        try:
                            message_id = int(message_id)
                        except (ValueError, TypeError):
                            continue
                        # Verify message belongs to current channel
                        msg = await db.get_chat_message(message_id)
                        if not msg:
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or msg["channel_id"] != channel["id"]:
                            continue
                        # Closed since the socket joined (stream made private, ban,
                        # removed from a private channel): the same check as a send
                        access = await _can_read_channel(channel, user_id, user_role)
                        if not access:
                            await ws.send_json({"type": "error", "message": access.message})
                            continue
                        added, count = await db.toggle_reaction(message_id, user_id, emoji)
                        await broadcast_to_channel(current_channel, {
                            "type": "reaction_update",
                            "message_id": message_id,
                            "emoji": emoji,
                            "user_id": user_id,
                            "added": added,
                            "count": count
                        }, anon_subject=user_id if my_state["anonymous"] else None)

                    elif msg_type == "edit_message":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        new_text = data.get("message", "").strip()
                        if not message_id or not new_text:
                            continue
                        try:
                            message_id = int(message_id)
                        except (ValueError, TypeError):
                            continue
                        if len(new_text) > 4000:
                            continue
                        # Verify message belongs to current channel
                        edit_msg = await db.get_chat_message(message_id)
                        if not edit_msg:
                            continue
                        edit_ch = await db.get_chat_channel_by_name(current_channel)
                        if not edit_ch or edit_msg["channel_id"] != edit_ch["id"]:
                            continue
                        # Same ownership and time-window rule as the store, checked first so a
                        # refused edit never costs the author an automod penalty.
                        if not db.chat_message_editable(edit_msg, user_id):
                            await ws.send_json({"type": "error", "message": "Cannot edit (5-minute window expired or not your message)"})
                            continue
                        # An edit passes the checks a send does (stream ban, timeout, mute, rate
                        # limit, slow mode) before automod sees it.
                        if await _chat_member_blocked(ws, edit_ch, user_id=user_id, user_role=user_role,
                                                      msg_times=chat_msg_times, rate_limit=chat_rate_limit,
                                                      rate_window=chat_rate_window,
                                                      slowmode=False):
                            # The client shows an edit before the server confirms it: give the
                            # author the stored text back, as for an edit automod refuses.
                            await ws.send_json({
                                "type": "edit_rejected",
                                "message_id": edit_msg["id"],
                                "message": edit_msg["message"]
                            })
                            continue
                        if await apply_automod(ws, new_text, user_id=user_id, user_role=user_role,
                                               channel=edit_ch, channel_name=current_channel,
                                               username=username, my_state=my_state, edit_of=edit_msg):
                            continue
                        updated = await db.edit_chat_message(message_id, user_id, new_text)
                        if updated:
                            await broadcast_to_channel(current_channel, {
                                "type": "message_edited",
                                "message_id": message_id,
                                "message": new_text,
                                "edited_at": updated["edited_at"]
                            })
                        else:
                            await ws.send_json({"type": "error", "message": "Cannot edit (5-minute window expired or not your message)"})

                    elif msg_type == "pin_message":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        if not message_id:
                            continue
                        try:
                            message_id = _ws_id(message_id)
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid message_id"})
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue
                        if not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        mod_level = await chat_mod_level(channel, {"id": user_id, "role": user_role})
                        if mod_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Only moderators can pin messages"})
                            continue
                        msg = await db.get_chat_message(message_id)
                        if not msg or msg["channel_id"] != channel["id"]:
                            continue
                        success = await db.pin_message(message_id, user_id)
                        if success:
                            my_state = chat_user_state.get(user_id, {})
                            display_name = (ANON_MODERATOR_LABEL if _anon_actor(user_role, my_state) else
                                            "Anonymous" if my_state.get("anonymous") else (my_state.get("nickname") or username))
                            msg_author = msg.get("username", "Unknown")
                            if msg.get("anonymous"):
                                msg_author = "Anonymous"
                            await broadcast_to_channel(current_channel, {
                                "type": "message_pinned",
                                "message_id": message_id,
                                "message": msg["message"],
                                "username": msg_author,
                                "pinned_by": display_name
                            })
                            await _audit_chat_mod("pin_message", user_id, username, mod_level, channel,
                                                  target_id=message_id, target_type="message")

                    elif msg_type == "unpin_message":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        if not message_id:
                            continue
                        try:
                            message_id = _ws_id(message_id)
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid message_id"})
                            continue
                        # Verify message belongs to current channel (if it still exists)
                        unpin_ch = await db.get_chat_channel_by_name(current_channel)
                        if not unpin_ch or not await _socket_may_act_in(ws, unpin_ch, user_id, user_role):
                            continue
                        mod_level = await chat_mod_level(unpin_ch, {"id": user_id, "role": user_role})
                        if mod_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Only moderators can unpin messages"})
                            continue
                        unpin_msg = await db.get_chat_message(message_id)
                        if unpin_msg and unpin_msg["channel_id"] != unpin_ch["id"]:
                            continue
                        # Allow unpin even if message was deleted (cleans up stale pins in frontend)
                        # Unpin in DB (no-op if message already deleted)
                        await db.unpin_message(message_id)
                        # Always broadcast so frontend cleans up stale pins
                        await broadcast_to_channel(current_channel, {
                            "type": "message_unpinned",
                            "message_id": message_id
                        })
                        await _audit_chat_mod("unpin_message", user_id, username, mod_level, unpin_ch,
                                              target_id=message_id, target_type="message")

                    elif msg_type == "timeout_user":
                        if not current_channel:
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        mod_level = await chat_mod_level(channel, {"id": user_id, "role": user_role})
                        if mod_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Moderator access required"})
                            continue
                        duration = data.get("duration", 300)
                        reason = str(data.get("reason", ""))[:200]
                        # The target is named by account id, or by the id of one of
                        # their messages (the only way to name the author of an
                        # anonymous post: the client never learns that id)
                        target_user_id = data.get("target_user_id") or data.get("user_id")
                        msg_anon = False      # the post was anonymous: stays so even if the author has since switched it off
                        try:
                            if target_user_id:
                                target_user_id = _ws_id(target_user_id)
                            elif data.get("message_id") is not None:
                                t_msg = await db.get_chat_message(_ws_id(data.get("message_id")))
                                if not t_msg or t_msg.get("channel_id") != channel["id"]:
                                    continue
                                target_user_id = t_msg.get("user_id")
                                msg_anon = bool(t_msg.get("anonymous"))
                            duration = max(1, min(int(duration), 86400 * 30))  # max 30 days
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid message_id, user_id or duration"})
                            continue
                        if not target_user_id:
                            continue
                        actor = {"id": user_id, "role": user_role}
                        target_user = await db.get_user_by_id(target_user_id)
                        if not target_user or not await chat_mod_may_act(channel, actor, target_user_id):
                            await ws.send_json({"type": "error", "message": _CHAT_REFUSED_TARGET})
                            continue
                        if mod_level < CHAT_LEVEL_STAFF:
                            # A new timeout replaces the old penalty row: an owner or a stream mod
                            # may not use it to drop a mute, a site-wide penalty or one that staff
                            # (or a mod above them) placed
                            old_pen = await db.is_user_timed_out(target_user_id, channel["id"])
                            if old_pen and (old_pen.get("type") != "timeout" or old_pen.get("channel_id") is None
                                            or (old_pen.get("moderator_id") != user_id
                                                and not await chat_mod_may_act(channel, actor, old_pen.get("moderator_id")))):
                                await ws.send_json({"type": "error", "message": _CHAT_REFUSED_TARGET})
                                continue
                        await db.create_chat_timeout(target_user_id, user_id, "timeout", channel["id"], reason, duration)
                        await _voice_drop_for_penalty(target_user_id, channel)
                        display_name = (ANON_MODERATOR_LABEL if _anon_actor(user_role, my_state)
                                        else my_state.get("nickname") or username)
                        target_anon = msg_anon or bool(target_user.get("chat_anonymous"))
                        target_name = "Anonymous" if target_anon else (target_user.get("nickname") or target_user["username"])
                        await broadcast_to_channel(current_channel, {
                            "type": "user_timed_out",
                            "user_id": target_user_id,
                            "username": target_name,
                            "duration": duration,
                            "reason": reason,
                            "moderator": display_name
                        }, anon_subject=target_user_id if target_anon else None)
                        await send_notification(target_user_id, "timeout",
                            f"You were timed out in #{current_channel}",
                            f"Duration: {duration}s" + (f" — {reason}" if reason else ""),
                            {"channel": current_channel})
                        await _audit_chat_mod("user_timeout", user_id, username, mod_level, channel,
                                              target_id=target_user_id, target_name=target_name,
                                              extra={"duration": duration, "reason": reason})
                        alerts.moderation_action(
                            "timeout", actor=username, target=target_user["username"], anonymous=target_anon,
                            actor_id=user_id, target_id=target_user_id, channel=current_channel,
                            reason=reason, duration=duration, actor_anonymous=bool(my_state.get("anonymous")),
                            actor_role=user_role, private=await _alert_context_private(channel))

                    elif msg_type == "mute_user":
                        if not current_channel:
                            continue
                        is_mod = user_role in ("admin", "superadmin", "moderator")
                        if not is_mod:
                            await ws.send_json({"type": "error", "message": "Moderator access required"})
                            continue
                        target_user_id = data.get("target_user_id") or data.get("user_id")
                        reason = data.get("reason", "")
                        if not target_user_id:
                            continue
                        try:
                            target_user_id = _ws_id(target_user_id)
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid user_id"})
                            continue
                        target_user = await db.get_user_by_id(target_user_id)
                        if not target_user:
                            continue
                        target_role = target_user.get("role") or "user"
                        if get_role_level(target_role) >= get_role_level(user_role):
                            await ws.send_json({"type": "error", "message": "Cannot mute users with equal or higher role"})
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        await db.create_chat_timeout(target_user_id, user_id, "mute", channel["id"], reason)
                        await _voice_drop_for_penalty(target_user_id, channel)
                        display_name = my_state.get("nickname") or username
                        target_anon = bool(target_user.get("chat_anonymous"))
                        target_name = "Anonymous" if target_anon else (target_user.get("nickname") or target_user["username"])
                        await broadcast_to_channel(current_channel, {
                            "type": "user_muted",
                            "user_id": target_user_id,
                            "username": target_name,
                            "reason": reason,
                            "moderator": display_name
                        }, anon_subject=target_user_id if target_anon else None)
                        await send_notification(target_user_id, "mute",
                            f"You were muted in #{current_channel}",
                            reason or "No reason given",
                            {"channel": current_channel})
                        await audit_log("user_mute", user_id, username,
                                        target_id=target_user_id, target_type="user",
                                        target_name=target_name,
                                        channel_name=current_channel,
                                        details=json.dumps({"reason": reason}))
                        alerts.moderation_action(
                            "mute", actor=username, target=target_user["username"], anonymous=target_anon,
                            actor_id=user_id, target_id=target_user_id, channel=current_channel, reason=reason,
                            actor_anonymous=bool(my_state.get("anonymous")),
                            actor_role=user_role, private=await _alert_context_private(channel))

                    elif msg_type == "unmute_user":
                        if not current_channel:
                            continue
                        is_mod = user_role in ("admin", "superadmin", "moderator")
                        if not is_mod:
                            await ws.send_json({"type": "error", "message": "Moderator access required"})
                            continue
                        target_user_id = data.get("target_user_id") or data.get("user_id")
                        if not target_user_id:
                            continue
                        try:
                            target_user_id = _ws_id(target_user_id)
                        except (ValueError, TypeError):
                            await ws.send_json({"type": "error", "message": "Invalid user_id"})
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        removed = await db.remove_chat_timeout(target_user_id, channel["id"])
                        if removed:
                            _voice_penalty_denies.pop((channel["name"], target_user_id), None)
                            target_user = await db.get_user_by_id(target_user_id)
                            target_anon = bool(target_user.get("chat_anonymous")) if target_user else False
                            target_name = ("Anonymous" if target_anon else (target_user.get("nickname") or target_user["username"])) if target_user else "Unknown"
                            display_name = my_state.get("nickname") or username
                            await broadcast_to_channel(current_channel, {
                                "type": "user_unmuted",
                                "user_id": target_user_id,
                                "username": target_name,
                                "moderator": display_name
                            }, anon_subject=target_user_id if target_anon else None)
                            await audit_log("user_unmute", user_id, username,
                                            target_id=target_user_id, target_type="user",
                                            target_name=target_name, channel_name=current_channel)

                    elif msg_type == "mark_read":
                        if not current_channel:
                            continue
                        message_id = data.get("message_id")
                        if not message_id:
                            continue
                        try:
                            message_id = _ws_id(message_id)
                        except (ValueError, TypeError):
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if channel:
                            await db.update_read_position(user_id, channel["id"], message_id)

                    # ==============================================
                    # User Blocking (WS)
                    # ==============================================
                    elif msg_type == "block_user":
                        target_uid = data.get("target_user_id")
                        if not target_uid:
                            continue
                        try:
                            target_uid = int(target_uid)
                        except (ValueError, TypeError):
                            continue
                        if target_uid == user_id:
                            await ws.send_json({"type": "error", "message": "Cannot block yourself"})
                            continue
                        await db.block_user(user_id, target_uid)
                        await ws.send_json({"type": "user_blocked", "user_id": target_uid})

                    elif msg_type == "unblock_user":
                        target_uid = data.get("target_user_id")
                        if not target_uid:
                            continue
                        try:
                            target_uid = int(target_uid)
                        except (ValueError, TypeError):
                            continue
                        await db.unblock_user(user_id, target_uid)
                        await ws.send_json({"type": "user_unblocked", "user_id": target_uid})

                    # ==============================================
                    # Polls (WS)
                    # ==============================================
                    elif msg_type == "create_poll":
                        if not current_channel:
                            continue
                        # Check timeout/mute
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue
                        # Closed since the socket joined: the same check as a send
                        access = await _can_read_channel(channel, user_id, user_role)
                        if not access:
                            await ws.send_json({"type": "error", "message": access.message})
                            continue
                        timeout_info = await db.is_user_timed_out(user_id, channel["id"])
                        if timeout_info:
                            await ws.send_json({"type": "error", "message": "You are timed out or muted"})
                            continue
                        # In a stream's own chat only its owner, its mods and staff open polls;
                        # every other channel keeps its rule (any member)
                        poll_stream = await db.get_stream_by_chat_channel(channel["id"])
                        poll_level = await chat_mod_level(channel, {"id": user_id, "role": user_role}, poll_stream)
                        if _real_stream_chat(poll_stream) and poll_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error",
                                                "message": "Only the streamer and the chat moderators can start polls here"})
                            continue

                        question = data.get("question", "").strip()
                        options = data.get("options", [])
                        allow_multiple = bool(data.get("allow_multiple", False))
                        anonymous_votes = bool(data.get("anonymous_votes", False))
                        duration = data.get("duration")  # seconds, optional

                        if not question or len(question) > 500:
                            await ws.send_json({"type": "error", "message": "Question required (max 500 chars)"})
                            continue
                        if not isinstance(options, list) or len(options) < 2 or len(options) > 10:
                            await ws.send_json({"type": "error", "message": "Need 2-10 options"})
                            continue
                        # Validate option strings
                        clean_options = []
                        for opt in options:
                            opt_str = str(opt).strip()
                            if not opt_str or len(opt_str) > 200:
                                await ws.send_json({"type": "error", "message": "Each option must be 1-200 chars"})
                                break
                            clean_options.append(opt_str)
                        else:
                            # All options valid
                            expires_minutes = None
                            if duration:
                                try:
                                    dur_secs = int(duration)
                                    if 60 <= dur_secs <= 604800:
                                        expires_minutes = max(1, dur_secs // 60)
                                except (ValueError, TypeError):
                                    pass

                            # Create a message for the poll
                            display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                            msg_id = await db.create_chat_message(
                                channel["id"], user_id, username,
                                f"📊 Poll: {question}",
                                anonymous=my_state["anonymous"]
                            )

                            poll_id = await db.create_poll(
                                channel_id=channel["id"],
                                message_id=msg_id,
                                user_id=user_id,
                                question=question,
                                options=clean_options,
                                allow_multiple=allow_multiple,
                                anonymous_votes=anonymous_votes,
                                expires_minutes=expires_minutes
                            )

                            poll_data = _format_poll_for_client(await db.get_poll(poll_id), user_id)
                            await broadcast_to_channel(current_channel, {
                                "type": "poll_created",
                                "poll": poll_data,
                                "message_id": msg_id,
                                "user_id": user_id,
                                "username": display_name,
                                "created_at": datetime.now(timezone.utc).isoformat()
                            }, anon_subject=user_id if my_state["anonymous"] else None)
                            if _real_stream_chat(poll_stream):
                                await _audit_chat_mod("poll_create", user_id, username, poll_level, channel,
                                                      target_id=poll_id, target_type="poll",
                                                      extra={"stream_id": poll_stream["id"]})

                    elif msg_type == "vote_poll":
                        poll_id = data.get("poll_id")
                        option_index = data.get("option_index")
                        if poll_id is None or option_index is None:
                            continue
                        try:
                            poll_id = _ws_id(poll_id)
                            option_index = int(option_index)
                        except (ValueError, TypeError):
                            continue

                        poll = await db.get_poll(poll_id)
                        if not poll:
                            await ws.send_json({"type": "error", "message": "Poll not found"})
                            continue
                        # Verify poll belongs to user's current channel
                        poll_ch = await db.get_chat_channel(poll["channel_id"])
                        if not poll_ch or poll_ch["name"] != current_channel:
                            await ws.send_json({"type": "error", "message": "Poll not found"})
                            continue
                        # Closed since the socket joined: the same check as a send
                        access = await _can_read_channel(poll_ch, user_id, user_role)
                        if not access:
                            await ws.send_json({"type": "error", "message": access.message})
                            continue
                        if poll.get("is_closed"):
                            await ws.send_json({"type": "error", "message": "Poll is closed"})
                            continue
                        if poll.get("expires_at"):
                            try:
                                exp = datetime.fromisoformat(poll["expires_at"].replace("Z", "+00:00"))
                                if datetime.now(timezone.utc) > exp:
                                    await ws.send_json({"type": "error", "message": "Poll has expired"})
                                    continue
                            except (ValueError, TypeError):
                                pass
                        options = poll.get("options_list", [])
                        if option_index < 0 or option_index >= len(options):
                            await ws.send_json({"type": "error", "message": "Invalid option"})
                            continue

                        success = await db.vote_poll(poll_id, user_id, option_index)
                        if success:
                            updated_poll = _format_poll_for_client(await db.get_poll(poll_id))
                            ch_name = None
                            ch = await db.get_chat_channel(poll["channel_id"])
                            if ch:
                                ch_name = ch["name"]
                            if ch_name and ch_name in chat_rooms:
                                await broadcast_to_channel(ch_name, {
                                    "type": "poll_updated",
                                    "poll": updated_poll
                                }, anon_subject=await _anonymous_poll_creator(poll))
                        else:
                            await ws.send_json({"type": "error", "message": "Already voted (multi-vote not allowed)"})

                    elif msg_type == "close_poll":
                        poll_id = data.get("poll_id")
                        if not poll_id:
                            continue
                        try:
                            poll_id = _ws_id(poll_id)
                        except (ValueError, TypeError):
                            continue
                        poll = await db.get_poll(poll_id)
                        if not poll:
                            await ws.send_json({"type": "error", "message": "Poll not found"})
                            continue
                        # Verify poll belongs to user's current channel
                        poll_ch = await db.get_chat_channel(poll["channel_id"])
                        if not poll_ch or poll_ch["name"] != current_channel:
                            await ws.send_json({"type": "error", "message": "Poll not found"})
                            continue
                        if not await _socket_may_act_in(ws, poll_ch, user_id, user_role):
                            continue
                        # Only creator or mod+ can close
                        is_creator = poll["user_id"] == user_id
                        is_mod = await chat_mod_level(poll_ch, {"id": user_id, "role": user_role}) != CHAT_LEVEL_NONE
                        if not is_creator and not is_mod:
                            await ws.send_json({"type": "error", "message": "Only poll creator or moderators can close polls"})
                            continue
                        await db.close_poll(poll_id)
                        updated_poll = _format_poll_for_client(await db.get_poll(poll_id))
                        ch = await db.get_chat_channel(poll["channel_id"])
                        if ch and ch["name"] in chat_rooms:
                            await broadcast_to_channel(ch["name"], {
                                "type": "poll_closed",
                                "poll": updated_poll
                            }, anon_subject=await _anonymous_poll_creator(poll))

                    elif msg_type == "ban":
                        # Stream owner can ban a user from chat, named either by
                        # account id or by the id of one of their messages (the
                        # server then looks the author up, so the client never
                        # needs the id of an anonymous author).
                        if not current_channel:
                            continue

                        by_message = data.get("user_id") is None and data.get("message_id") is not None
                        target_user_id = None
                        ban_message_id = None
                        ban_msg_anonymous = False
                        try:
                            if by_message:
                                ban_message_id = _ws_id(data.get("message_id"))
                            else:
                                target_user_id = _ws_id(data.get("user_id"))
                        except (TypeError, ValueError):
                            await ws.send_json({"type": "error",
                                                "message": "Invalid message_id" if by_message else "Invalid user_id"})
                            continue
                        reason = data.get("reason", "")

                        if not by_message and not target_user_id:
                            await ws.send_json({"type": "error", "message": "user_id required"})
                            continue

                        # Get the stream for this chat channel
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue

                        stream = await db.get_stream_by_chat_channel(channel["id"])
                        if not stream:
                            await ws.send_json({"type": "error", "message": "Not a stream chat"})
                            continue

                        # The owner, a stream mod of this chat and staff ban (chat_mod_level);
                        # who they may ban is chat_mod_may_act below
                        if not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        actor = {"id": user_id, "role": user_role}
                        mod_level = await chat_mod_level(channel, actor, stream)
                        if mod_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Not authorized"})
                            continue

                        if by_message:
                            # Only messages of this stream's chat resolve, and
                            # only after the authorisation above.
                            ban_msg = await db.get_chat_message(ban_message_id)
                            if (not ban_msg or ban_msg.get("channel_id") != channel["id"]
                                    or not ban_msg.get("user_id")):
                                await ws.send_json({"type": "error", "message": "Message not found"})
                                continue
                            target_user_id = ban_msg["user_id"]
                            # The message stays anonymous even if its author has
                            # switched anonymous mode off since.
                            ban_msg_anonymous = bool(ban_msg.get("anonymous"))

                        # Not oneself, not the owner, not another mod, not staff (one text for
                        # all of them: it must not say who an anonymous author is)
                        if not await chat_mod_may_act(channel, actor, target_user_id, stream):
                            await ws.send_json({"type": "error", "message": _CHAT_REFUSED_TARGET})
                            continue

                        # Create the ban. A ban made from an anonymous post is
                        # its own record (one per message) that is never
                        # refused because the author is already banned, so the
                        # answer does not show whether that is the case.
                        ban_id = await db.create_stream_ban(
                            stream_id=stream["id"],
                            user_id=target_user_id,
                            banned_by=user_id,
                            reason=reason,
                            anonymous=ban_msg_anonymous,
                            message_id=ban_message_id if ban_msg_anonymous else None,
                            banned_by_anonymous=_anon_actor(user_role, my_state)
                        )

                        if ban_id:
                            # Playback is refused from the next request on, not after the
                            # cached decision runs out
                            _stream_member_lost_access(stream["id"], target_user_id)
                            # A banned member does not stay in the room or the voice call.
                            await _evict_unreadable_sockets(channel)
                            await _voice_eject_if_not_allowed(target_user_id)
                            # Get banned user info
                            banned_user = await db.get_user_by_id(target_user_id)
                            # Only a ban made from an anonymous post is masked.
                            # A ban by account id is answered and announced by
                            # name whatever the target's current mode is: the
                            # caller supplied the id, and a different answer
                            # for anonymous accounts would let them probe it.
                            # The exception is a staff caller: staff are shown
                            # the id on anonymous posts and can ban from them by
                            # id, and their answer is no probe because they
                            # already see the identity.
                            banned_anon = ban_msg_anonymous or (
                                user_role in _CHAT_STAFF_ROLES
                                and bool(banned_user and banned_user.get("chat_anonymous")))
                            banned_username = banned_user["username"] if banned_user else f"User {target_user_id}"

                            # Notify the channel
                            await broadcast_to_channel(current_channel, {
                                "type": "user_banned",
                                "user_id": target_user_id,
                                "username": "Anonymous" if banned_anon else banned_username,
                                "banned_by": ANON_MODERATOR_LABEL if _anon_actor(user_role, my_state) else username,
                                "reason": reason
                            }, anon_subject=target_user_id if banned_anon else None)

                            # Send confirmation to the banner; an anonymous
                            # target stays anonymous unless the banner is entitled
                            # to the identity.
                            hide_target = banned_anon and not _viewer_sees_identity(
                                user_id, user_role, target_user_id)
                            await ws.send_json({
                                "type": "ban_success",
                                "user_id": None if hide_target else target_user_id,
                                "username": "Anonymous" if hide_target else banned_username
                            })

                            logger.info(f"User {banned_username} banned from stream {stream['name']} by {username}")
                            await _audit_chat_mod("user_ban", user_id, username, mod_level, channel,
                                                  target_id=target_user_id,
                                                  target_name="Anonymous" if banned_anon else banned_username,
                                                  extra={"reason": reason, "stream": stream["name"],
                                                         "stream_id": stream["id"]})
                            alerts.moderation_action(
                                "ban", actor=username, target=banned_username,
                                anonymous=bool(banned_anon or (banned_user and banned_user.get("chat_anonymous"))),
                                actor_id=user_id, target_id=target_user_id, channel=current_channel,
                                reason=reason, where=stream["name"],
                                actor_anonymous=bool(my_state.get("anonymous")),
                                actor_role=user_role, private=await _alert_context_private(channel))
                        else:
                            await ws.send_json({"type": "error", "message": "User may already be banned"})

                    elif msg_type == "unban":
                        # Stream owner can unban a user, named either by account
                        # id or by the id of the ban (the only way to lift a ban
                        # made from an anonymous post without knowing the author).
                        if not current_channel:
                            continue

                        by_ban_id = data.get("user_id") is None and data.get("ban_id") is not None
                        try:
                            if by_ban_id:
                                target_ban_id = _ws_id(data.get("ban_id"))
                            else:
                                target_user_id = _ws_id(data.get("user_id"))
                        except (TypeError, ValueError):
                            await ws.send_json({"type": "error",
                                                "message": "Invalid ban_id" if by_ban_id else "Invalid user_id"})
                            continue
                        if not by_ban_id and not target_user_id:
                            await ws.send_json({"type": "error", "message": "user_id required"})
                            continue

                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue

                        stream = await db.get_stream_by_chat_channel(channel["id"])
                        if not stream:
                            await ws.send_json({"type": "error", "message": "Not a stream chat"})
                            continue

                        # The owner, a stream mod of this chat and staff unban
                        # An admin or superadmin lifts any ban, their own included (see
                        # _role_lifts_any_ban); everyone else needs to read the chat
                        lifts_any = _role_lifts_any_ban(user_role)
                        if not lifts_any and not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        mod_level = (CHAT_LEVEL_STAFF if lifts_any else
                                     await chat_mod_level(channel, {"id": user_id, "role": user_role}, stream))
                        if mod_level == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Not authorized"})
                            continue

                        # Who the ban is on is known before anything is deleted: the
                        # owner and stream mods lift it only for members they may act on
                        actor = {"id": user_id, "role": user_role}
                        if by_ban_id:
                            pending = await db.get_stream_ban(stream["id"], target_ban_id)
                            unban_target = pending["user_id"] if pending else None
                        else:
                            unban_target = target_user_id
                        if not lifts_any and unban_target is not None and unban_target != user_id and not await chat_mod_may_act(
                                channel, actor, unban_target, stream):
                            await ws.send_json({"type": "error", "message": _CHAT_REFUSED_TARGET})
                            continue

                        removed_anonymous = False
                        if by_ban_id:
                            removed = await db.remove_stream_ban_by_id(stream["id"], target_ban_id)
                            success = removed is not None
                            if success:
                                target_user_id = removed["user_id"]
                                removed_anonymous = bool(removed.get("anonymous"))
                        else:
                            # Without staff rights only the named ban goes: a ban
                            # made from an anonymous post must not react to an
                            # account id the caller guessed.
                            success = await db.remove_stream_ban(
                                stream["id"], target_user_id,
                                include_anonymous=user_role in _CHAT_STAFF_ROLES)
                        if success:
                            _playback_cache_forget(stream_id=stream["id"])
                            _forget_activity_for_stream(stream["id"])
                            banned_user = await db.get_user_by_id(target_user_id)
                            banned_username = banned_user["username"] if banned_user else f"User {target_user_id}"
                            hide_target = removed_anonymous and not _viewer_sees_identity(
                                user_id, user_role, target_user_id)

                            await ws.send_json({
                                "type": "unban_success",
                                "user_id": None if hide_target else target_user_id,
                                "username": "Anonymous" if hide_target else banned_username
                            })
                            logger.info(f"User {banned_username} unbanned from stream {stream['name']} by {username}")
                            await _audit_chat_mod("user_unban", user_id, username, mod_level, channel,
                                                  target_id=target_user_id,
                                                  target_name="Anonymous" if removed_anonymous else banned_username,
                                                  extra={"stream_id": stream["id"]})
                        else:
                            await ws.send_json({"type": "error", "message": "Ban not found"})

                    elif msg_type == "set_slowmode":
                        # The owner of this stream's chat, its mods and staff set the wait between
                        # a viewer's messages: 0, 5, 15 or 30 seconds, in a real stream chat only
                        # (the HTTP channel route still refuses stream channels)
                        if not current_channel:
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        sm_stream = await db.get_stream_by_chat_channel(channel["id"])
                        sm_level = await chat_mod_level(channel, {"id": user_id, "role": user_role}, sm_stream)
                        if sm_level == CHAT_LEVEL_NONE or not _real_stream_chat(sm_stream):
                            await ws.send_json({"type": "error", "message": "Not authorized"})
                            continue
                        seconds = data.get("seconds")
                        if isinstance(seconds, bool) or seconds not in STREAM_SLOWMODE_CHOICES:
                            await ws.send_json({"type": "error", "message": "Slow mode is 0, 5, 15 or 30 seconds"})
                            continue
                        await db.update_chat_channel(channel["id"], slowmode_seconds=int(seconds))
                        await broadcast_to_channel(current_channel, {
                            "type": "slowmode_changed", "seconds": int(seconds),
                            "channel_id": channel["id"]})
                        await _audit_chat_mod("slowmode_set", user_id, username, sm_level, channel,
                                              extra={"seconds": int(seconds), "stream_id": sm_stream["id"]})

                    elif msg_type == "set_mass_mentions":
                        # Open @here and @everyone to every member of this channel (or close them
                        # again): staff in any channel they can read, the owner of a stream's chat
                        # in that chat. Stream mods and everybody else are refused.
                        if not current_channel:
                            continue
                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel or not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        mm_level = await chat_mod_level(channel, {"id": user_id, "role": user_role})
                        if mm_level not in (CHAT_LEVEL_STAFF, CHAT_LEVEL_OWNER):
                            await ws.send_json({"type": "error", "message": "Not authorized"})
                            continue
                        allowed = data.get("allowed")
                        if not isinstance(allowed, bool):
                            await ws.send_json({"type": "error", "message": "allowed must be true or false"})
                            continue
                        if bool(channel.get("allow_mass_mentions")) != allowed:
                            await db.set_allow_mass_mentions(channel["id"], allowed)
                            await broadcast_to_channel(current_channel, {
                                "type": "mass_mentions_changed", "allowed": allowed,
                                "channel_id": channel["id"]})
                            await _audit_chat_mod("mass_mentions_set", user_id, username, mm_level, channel,
                                                  extra={"allowed": allowed})

                    elif msg_type == "get_bans":
                        # Get list of banned users (stream owner only)
                        if not current_channel:
                            continue

                        channel = await db.get_chat_channel_by_name(current_channel)
                        if not channel:
                            continue

                        stream = await db.get_stream_by_chat_channel(channel["id"])
                        if not stream:
                            await ws.send_json({"type": "error", "message": "Not a stream chat"})
                            continue

                        # The owner, a stream mod of this chat and staff see the ban list
                        if not await _socket_may_act_in(ws, channel, user_id, user_role):
                            continue
                        if await chat_mod_level(channel, {"id": user_id, "role": user_role}, stream) == CHAT_LEVEL_NONE:
                            await ws.send_json({"type": "error", "message": "Not authorized"})
                            continue

                        bans = _mask_ban_rows(await db.get_stream_bans(stream["id"]),
                                              user_id, user_role)
                        await ws.send_json({
                            "type": "bans_list",
                            "bans": bans
                        })

                    # =========================================================
                    # Voice Chat Signaling
                    # =========================================================
                    elif msg_type == "voice_join":
                        # Refusals (timed out or muted, room full, locked, kick block) and
                        # the resume branch live in _voice_join.
                        joined_room = await _voice_join(
                            ws, user_id, user_role, token.token_id, my_state,
                            username, current_channel, data)
                        if joined_room:
                            voice_room = joined_room

                    elif msg_type in VOICE_MOD_FRAMES:
                        await _voice_moderate(ws, user_id, user_role, username, voice_room, msg_type, data)

                    elif msg_type == "voice_leave":
                        # With the resume token this ends the account's own
                        # session from a new socket, for a Leave that was
                        # clicked while the old socket was down.
                        if isinstance(data.get("resume_token"), str):
                            if await _voice_leave_with_token(user_id, data):
                                voice_room = None
                            continue
                        if not voice_room:
                            continue
                        # Only the socket that owns the session can end it.
                        if _voice_owned(voice_room, user_id, ws) is not None:
                            await _voice_remove(voice_room, user_id)
                        voice_room = None

                    elif msg_type == "voice_signal":
                        # Forward WebRTC signaling to target user
                        target_user_id = data.get("target_user_id")
                        signal_data = data.get("signal")
                        if not target_user_id or not signal_data or not voice_room:
                            continue

                        try:
                            target_user_id = int(target_user_id)
                        except (ValueError, TypeError):
                            continue
                        if target_user_id == user_id:
                            continue  # Don't relay signals to self

                        # Find target in voice state (a member that is
                        # reconnecting has no live socket to receive it)
                        target_entry = voice_state.get(voice_room, {}).get(target_user_id)
                        if (_voice_owned(voice_room, user_id, ws) is not None
                                and target_entry is not None
                                and not target_entry.get("reconnecting")):
                            target_ws = target_entry["ws"]
                            try:
                                if not target_ws.closed:
                                    await target_ws.send_json({
                                        "type": "voice_signal",
                                        "from_user_id": user_id,
                                        "signal": signal_data
                                    })
                            except (ConnectionError, ConnectionResetError, TypeError):
                                pass

                    elif msg_type == "voice_mute":
                        muted = bool(data.get("muted", False))
                        own_entry = _voice_owned(voice_room, user_id, ws)
                        if own_entry is not None:
                            muted = muted or bool(own_entry.get("server_muted"))   # a server mute is not lifted by the member
                            own_entry["muted"] = muted
                            bcast = {"type": "voice_mute_changed", "user_id": user_id, "muted": muted}
                            await broadcast_to_voice_room(voice_room, bcast)

                    elif msg_type == "voice_deafen":
                        deafened = bool(data.get("deafened", False))
                        own_entry = _voice_owned(voice_room, user_id, ws)
                        if own_entry is not None:
                            own_entry["deafened"] = deafened
                            bcast = {"type": "voice_deafen_changed", "user_id": user_id, "deafened": deafened}
                            await broadcast_to_voice_room(voice_room, bcast)

                    elif msg_type == "voice_speaking":
                        speaking = bool(data.get("speaking", False))
                        own_entry = _voice_owned(voice_room, user_id, ws)
                        if own_entry is not None:
                            # Rate-limit speaking broadcasts (max 1 per 100ms)
                            rate_key = (voice_room, user_id)
                            now = monotonic()
                            last = _voice_speaking_last.get(rate_key, 0)
                            if now - last < 0.1:
                                continue
                            _voice_speaking_last[rate_key] = now

                            own_entry["speaking"] = speaking
                            bcast = {"type": "voice_speaking_changed", "user_id": user_id, "speaking": speaking}
                            await broadcast_to_voice_room(voice_room, bcast)

                    elif msg_type == "screen_share_start":
                        own_entry = _voice_owned(voice_room, user_id, ws)
                        if own_entry is None:
                            continue
                        # Check timeout/mute in channel rooms (not DMs)
                        if not voice_room.startswith("dm:"):
                            ss_channel = await db.get_chat_channel_by_name(voice_room)
                            if ss_channel:
                                ss_timeout = await db.is_user_timed_out(user_id, ss_channel["id"])
                                if ss_timeout:
                                    await ws.send_json({"type": "error", "message": "You are timed out in this channel"})
                                    continue
                        # Check nobody else is sharing in this room
                        already_sharing = any(
                            vd.get("screen_sharing") for vid, vd in voice_state[voice_room].items() if vid != user_id
                        )
                        if already_sharing:
                            await ws.send_json({"type": "error", "message": "Someone is already sharing their screen"})
                            continue
                        if _voice_owned(voice_room, user_id, ws) is not own_entry:
                            continue  # the session changed while the checks above ran
                        own_entry["screen_sharing"] = True
                        display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                        bcast = {"type": "screen_share_started", "user_id": user_id, "username": display_name}
                        await broadcast_to_voice_room(voice_room, bcast)
                        logger.info(f"[Voice] {display_name} started screen sharing in {voice_room}")

                    elif msg_type == "screen_share_stop":
                        own_entry = _voice_owned(voice_room, user_id, ws)
                        if own_entry is None:
                            continue
                        own_entry["screen_sharing"] = False
                        bcast = {"type": "screen_share_stopped", "user_id": user_id}
                        await broadcast_to_voice_room(voice_room, bcast)
                        display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
                        logger.info(f"[Voice] {display_name} stopped screen sharing in {voice_room}")

                    # ==============================================
                    # Direct Message handlers
                    # ==============================================

                    elif msg_type == "dm_open":
                        # Open/create a 1:1 DM conversation
                        target_user_id = data.get("user_id")
                        conv_id = data.get("conversation_id")
                        conv = None
                        if target_user_id:
                            try:
                                target_user_id = int(target_user_id)
                            except (ValueError, TypeError):
                                continue
                            if target_user_id == user_id:
                                await ws.send_json({"type": "error", "message": "Cannot DM yourself"})
                                continue
                            # Block check for DMs
                            if await db.is_blocked_bidirectional(user_id, target_user_id):
                                await ws.send_json({"type": "error", "message": "Cannot message this user"})
                                continue
                            target = await db.get_user_by_id(target_user_id)
                            if not target:
                                await ws.send_json({"type": "error", "message": "User not found"})
                                continue
                            conv = await db.create_dm_conversation(user_id, [target_user_id], conv_type="1on1")
                        elif conv_id:
                            try:
                                conv_id = int(conv_id)
                            except (ValueError, TypeError):
                                continue
                            if not await db.is_dm_participant(conv_id, user_id):
                                continue
                            conv = await db.get_dm_conversation(conv_id)
                        if conv:
                            messages = await db.get_dm_messages(conv["id"], limit=50)
                            msg_ids = [m["id"] for m in messages]
                            reactions = await db.get_bulk_dm_reactions(msg_ids) if msg_ids else {}
                            for m in messages:
                                m["reactions"] = reactions.get(m["id"], [])
                            await ws.send_json({
                                "type": "dm_conversation_opened",
                                "conversation": conv,
                                "messages": messages
                            })

                    elif msg_type == "dm_create_group":
                        # Create a group DM
                        try:
                            target_ids = [int(uid) for uid in data.get("user_ids", [])]
                        except (ValueError, TypeError):
                            continue
                        if user_id in target_ids:
                            target_ids.remove(user_id)
                        if not target_ids or len(target_ids) > 9:
                            await ws.send_json({"type": "error", "message": "Need 1-9 other participants"})
                            continue
                        name = data.get("name", "").strip() or None
                        conv = await db.create_dm_conversation(user_id, target_ids, name=name, conv_type="group")
                        await ws.send_json({
                            "type": "dm_conversation_opened",
                            "conversation": conv,
                            "messages": []
                        })
                        # Notify other participants
                        for uid in target_ids:
                            await _send_dm_to_user(uid, {
                                "type": "dm_conversations_list",
                                "conversations": await db.get_dm_conversations(uid),
                                "unread_counts": await db.get_dm_unread_counts(uid)
                            })

                    elif msg_type == "dm_message":
                        # Send a DM message
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                        except (ValueError, TypeError):
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        # Block check for DMs
                        if await _dm_participant_blocked(user_id, conv_id):
                            await ws.send_json({"type": "error", "message": "Cannot message this user"})
                            continue
                        text = data.get("message", "").strip()
                        image_url = data.get("image_url")
                        if image_url and not _valid_chat_upload_url(image_url):
                            image_url = None
                        attachment_url = data.get("attachment_url")
                        attachment_name = data.get("attachment_name")
                        attachment_size = data.get("attachment_size")
                        attachment_type = data.get("attachment_type")
                        if attachment_size is not None:
                            try:
                                attachment_size = int(attachment_size)
                            except (ValueError, TypeError):
                                attachment_size = None
                        if attachment_url and not _valid_chat_upload_url(attachment_url):
                            attachment_url = None
                            attachment_name = None
                            attachment_size = None
                            attachment_type = None
                        if not text and not image_url and not attachment_url:
                            continue
                        if text and len(text) > 4000:
                            text = text[:4000]
                        # Rate limit (shared with channel chat)
                        now_mono = monotonic()
                        chat_msg_times[:] = [t for t in chat_msg_times if now_mono - t < chat_rate_window]
                        if len(chat_msg_times) >= chat_rate_limit:
                            await ws.send_json({"type": "error", "message": "Rate limit exceeded"})
                            continue
                        chat_msg_times.append(now_mono)

                        reply_to = data.get("reply_to")
                        reply_preview_username = None
                        reply_preview_text = None
                        if reply_to:
                            try:
                                reply_to = int(reply_to)
                                orig = await db.get_dm_message(reply_to)
                                if orig and orig.get("conversation_id") == conv_id:
                                    reply_preview_username = orig.get("username", "")
                                    reply_preview_text = orig.get("message", "")[:100]
                                else:
                                    reply_to = None
                            except (ValueError, TypeError):
                                reply_to = None

                        display_name = "Anonymous" if my_state.get("anonymous") else (my_state.get("nickname") or username)
                        msg_id = await db.create_dm_message(
                            conv_id, user_id, username, text,
                            reply_to=reply_to, image_url=image_url,
                            reply_preview_username=reply_preview_username,
                            reply_preview_text=reply_preview_text,
                            attachment_url=attachment_url,
                            attachment_name=attachment_name,
                            attachment_size=attachment_size,
                            attachment_type=attachment_type
                        )
                        payload = {
                            "type": "dm_message",
                            "conversation_id": conv_id,
                            "id": msg_id,
                            "user_id": user_id,
                            "username": display_name,
                            "message": text,
                            "image_url": image_url,
                            "attachment_url": attachment_url,
                            "attachment_name": attachment_name,
                            "attachment_size": attachment_size,
                            "attachment_type": attachment_type,
                            "reply_to": reply_to,
                            "reply_preview_username": reply_preview_username,
                            "reply_preview_text": reply_preview_text,
                            "created_at": datetime.now(timezone.utc).isoformat(),
                            "reactions": []
                        }
                        await _broadcast_to_dm(conv_id, payload)
                        # Send notification to offline participants
                        participants = await db.get_dm_participant_ids(conv_id)
                        for pid in participants:
                            if pid != user_id and pid not in dm_user_connections:
                                await send_notification(
                                    pid, "dm_message",
                                    f"New message from {display_name}",
                                    None,
                                    {"conversation_id": conv_id, "message_id": msg_id}
                                )
                        # A member with no open chat socket also gets a push (no text, no sender name)
                        _schedule_push(_push_dm(conv_id, user_id))

                    elif msg_type == "dm_typing":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                        except (ValueError, TypeError):
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        display_name = "Anonymous" if my_state.get("anonymous") else (my_state.get("nickname") or username)
                        await _broadcast_to_dm(conv_id, {
                            "type": "dm_typing",
                            "conversation_id": conv_id,
                            "user_id": user_id,
                            "username": display_name
                        }, exclude_user_id=user_id)

                    elif msg_type == "dm_delete":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                            message_id = int(data.get("message_id", 0))
                        except (ValueError, TypeError):
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        msg = await db.get_dm_message(message_id)
                        if not msg or msg.get("conversation_id") != conv_id:
                            continue
                        deleted = await db.delete_dm_message(message_id, user_id)
                        if deleted:
                            await _broadcast_to_dm(conv_id, {
                                "type": "dm_message_deleted",
                                "conversation_id": conv_id,
                                "message_id": message_id
                            })

                    elif msg_type == "dm_react":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                            message_id = int(data.get("message_id", 0))
                        except (ValueError, TypeError):
                            continue
                        emoji = data.get("emoji", "")
                        if not emoji or len(emoji) > 36:
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        react_msg = await db.get_dm_message(message_id)
                        if not react_msg or react_msg.get("conversation_id") != conv_id:
                            continue
                        added, count = await db.toggle_dm_reaction(message_id, user_id, emoji)
                        await _broadcast_to_dm(conv_id, {
                            "type": "dm_reaction_update",
                            "conversation_id": conv_id,
                            "message_id": message_id,
                            "emoji": emoji,
                            "added": added,
                            "count": count,
                            "user_id": user_id
                        })

                    elif msg_type == "dm_edit":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                            message_id = int(data.get("message_id", 0))
                        except (ValueError, TypeError):
                            continue
                        new_text = data.get("message", "").strip()
                        if not new_text or len(new_text) > 4000:
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        edit_msg = await db.get_dm_message(message_id)
                        if not edit_msg or edit_msg.get("conversation_id") != conv_id:
                            continue
                        # The checks a DM send has: a block between the participants, and the
                        # rate limit shared with channel chat.
                        if await _dm_participant_blocked(user_id, conv_id):
                            await ws.send_json({"type": "error", "message": "Cannot message this user"})
                            continue
                        now_mono = monotonic()
                        chat_msg_times[:] = [t for t in chat_msg_times if now_mono - t < chat_rate_window]
                        if len(chat_msg_times) >= chat_rate_limit:
                            await ws.send_json({"type": "error", "message": "Rate limit exceeded"})
                            continue
                        chat_msg_times.append(now_mono)
                        updated = await db.edit_dm_message(message_id, user_id, new_text)
                        if updated:
                            await _broadcast_to_dm(conv_id, {
                                "type": "dm_message_edited",
                                "conversation_id": conv_id,
                                "message_id": message_id,
                                "message": new_text,
                                "edited_at": updated["edited_at"]
                            })

                    elif msg_type == "dm_mark_read":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                            message_id = int(data.get("message_id", 0))
                        except (ValueError, TypeError):
                            continue
                        if await db.is_dm_participant(conv_id, user_id):
                            await db.update_dm_read_position(user_id, conv_id, message_id)

                    elif msg_type == "dm_history":
                        try:
                            conv_id = int(data.get("conversation_id", 0))
                        except (ValueError, TypeError):
                            continue
                        if not await db.is_dm_participant(conv_id, user_id):
                            continue
                        before_id = data.get("before_id")
                        if before_id:
                            try:
                                before_id = int(before_id)
                            except (ValueError, TypeError):
                                before_id = None
                        messages = await db.get_dm_messages(conv_id, limit=50, before_id=before_id)
                        msg_ids = [m["id"] for m in messages]
                        reactions = await db.get_bulk_dm_reactions(msg_ids) if msg_ids else {}
                        for m in messages:
                            m["reactions"] = reactions.get(m["id"], [])
                        await ws.send_json({
                            "type": "dm_history",
                            "conversation_id": conv_id,
                            "messages": messages
                        })

                except json.JSONDecodeError:
                    await ws.send_json({"type": "error", "message": "Invalid JSON"})

            elif msg.type == aiohttp.WSMsgType.ERROR:
                logger.error(f"[Chat] WebSocket error: {ws.exception()}")
                break

    except Exception as e:
        logger.error(f"[Chat] Error: {e}")
        traffic_metrics.record_error(SERVICE_ID_CHAT)

    finally:
        # Clean up global connection tracking
        active_connections.discard(raw_ws)
        _unregister_user_ws(user_id, raw_ws)
        _chat_socket_close(user_entry[0], user_id)
        traffic_metrics.end_connection(chat_conn_id)
        count = _online_users.get(user_id, 1) - 1
        if count <= 0:
            _online_users.pop(user_id, None)
        else:
            _online_users[user_id] = count

        # Voice: only the entries this socket owns are touched, so closing a
        # second tab leaves the call in the first one alone. An owned entry
        # keeps its place for a short grace period so the same browser can
        # resume it on a new socket (revoked sessions were removed already).
        await _voice_close_safely(ws, user_id)
        # Clean up speaking rate-limit entries
        for key in [k for k in _voice_speaking_last
                    if k[1] == user_id and user_id not in voice_state.get(k[0], {})]:
            _voice_speaking_last.pop(key, None)

        # Clean up chat room
        if current_channel and current_channel in chat_rooms:
            chat_rooms[current_channel].discard(user_entry)
            still_here = _user_has_other_socket(current_channel, user_id, ws)
            display_name = "Anonymous" if my_state["anonymous"] else (my_state["nickname"] or username)
            if not still_here:
                await broadcast_to_channel(current_channel, {
                    "type": "user_left",
                    "user_id": user_id,
                    "username": display_name
                }, anon_subject=user_id if my_state["anonymous"] else None)
            # Broadcast updated users list to remaining users
            await broadcast_users_list(current_channel)
            # Remove empty rooms
            if current_channel in chat_rooms and not chat_rooms[current_channel]:
                del chat_rooms[current_channel]

        # Clean up mutable state (only if no other WS for this user)
        has_other_ws = False
        for ch_users in chat_rooms.values():
            for entry in ch_users:
                if entry[1] == user_id and entry[0] != ws:
                    has_other_ws = True
                    break
            if has_other_ws:
                break
        _chat_state_release(user_id)
        if not has_other_ws:
            # Auto-set offline + update last_seen (preserve manual busy/dnd)
            try:
                u_status = await db.get_user_status(user_id)
                if u_status and u_status.get("status") in ("online", "away"):
                    await db.set_user_status(user_id, "offline", u_status.get("status_message"))
                await db.update_last_seen(user_id)
                asyncio.create_task(fire_webhook_event("user.disconnected", {
                    "user_id": user_id, "username": username
                }, meta={"user_id": user_id}))
            except Exception as e:
                logger.debug(f"Auto-offline status update failed: {e}")

        # Unsubscribe from notifications
        if user_id in notification_subscribers:
            notification_subscribers[user_id].discard(raw_ws)
            if not notification_subscribers[user_id]:
                del notification_subscribers[user_id]

        # Unregister from DM delivery
        if user_id in dm_user_connections:
            dm_user_connections[user_id].discard(raw_ws)
            if not dm_user_connections[user_id]:
                del dm_user_connections[user_id]

        logger.info(f"[Chat] User {username} disconnected")

    return raw_ws


async def http_voice_ice_servers(request: web.Request) -> web.Response:
    """Get ICE server configuration for WebRTC voice chat."""
    token = await authenticate_request(request)
    if not token:
        return unauthorized_response(request)

    ice_servers = []
    # STUN server
    if Config.STUN_SERVER:
        ice_servers.append({"urls": Config.STUN_SERVER})
    # TURN server (optional)
    if Config.TURN_SERVER:
        turn_entry = {"urls": Config.TURN_SERVER}
        if Config.TURN_USERNAME:
            turn_entry["username"] = Config.TURN_USERNAME
        if Config.TURN_PASSWORD:
            turn_entry["credential"] = Config.TURN_PASSWORD
        ice_servers.append(turn_entry)

    return web.json_response({"ice_servers": ice_servers})


