class PortalServer:
    """Main Open Relay Portal server."""

    def __init__(self):
        self.runner = None
        self._shutdown_event = asyncio.Event()
        self._vod_recovery_task = None
        self._search_backfill_task = None

    def _start_vod_recovery(self) -> None:
        """Start a recovery pass over the VOD staging folder unless one is already running."""
        task = self._vod_recovery_task
        if _vod_recovery_running or (task is not None and not task.done()):
            return
        self._vod_recovery_task = asyncio.create_task(recover_vod_staging())

    async def _cancel_vod_recovery(self) -> None:
        """Cancel a running recovery pass (and a scheduled extra pass) and wait for it to end."""
        global _vod_extra_sweep_task
        extra, _vod_extra_sweep_task = _vod_extra_sweep_task, None
        if extra is not None and not extra.done():
            extra.cancel()
            try:
                await extra
            except asyncio.CancelledError:
                pass
            except Exception as e:
                logger.debug(f"VOD extra sweep task ended with {e}")
        task = self._vod_recovery_task
        self._vod_recovery_task = None
        if task is not None and not task.done():
            task.cancel()
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception as e:
                logger.debug(f"VOD recovery task ended with {e}")

    async def _search_backfill_runner(self) -> None:
        """Run the one-time search index backfill a little after start, off the
        request path. It resumes where it stopped and does nothing once done."""
        try:
            await asyncio.sleep(20)
            await db.backfill_search_flags()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            logger.error(f"Search index backfill stopped: {e}")

    async def start(self) -> None:
        """Start the server."""
        # Validate configuration
        if Config.validate_or_warn():
            logger.error("Configuration errors detected. Please fix and restart.")
            sys.exit(1)

        if Config.STAGE_MODE:
            logger.warning("PORTAL_STAGE_MODE is on: staged test instance, host side effects are disabled")

        # Initialize database
        await db.connect()
        logger.info(f"Database connected: {Config.DATABASE_PATH}")

        # Probe nice/ionice once, off the event loop, so no later spawn has to.
        await asyncio.to_thread(_media_warm)

        # Terminal recordings are private: tighten an existing directory now,
        # not only when the next recording starts.
        try:
            from session_recording import prepare_recordings_dir, tighten_recording_files, RecordingsDirRefused
            prepare_recordings_dir(Config.RECORDINGS_DIR)
            tightened = tighten_recording_files(Config.RECORDINGS_DIR)
            if tightened:
                logger.info(f"Set mode 0600 on {tightened} existing recording file(s)")
            await session_recording.reconcile_total()
            try:
                await session_recording.finish_interrupted()
            except Exception as e:
                logger.warning(f"Could not close off interrupted recordings: {e}")
        except RecordingsDirRefused:
            pass  # recording_paths already logged why; recording stays off for this run
        except OSError as e:
            logger.warning(f"Could not prepare the recordings directory {Config.RECORDINGS_DIR}: {e}")

        # Reset all streams to offline on startup (no stream can be live before MediaMTX starts)
        stale = await db.reset_all_streams_offline()
        if stale:
            logger.info(f"Reset {stale} stale stream(s) to offline")

        # Load persisted settings from database
        log_settings_json = await db.get_setting("log_settings")
        if log_settings_json:
            try:
                log_settings_data = json.loads(log_settings_json)
                update_log_settings(log_settings_data)
                logger.info("Log settings restored from database")
            except (json.JSONDecodeError, ValueError) as e:
                logger.warning(f"Could not restore log settings: {e}")

        # Load and initialize plugins
        load_builtin_plugins()
        await initialize_plugins()
        logger.info("Plugins initialized")

        # Initialize Shodan client - check database first (encrypted), then env var
        shodan_api_key_raw = await db.get_setting("shodan_api_key")
        shodan_api_key = decrypt_config(shodan_api_key_raw) if shodan_api_key_raw else Config.SHODAN_API_KEY
        if shodan_api_key:
            await init_shodan(shodan_api_key)
            Config.SHODAN_API_KEY = shodan_api_key  # Update Config for runtime checks
            shodan_client.set_api_key(shodan_api_key)  # Ensure client has the key
            logger.info("Shodan integration initialized (key from database)" if shodan_api_key_raw else "Shodan integration initialized (key from env)")

        # Load blocked IPs into the in-process cache the middleware checks
        global _blocked_ips
        try:
            await db.sweep_auto_bans()
        except Exception as e:
            logger.warning(f"Sweep of expired automatic bans failed: {type(e).__name__}")
        await _load_login_ban_state()
        await _load_proxy_limit_state()
        _blocked_ips = await db.get_active_blocked_ips()
        if _blocked_ips:
            logger.info(f"Loaded {len(_blocked_ips)} active IP block(s)")

        # Never-ban list, the last good Cloudflare ranges, and the proxy-trust notice
        await _load_never_ban_state()
        await _load_cloudflare_state()
        # Exemption state is complete now: lift stored automatic bans on addresses it covers
        await _drop_exempt_auto_bans()
        _log_proxy_trust_at_startup()

        # Start traffic metrics recorder
        if Config.METRICS_ENABLED:
            await start_metrics_recorder()
            logger.info("Traffic metrics recorder started")
            await start_resource_metrics_recorder()
            await start_device_metrics_recorder(db)

        # VOD staging: folder setup, old /tmp migration, upload of leftover chunks
        vod_leftovers = await asyncio.to_thread(_vod_prepare_staging)
        if vod_leftovers:
            self._start_vod_recovery()

        # Browser playback cache of VOD chunks: folder setup, index check, strays removed
        await asyncio.to_thread(_vod_play_setup)
        await _vod_play_reconcile_owners()

        # Security event log: bind the database and start the aggregate flusher
        secevents.log.bind(db)
        secevents.log.start()
        _bind_alerts()

        # Start unified data retention cleanup task
        asyncio.create_task(self._data_cleanup_task())

        # Operator flags for old messages in the search index: a background pass in
        # small batches (never in staged mode; a staged check starts it on purpose)
        if not Config.STAGE_MODE:
            self._search_backfill_task = asyncio.create_task(self._search_backfill_runner())

        # Scheduled backup due check shortly after start, so a service that restarts more
        # often than the cleanup interval still gets its backups (skipped in staged mode)
        if not Config.STAGE_MODE:
            asyncio.create_task(backup_manager.run_startup_check())

        # Weekly Cloudflare range refresh (the only outbound call is two GETs of the published lists;
        # never in staged mode)
        if not Config.STAGE_MODE:
            asyncio.create_task(_cf_refresh_loop())
            asyncio.create_task(_alert_cert_loop())
            asyncio.create_task(_alert_update_loop())

        # Start viewer count sync task (portal-side viewer map, every few seconds)
        # (it only reads and writes the database, so it runs in staged mode too)
        asyncio.create_task(self._viewer_sync_task())

        # Start RTMP token cleanup task (runs every 5 minutes)
        asyncio.create_task(self._rtmp_token_cleanup_task())

        # Expired connection shares and service grants: deleted, audited, their sockets closed
        # (runs in staged mode too; it only reads and writes the database and closes sockets)
        asyncio.create_task(self._grant_expiry_task())

        # Start relay health monitor (restarts orphaned relays every 45 seconds)
        if not Config.STAGE_MODE:
            asyncio.create_task(self._relay_health_monitor_task())

        # Initialize vulnerability scanner - check database for NVD API key (encrypted)
        nvd_api_key_raw = await db.get_setting("nvd_api_key")
        nvd_api_key = decrypt_config(nvd_api_key_raw) if nvd_api_key_raw else Config.NVD_API_KEY
        await init_scanner(
            nvd_api_key=nvd_api_key or None,
            nmap_path=Config.NMAP_PATH,
            cache_ttl=Config.CVE_CACHE_TTL,
            timeout=Config.VULN_SCAN_TIMEOUT
        )
        if nvd_api_key:
            Config.NVD_API_KEY = nvd_api_key
        logger.info("Vulnerability scanner initialized")

        # Initialize managed services
        global _service_manager
        load_service_types()  # Load service type plugins
        _service_manager = await init_service_manager(db, on_event=alerts.service_event)
        logger.info("Managed services initialized")

        # Seed the game-server catalog (idempotent) + start the periodic
        # SteamCMD build-check so cards show an up-to-date / update-available badge
        try:
            await gameservers.seed_catalog(db)
            await gameservers.ensure_default_storage_root(db)
            await gameservers.resync_all_from_catalog(db)
            if not Config.STAGE_MODE:  # these touch systemd units, steamcmd and the real home dir
                await gameservers.migrate_broken_runtimes(db)
                gameservers.start_build_check_loop(db)
                await gameservers.ensure_steam_runtime_libs()
        except Exception as e:
            logger.warning(f"Game catalog seed failed: {e}")

        # Register mediamtx restart callback with update manager
        async def _restart_mediamtx_services():
            for svc in _service_manager.get_all_services():
                if getattr(svc, 'binary_name', None) == 'mediamtx':
                    if svc.status == 'running':
                        await _service_manager.stop_service(svc.id)
                    await _service_manager.start_service(svc.id)
        update_manager.register_mediamtx_restart(_restart_mediamtx_services)

        # Create SSL context
        ssl_context = create_ssl_context()
        logger.info("SSL context created")

        # Create and start application
        app = create_app()
        self.runner = web.AppRunner(app)
        await self.runner.setup()

        site = web.TCPSite(
            self.runner,
            Config.HOST,
            Config.PORT,
            ssl_context=ssl_context
        )
        try:
            await site.start()
        except PermissionError:
            logger.error(f"Permission denied binding to port {Config.PORT}.")
            logger.error(f"Ports below 1024 require root. Fix with one of:")
            logger.error(f"  1. sudo python server.py serve")
            logger.error(f"  2. sudo systemctl start portal  (if installed)")
            logger.error(f"  3. Change PORT to 8443 in .env (no root needed)")
            sys.exit(1)
        except OSError as e:
            if e.errno == 98:  # EADDRINUSE
                logger.error(f"Port {Config.PORT} is already in use.")
                logger.error(f"Another instance may be running. Check with:")
                logger.error(f"  sudo ss -tlnp sport = :{Config.PORT}")
            else:
                logger.error(f"Failed to bind to {Config.HOST}:{Config.PORT}: {e}")
            sys.exit(1)

        # Generate/log daily invite code (DB-backed + legacy file)
        invite_code = get_daily_invite_code()  # Legacy file-based
        # Seed daily code in DB (uses first admin user)
        try:
            cursor = await db.conn.execute(
                "SELECT id FROM users WHERE is_admin = 1 OR role IN ('admin', 'superadmin') LIMIT 1"
            )
            admin_row = await cursor.fetchone()
            if admin_row:
                db_daily_code = await db.ensure_daily_invite_code(admin_row["id"])
                logger.info(f"Daily invite code (DB): {db_daily_code}")
        except Exception as e:
            logger.warning(f"Failed to seed daily invite code in DB: {e}")
        logger.info(f"Daily invite code (legacy): {invite_code}")

        logger.info(f"Open Relay Portal started on https://{Config.HOSTNAME}:{Config.PORT}")
        logger.info("Endpoints:")
        logger.info(f"  - Health:     GET  /health")
        logger.info(f"  - Login:      GET  /login")
        logger.info(f"  - Dashboard:  GET  /dashboard")
        logger.info(f"  - Register:   POST /api/register (requires invite code)")
        logger.info(f"  - WebSocket:  wss://{Config.HOSTNAME}/ws/")

    async def _rtmp_token_cleanup_task(self) -> None:
        """Background task to clean up expired RTMP tokens (runs every 5 minutes)."""
        while True:
            try:
                await asyncio.sleep(5 * 60)  # 5 minutes
                deleted = await db.cleanup_expired_rtmp_tokens()
                if deleted > 0:
                    logger.debug(f"Cleaned up {deleted} expired RTMP token(s)")
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"RTMP token cleanup error: {e}")

    async def _grant_expiry_task(self) -> None:
        """Every 60 s: sweep_expired_grants_once(). Access is already refused by the
        predicate when the time passes; a socket that was open then ends within one tick."""
        while True:
            try:
                await asyncio.sleep(_grant_sweep_interval())
                n = await sweep_expired_grants_once()
                if n:
                    logger.info(f"Expired {n} share(s) or grant(s)")
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Grant expiry sweep error: {e}")

    async def _data_cleanup_task(self) -> None:
        """Unified data retention cleanup — interval configurable via settings."""
        # Files of messages a prune or cleanup deleted before the last stop or kill go now, not at the
        # end of the first interval
        try:
            pending = await _pending_upload_names()
            if pending:
                left_over = {"files": 0, "bytes": 0}
                await db.finish_purge_files(pending, left_over)
                logger.info(f"[Retention] Removed {left_over['files']} chat upload file(s) left by a stopped prune or cleanup")
        except asyncio.CancelledError:
            return
        except Exception as e:
            logger.error(f"[Retention] Pending chat upload removal failed: {e}")
        while True:
            try:
                config = await db.get_retention_config()
                interval = max(1, int(config.get("cleanup_interval_hours", 6)))
                global _cleanup_next_at
                _cleanup_next_at = time() + interval * 60 * 60     # shown as "next cleanup about" in channel info
                await asyncio.sleep(interval * 60 * 60)

                config = await db.get_retention_config()
                total = 0

                # Leftover VOD chunks: try the upload again, drop undeliverable ones after 14 days
                try:
                    self._start_vod_recovery()
                except Exception as e:
                    logger.error(f"[Retention] VOD recovery could not start: {e}")

                # Chat messages (and the upload files only they referred to)
                file_stats = {"files": 0, "bytes": 0}
                try:
                    total += await _run_chat_retention(config, file_stats)
                except Exception as e:
                    logger.error(f"[Retention] Chat cleanup failed: {e}")

                # DM messages
                try:
                    dm_days = int(config.get("retention_dm_days", 30))
                    if dm_days > 0:
                        d = await db.cleanup_old_dm_messages(days=dm_days, stats=file_stats)
                        if d > 0:
                            logger.info(f"[Retention] Cleaned {d} DM messages older than {dm_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] DM cleanup failed: {e}")
                if file_stats["files"]:
                    logger.info(f"[Retention] Removed {file_stats['files']} chat upload file(s), "
                                f"{file_stats['bytes']} bytes, with their messages")

                # Chat upload files no message refers to: once a day, report only
                # unless chat_orphan_sweep_delete is "true"
                try:
                    last = float(await db.get_setting("chat_orphan_sweep_last") or 0)
                    if time() - last >= 23 * 3600:
                        await db.sweep_orphan_chat_uploads()
                        await db.set_setting("chat_orphan_sweep_last", str(time()))
                except Exception as e:
                    logger.error(f"[Retention] Orphan chat upload sweep failed: {e}")

                # Notifications
                try:
                    notif_days = int(config.get("retention_notifications_days", 30))
                    if notif_days > 0:
                        d = await db.cleanup_old_notifications(days=notif_days)
                        if d > 0:
                            logger.info(f"[Retention] Cleaned {d} notifications older than {notif_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Notification cleanup failed: {e}")

                # Activity log
                try:
                    activity_max = int(config.get("retention_activity_max", 500))
                    d = await db.cleanup_old_activity_log(keep=activity_max)
                    if d > 0:
                        logger.info(f"[Retention] Trimmed {d} activity log entries (keeping {activity_max})")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Activity log cleanup failed: {e}")

                # Expired tokens & API keys
                try:
                    d = await db.cleanup_expired_tokens()
                    total += d
                    d = await db.cleanup_expired_api_keys()
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Token cleanup failed: {e}")

                # Expired automatic IP bans and their escalation history
                try:
                    total += await db.sweep_auto_bans()
                except Exception as e:
                    logger.error(f"[Retention] Automatic ban sweep failed: {e}")

                # Service logs
                try:
                    logs_max = int(config.get("retention_service_logs_max", 1000))
                    service_ids = await db.get_all_service_ids()
                    for sid in service_ids:
                        d = await db.clear_service_logs(sid, keep_recent=logs_max)
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Service log cleanup failed: {e}")

                # Device-wide metric samples
                try:
                    devm_days = int(config.get("retention_device_metrics_days", 14))
                    if devm_days > 0:
                        d = await db.cleanup_device_metrics(days=devm_days)
                        if d > 0:
                            logger.info(f"[Retention] Cleaned {d} device metric samples older than {devm_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Device metrics cleanup failed: {e}")

                # Terminal recordings
                try:
                    rec_days = int(config.get("retention_recordings_days", 30))
                    if rec_days > 0:
                        d = await db.cleanup_old_recordings(days=rec_days)
                        if d > 0:
                            logger.info(f"[Retention] Removed {d} terminal recordings older than {rec_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Recordings cleanup failed: {e}")

                # Recording files no row refers to (account or service deleted)
                try:
                    d = await db.cleanup_orphan_recordings()
                    await session_recording.reconcile_total()
                    if d > 0:
                        logger.info(f"[Retention] Removed {d} orphan terminal recording files")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Orphan recording sweep failed: {e}")

                # Revoked invite codes (purge after 30 days)
                try:
                    d = await db.cleanup_old_invite_codes(days=30)
                    if d > 0:
                        logger.info(f"[Retention] Purged {d} revoked invite codes older than 30 days")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Invite code cleanup failed: {e}")

                # Expired chat timeouts
                try:
                    d = await db.cleanup_expired_timeouts()
                    if d > 0:
                        logger.info(f"[Retention] Cleaned {d} expired chat timeouts")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Timeout cleanup failed: {e}")

                # Audit log
                try:
                    audit_days = int(config.get("retention_audit_log_days", 90))
                    if audit_days > 0:
                        d = await db.cleanup_old_audit_log(days=audit_days)
                        if d > 0:
                            logger.info(f"[Retention] Cleaned {d} audit log entries older than {audit_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Audit log cleanup failed: {e}")

                # Security events (0 keeps everything)
                try:
                    sec_days = int(config.get("retention_security_events_days", 180))
                    if sec_days > 0:
                        d = await db.cleanup_old_security_events(days=sec_days)
                        if d > 0:
                            logger.info(f"[Retention] Cleaned {d} security events older than {sec_days} days")
                        total += d
                except Exception as e:
                    logger.error(f"[Retention] Security events cleanup failed: {e}")

                # Automod actions
                try:
                    d = await db.cleanup_old_automod_actions(days=30)
                    if d > 0:
                        logger.info(f"[Retention] Cleaned {d} automod actions older than 30 days")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Automod actions cleanup failed: {e}")

                # Webhook log cleanup (7 days)
                try:
                    d = await db.cleanup_old_webhook_logs(max_age_days=7)
                    if d > 0:
                        logger.info(f"[Retention] Cleaned {d} webhook logs older than 7 days")
                    total += d
                except Exception as e:
                    logger.error(f"[Retention] Webhook log cleanup failed: {e}")

                # In-memory cache cleanup
                try:
                    now_mono = monotonic()
                    stale = [k for k, v in _slowmode_last_msg.items() if now_mono - v > 3600]
                    for k in stale:
                        del _slowmode_last_msg[k]
                    stale = [k for k, v in _voice_speaking_last.items() if now_mono - v > 300]
                    for k in stale:
                        del _voice_speaking_last[k]
                    stale_wh = [k for k, v in _webhook_rate_limits.items() if not v]
                    for k in stale_wh:
                        del _webhook_rate_limits[k]
                    stale_inc = [k for k, v in _webhook_incoming_rate_limits.items() if not v]
                    for k in stale_inc:
                        del _webhook_incoming_rate_limits[k]
                    if stale:
                        logger.debug("[Retention] Cleaned stale in-memory rate-limit entries")
                except Exception as e:
                    logger.error(f"[Retention] In-memory cleanup failed: {e}")

                # VACUUM
                try:
                    if config.get("auto_vacuum", "true") == "true":
                        await db.vacuum_database()
                except Exception as e:
                    logger.error(f"[Retention] VACUUM failed: {e}")

                # Scheduled backup archive (skipped in staged mode and when disabled)
                try:
                    await backup_manager.run_scheduled()
                except Exception as e:
                    logger.error(f"[Backup] Scheduled backup failed: {e}")

                if total > 0:
                    logger.info(f"[Retention] Cleanup complete: {total} total items removed")

            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"[Retention] Cleanup error: {e}")

    async def _viewer_sync_task(self) -> None:
        """Background task: prune viewers not seen lately and write viewer_count when it changed."""
        while True:
            try:
                await asyncio.sleep(_VIEWER_SYNC_SECONDS)
                await _viewer_sync_once()
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"[Viewer sync] Error: {e}")

    async def _relay_health_monitor_task(self) -> None:
        """Background task: restart relays for live streams that have no active relay processes.

        Handles the case where the RTSP source drops briefly (causing ffmpeg to exit cleanly)
        without triggering a full on_publish callback — leaving relays permanently dead while
        the stream remains marked live in the DB.
        """
        await asyncio.sleep(60)  # Initial delay — let the server fully start up
        while True:
            try:
                await asyncio.sleep(45)

                # Get all currently live streams
                cursor = await db.conn.execute(
                    "SELECT id, stream_key FROM user_streams WHERE is_live = 1"
                )
                live_streams = await cursor.fetchall()
                if not live_streams:
                    continue

                now = monotonic()
                async with _stream_state_lock:
                    relay_snapshot = dict(active_relays)

                for row in live_streams:
                    stream_id = row["id"]

                    # Skip if stream has active relay processes
                    if relay_snapshot.get(stream_id):
                        continue

                    # Skip if we restarted recently (90s cooldown to avoid thrash)
                    if now - _relay_restart_cooldown.get(stream_id, 0) < 90:
                        continue

                    # Check if this stream has any enabled relay destinations
                    dests = await db.get_enabled_relay_destinations(stream_id)
                    if not dests:
                        continue

                    # Double-check stream is still live before acting
                    current = await db.get_user_stream(stream_id)
                    if not current or current.get("is_live") != 1:
                        continue

                    _relay_restart_cooldown[stream_id] = now
                    async with _stream_state_lock:
                        active_key = _rtmp_stream_paths.get(stream_id, current["stream_key"])

                    logger.info(f"Relay health monitor: stream {stream_id} is live but has no "
                                f"active relays — restarting {len(dests)} destination(s)")
                    asyncio.create_task(start_stream_relays(current, active_key))

            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error(f"Relay health monitor error: {e}")

    async def stop(self) -> None:
        """Stop the server gracefully."""
        logger.info("Shutting down...")

        # A running prune starts winding down now (it ends at its next batch boundary), so that happens
        # while the open connections drain instead of after it
        _ask_prunes_to_stop()

        # Stop the go-live announcements still writing (cards, notifications) before anything else
        await _cancel_golive_tasks()
        await _cancel_stream_info_tasks()
        if _push_pusher is not None:
            await _push_pusher.shutdown()

        # Playback jobs: their ffmpeg children are ours and end now, their work files are removed
        await _vod_play_cancel_all()

        # Stop any active stream relays
        for sid in list(active_relays.keys()):
            await stop_stream_relays(sid, force=True)

        # Stop the periodic VOD recovery before the recordings finish
        await self._cancel_vod_recovery()
        if self._search_backfill_task is not None and not self._search_backfill_task.done():
            self._search_backfill_task.cancel()   # resumes from its stored position at the next start

        # Stop any active VOD recordings and upload to SFTP
        await stop_all_recordings()

        # Stop metrics recorder
        await stop_metrics_recorder()
        await stop_resource_metrics_recorder()
        await stop_device_metrics_recorder()

        # Shutdown managed services (stops all running service processes)
        await shutdown_service_manager()
        logger.info("Managed services stopped")

        # Shutdown Shodan client
        await shutdown_shodan()

        # Shutdown vulnerability scanner
        await shutdown_scanner()

        # Stop the automod regex worker process
        await _automod_regex.close()

        # Shutdown plugins
        await shutdown_plugins()

        if self.runner:
            await self.runner.cleanup()

        # No request can start a prune any more; a running one finishes its files and its audit entry
        # while the database is still open
        await _cancel_prune_tasks()

        # Write the security events still counted in memory before the database closes
        await secevents.log.shutdown()

        await db.close()
        logger.info("Server stopped")

    async def run(self) -> None:
        """Run the server until shutdown signal."""
        await self.start()

        loop = asyncio.get_event_loop()

        def signal_handler():
            self._shutdown_event.set()

        for sig in (signal.SIGTERM, signal.SIGINT):
            loop.add_signal_handler(sig, signal_handler)

        await self._shutdown_event.wait()
        await self.stop()


