async def init_admin_user() -> None:
    """Initialize admin user if not exists."""
    import secrets

    await db.connect()
    secevents.log.bind(db)      # command-line process: events are written directly

    password = secrets.token_urlsafe(16)
    creds_file = Path(__file__).parent / "admin_credentials.txt"

    admin = await db.get_user_by_username("admin")
    if not admin:
        await create_user("admin", password, is_admin=True)
        label = "INITIAL ADMIN USER CREATED"
    else:
        # Reset password so credentials file is always current
        from argon2 import PasswordHasher
        ph = PasswordHasher()
        hashed = ph.hash(password)
        await db.conn.execute(
            "UPDATE users SET password_hash = ? WHERE username = 'admin'",
            (hashed,),
        )
        await db.conn.commit()
        revoked = await db.revoke_user_tokens(admin["id"])
        keys_revoked = await db.revoke_user_api_keys(admin["id"])
        await audit_log("password_reset", admin["id"], "cli",
                        target_id=admin["id"], target_type="user",
                        target_name="admin",
                        details={"sessions_revoked": revoked,
                                 "api_keys_revoked": keys_revoked, "via": "cli"})
        await security_event("password_reset", user=admin,
                             details={"via": "cli", "target_user_id": admin["id"],
                                      "target_username": "admin",
                                      "sessions_revoked": revoked,
                                      "api_keys_revoked": keys_revoked})
        label = "ADMIN PASSWORD RESET"

    creds_file.write_text(f"Username: admin\nPassword: {password}\n")
    creds_file.chmod(0o600)
    logger.warning(f"{label}. Credentials saved to: {creds_file}")
    print(f"\n{'='*50}")
    print(label)
    print(f"Username: admin")
    print(f"Credentials saved to: {creds_file}")
    print("IMPORTANT: Read and delete this file after noting the password!")
    print(f"{'='*50}\n")
    if label == "ADMIN PASSWORD RESET":
        print("NOTE: restart the portal service to also close WebSocket sessions "
              "(such as terminals) that were already open.\n")

    # Create default services if none exist
    services = await db.get_all_services()
    if not services:
        await db.create_service(
            name="Local Shell", path="/shell", plugin="terminal",
            host="localhost", port=0, config={},
            required_scopes=["admin"], icon="terminal",
            service_type="proxy", display_name="Local Shell",
            description="Admin local terminal access"
        )
        logger.info("Default Local Shell service created")
        print("Default service created: Local Shell")

    await db.close()


async def add_service_cli(
    name: str,
    path: str,
    host: str,
    plugin: str = "terminal",
    port: int = 0,
    scopes: str = ""
) -> None:
    """Add a service via CLI."""
    await db.connect()

    scope_list = [s.strip() for s in scopes.split(",") if s.strip()] if scopes else []
    service_id = await db.create_service(
        name=name,
        path=path,
        plugin=plugin,
        host=host,
        port=port,
        required_scopes=scope_list
    )
    print(f"Service '{name}' created with ID {service_id}")
    print(f"  Path: {path}")
    print(f"  Plugin: {plugin}")
    print(f"  Host: {host}")
    print(f"  Port: {port or 'N/A'}")
    print(f"  Required scopes: {scope_list or ['*']}")

    await db.close()


async def list_services_cli() -> None:
    """List all services via CLI."""
    await db.connect()

    services = await db.get_all_services()
    if not services:
        print("No services configured.")
    else:
        print(f"\n{'ID':<4} {'Name':<20} {'Plugin':<12} {'Path':<15} {'Host':<20} {'Port':<6} {'Scopes'}")
        print("-" * 100)
        for s in services:
            scopes = ",".join(s["required_scopes"]) or "*"
            host = s.get("host", "") or "localhost"
            port = s.get("port", 0) or "-"
            plugin = s.get("plugin", "tcp_tunnel")
            print(f"{s['id']:<4} {s['name']:<20} {plugin:<12} {s['path']:<15} {host:<20} {str(port):<6} {scopes}")

    await db.close()


def show_invite_code() -> None:
    """Show current daily invite code."""
    code = get_daily_invite_code()
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")

    # Log securely (code is time-based so less sensitive than password)
    logger.info(f"Daily invite code requested for {today}")

    print(f"\n{'='*50}")
    print("OPEN RELAY PORTAL - DAILY INVITE CODE")
    print(f"{'='*50}")
    print(f"Date:    {today}")
    print(f"Code:    {code}")
    print(f"Expires: {today} 23:59:59 UTC")
    print(f"{'='*50}")
    print("\nUsers can register at POST /api/register with:")
    print('  {"username": "...", "password": "...", "invite_code": "<code>"}')
    print(f"{'='*50}\n")


async def set_admin_cli(username: str, remove: bool = False) -> None:
    """Set or remove admin status for a user."""
    await db.connect()
    secevents.log.bind(db)      # command-line process: events are written directly

    user = await db.get_user_by_username(username)
    if not user:
        print(f"Error: User '{username}' not found")
        await db.close()
        return

    action = "Removing" if remove else "Granting"
    new_status = 0 if remove else 1

    if user["is_admin"] == new_status:
        status_word = "already" if new_status else "not"
        print(f"User '{username}' is {status_word} an admin")
        await db.close()
        return

    new_role = "user" if remove else "admin"
    await db.conn.execute(
        "UPDATE users SET is_admin = ?, role = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
        (new_status, new_role, user["id"])
    )
    await db.conn.commit()
    # Existing sessions carry the old role's scopes; force a fresh login.
    await db.revoke_user_tokens(user["id"])
    await db.revoke_user_api_keys(user["id"])
    await security_event("role_changed", user=user,
                         details={"via": "cli", "target_user_id": user["id"],
                                  "target_username": user["username"],
                                  "old_role": user.get("role") or ("admin" if user.get("is_admin") else "user"),
                                  "new_role": new_role})

    status_word = "removed from" if remove else "added to"
    print(f"User '{username}' has been {status_word} admin group (role={new_role})")
    print("NOTE: restart the portal service to also close WebSocket sessions "
          "that were already open for this user.")

    await db.close()


async def list_users_cli() -> None:
    """List all users."""
    await db.connect()

    async with db.conn.execute(
        "SELECT id, username, is_admin, created_at FROM users ORDER BY id"
    ) as cursor:
        rows = await cursor.fetchall()

    if not rows:
        print("No users found")
        await db.close()
        return

    print(f"\n{'ID':<5} {'Username':<20} {'Admin':<7} {'Created'}")
    print("-" * 60)
    for row in rows:
        admin_str = "Yes" if row["is_admin"] else "No"
        print(f"{row['id']:<5} {row['username']:<20} {admin_str:<7} {row['created_at']}")
    print(f"\nTotal: {len(rows)} users\n")

    await db.close()


def shell_cli(shell: str = None) -> None:
    """Start a local interactive shell."""
    import pty

    shell = shell or os.environ.get("SHELL", "/bin/bash")

    print(f"Starting shell: {shell}")
    print("Type 'exit' to quit.\n")

    try:
        pty.spawn(shell)
    except Exception as e:
        print(f"Error starting shell: {e}")
        sys.exit(1)


def main():
    """Main entry point."""
    import argparse

    parser = argparse.ArgumentParser(description="Open Relay Portal Server")
    subparsers = parser.add_subparsers(dest="command", help="Commands")

    # Serve
    subparsers.add_parser("serve", help="Start the server")

    # Init
    subparsers.add_parser("init", help="Initialize admin user")

    # Add service
    add_svc = subparsers.add_parser("add-service", help="Add a relay service")
    add_svc.add_argument("name", help="Service name")
    add_svc.add_argument("path", help="URL path (e.g., /myservice)")
    add_svc.add_argument("host", help="Target host (e.g., localhost, 192.168.1.100)")
    add_svc.add_argument("--plugin", default="terminal", help="Plugin type: terminal, ssh, vnc, http_proxy, tcp_tunnel")
    add_svc.add_argument("--port", type=int, default=0, help="Target port (e.g., 22 for SSH)")
    add_svc.add_argument("--scopes", default="", help="Required scopes (comma-separated)")

    # List services
    subparsers.add_parser("list-services", help="List all relay services")

    # Show invite code
    subparsers.add_parser("invite-code", help="Show current daily invite code")

    # Set admin status
    set_admin = subparsers.add_parser("set-admin", help="Set or remove admin status for a user")
    set_admin.add_argument("username", help="Username to modify")
    set_admin.add_argument("--remove", action="store_true", help="Remove admin status instead of granting it")

    # List users
    subparsers.add_parser("list-users", help="List all users")

    # Setup wizard
    subparsers.add_parser("setup", help="Interactive setup wizard")

    # Install MediaMTX
    subparsers.add_parser("install-mediamtx", help="Download and install MediaMTX streaming server")

    # Install fail2ban (optional host hardening)
    f2b = subparsers.add_parser("install-fail2ban", help="Install fail2ban with an SSH jail (optional, Debian/Ubuntu)")
    f2b.add_argument("--ignore-ip", action="append", default=[], metavar="IP",
                     help="IP or CIDR that is never banned (repeatable; include your own)")

    # Check updates
    subparsers.add_parser("check-updates", help="Check for available updates")

    # List snapshots
    subparsers.add_parser("list-snapshots", help="List portal snapshots")

    # Create snapshot
    subparsers.add_parser("create-snapshot", help="Create a manual portal snapshot")

    # Consistent database copy (safe while the portal is running)
    backup_db = subparsers.add_parser("backup-db", help="Write a consistent copy of the database to a 0600 file")
    backup_db.add_argument("--out", default=None, metavar="PATH",
                           help="Output file (default: backups/portal-db-<timestamp>.db)")

    # Backup archive (database + restore keys) and restore into an empty directory
    subparsers.add_parser("backup-archive", help="Write a backup archive (database, .env, salt, invite code) to backups/archives/")
    restore_cmd = subparsers.add_parser("restore-archive", help="Unpack a backup archive into an EMPTY directory after verifying it")
    restore_cmd.add_argument("archive", help="Path of the .tar.gz archive")
    restore_cmd.add_argument("--into", required=True, metavar="DIR", help="Empty target directory (created if missing)")

    # Lift IP blocks without the web UI (server stopped; no migrations are run)
    unblock_cmd = subparsers.add_parser("unblock", help="Remove the IP block(s) for one address from the database (run with the server stopped)")
    unblock_cmd.add_argument("ip", help="IPv4 or IPv6 address")
    subparsers.add_parser("clear-bans", help="Remove every IP block from the database (run with the server stopped)")
    subparsers.add_parser("cf-ranges-reset", help="Forget the saved Cloudflare range list so the built-in one is used (run with the server stopped)")

    # Update component
    update_cmd = subparsers.add_parser("update", help="Apply an update to a component")
    update_cmd.add_argument("--component", required=True,
                            choices=["portal", "pip", "mediamtx", "system"],
                            help="Component to update")
    update_cmd.add_argument("--version", default=None, help="Target version (optional)")

    args = parser.parse_args()

    if args.command is None:
        parser.print_help()
        return
    elif args.command == "serve":
        server = PortalServer()
        asyncio.run(server.run())
    elif args.command == "init":
        asyncio.run(init_admin_user())
    elif args.command == "add-service":
        asyncio.run(add_service_cli(args.name, args.path, args.host, args.plugin, args.port, args.scopes))
    elif args.command == "list-services":
        asyncio.run(list_services_cli())
    elif args.command == "invite-code":
        show_invite_code()
    elif args.command == "set-admin":
        asyncio.run(set_admin_cli(args.username, args.remove))
    elif args.command == "list-users":
        asyncio.run(list_users_cli())
    elif args.command == "setup":
        from setup import run_setup_wizard
        run_setup_wizard()
    elif args.command == "install-mediamtx":
        from setup import install_mediamtx
        success = install_mediamtx()
        sys.exit(0 if success else 1)
    elif args.command == "install-fail2ban":
        from setup import install_fail2ban
        sys.exit(0 if install_fail2ban(args.ignore_ip) else 1)
    elif args.command == "check-updates":
        asyncio.run(update_manager._cli_check_updates())
    elif args.command == "list-snapshots":
        async def _list_snaps():
            snaps = await update_manager.list_snapshots()
            if not snaps:
                print("No snapshots found.")
                return
            print(f"{'ID':<25}  {'Version':<15}  {'Created':<30}  {'Size':<10}  Reason")
            print("-" * 100)
            for s in snaps:
                print(f"{s.get('id',''):<25}  {s.get('version',''):<15}  "
                      f"{s.get('created_at',''):<30}  {s.get('size_human',''):<10}  "
                      f"{s.get('reason','')}")
        asyncio.run(_list_snaps())
    elif args.command == "create-snapshot":
        async def _create_snap():
            print("Creating snapshot...")
            snap = await update_manager.create_snapshot(reason="manual-cli")
            print(f"Snapshot created: {snap['id']} (version: {snap['version']}, size: {snap['size_human']})")
        asyncio.run(_create_snap())
    elif args.command == "backup-db":
        try:
            _path, _size, _result = update_manager.backup_database(args.out)
        except Exception as e:
            print(f"backup-db failed: {e}", file=sys.stderr)
            sys.exit(1)
        if _result != "ok":
            print(f"WARNING: integrity_check returned: {_result}", file=sys.stderr)
        print(_path)
        sys.exit(0 if _result == "ok" else 1)
    elif args.command == "backup-archive":
        try:
            _cfg = backup_manager.read_config_sync()
            _version = asyncio.run(update_manager._get_portal_version())
            _info = backup_manager.create_archive(None, _version, _cfg["keep"], _cfg["extra_dir"])
        except Exception as e:
            print(f"backup-archive failed: {e}", file=sys.stderr)
            sys.exit(1)
        if _info.get("extra_error"):
            print(f"WARNING: copy to the extra destination failed: {_info['extra_error']}", file=sys.stderr)
        print(_info["path"])
    elif args.command == "restore-archive":
        try:
            _res = backup_manager.restore_archive(args.archive, args.into)
        except Exception as e:
            print(f"restore-archive failed: {e}", file=sys.stderr)
            sys.exit(1)
        print(f"Restored into {_res['into']}: {', '.join(_res['files'])}")
        print(f"Archive made by portal version {_res['portal_version']} at {_res['created_at']}.")
        for _w in _res["warnings"]:
            print(f"WARNING: {_w}", file=sys.stderr)
        print("Nothing in the live installation was changed. To use the restored data, put the same portal")
        print("release in a fresh directory, copy these files into it, fix the paths and port listed above in")
        print(".env, and start it there. See 'Backups and Rollback' in the README.")
    elif args.command == "unblock":
        import ban_cli
        sys.exit(ban_cli.unblock(args.ip, Config.DATABASE_PATH))
    elif args.command == "clear-bans":
        import ban_cli
        sys.exit(ban_cli.clear_bans(Config.DATABASE_PATH))
    elif args.command == "cf-ranges-reset":
        import ban_cli
        sys.exit(ban_cli.cf_ranges_reset(Config.DATABASE_PATH))
    elif args.command == "update":
        async def _run_update():
            print(f"Starting update: {args.component}" + (f" version {args.version}" if args.version else ""))
            job_id = await update_manager.start_apply(args.component, args.version)
            print(f"Job started: {job_id}")
            # Poll until done
            import time as _time
            while True:
                job = update_manager.get_job(job_id)
                if not job:
                    print("Job not found")
                    break
                for line in job["log"]:
                    print(line)
                job["log"].clear()
                if job["status"] != "running":
                    print(f"\nJob {job['status']}.")
                    break
                await asyncio.sleep(1)
        asyncio.run(_run_update())
    else:
        parser.print_help()


if __name__ == "__main__":
    main()
